INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (99, 35, NULL, 55, '<p style=\"margin:0\">Selamat siang pak, Mohon izin menjawab pak terkait dengan beberapa hal yang perlu di diskusikan,</p><p style=\"margin:0\">1. </p><p style=\"margin:0\">-Setelah melakukan studi literatur sebelumnya, saya menemukan bahwa industri briket biomassa belum memiliki sistem kontroling dan monitoring , walaupun terdapat beberapa industri yang menggunakan PLC sebagai sistem kontroling saja. Maka dari itu, Tujuan lebih rinci dari penelitian ini ialah merancang sebuah produk software untuk sistem kontroling dan monitoring pada sebuah alat pembuatan briket biomassa, dimulai dari pembuatan kontrol PLC dengan mempertimbangkan beberapa hal dalam penggunaan sensor dan aktuator serta lingkungan kerja, pembuatan sistem SCADA/HMI, dan yang terakhir adalah pengintegrasian IIoT sehingga kegiatan industri dapat dilakukan secara \"remote\", hal tersebut dilakukan dengan menggunakan beberapa software sebagai pendukung seperti penggunaan software kontrol PLC=CX-programmer, SCADA / HMI = EasyBuilder Pro, dan IIoT = Sebuah web app, sehingga dengan terciptanya sebuah sistem tersebut diharapkan dapat memberi gambaran/referensi bagi pada pelaku industri briket biomassa.&nbsp;</p><p style=\"margin:0\">-Software yang menjadi fokus utama disini adalah perancangan sistem kontroling &amp; monitoring PLC-SCADA, di lain sisi IIoT hanya menjadi sebuah pendukung sistem \"remote\" sehingga penelitian ini akan relevan pada era industri 4.0.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">2. Baik pak, berikut beberapa alasan mengambil topik tersebut setelah dilakukan studi literatur lanjutan beberapa hari kebelakang ini:</p><p style=\"margin:0\">- Kurangnya penerapan sistem otomasi pada alat pembuatan briket biomassa di era industri 4.0</p><p style=\"margin:0\">- Potensi industri briket biomassa dengan melihat Permen ESDM dalam hal co-firing biomassa pada PLTU</p><p style=\"margin:0\">- Pengurangan limbah pertanian melihat indonesia merupakan negara agraris&nbsp;</p>', '2023-10-12 07:03:04', '2023-10-12 07:03:04');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (100, 5, NULL, 16, '<p style=\"margin:0\">Izin menyampaikan, saya akan menambahkan hasil rekaman untuk dilakukan pendeteksian yang akan ditampilkan dengan cara diunggah melalui web dengan menggunakan <i>library streamlit</i> agar bisa menampilkan jumlah kendaraan. Dan menambahkan pendeteksian di waktu malam hari untuk jenis kendaraan mobil, bus, dan truk. Meskipun kendaraan tersebut hanya sebagian kecil di jalan tetapi menyebabkan kecepatan bergergak lebih lambat. Sehingga, akan mempengaruhi kendaraan yang lebih kecil dan juga dengan mengetahui karakteristik jenis kendaraan yang berbeda dapat menjadi acuan dasar untuk merancang geometrik jalan. Untuk meningkatkan akurasi, maka saya akan mengambil dan menambahkan dataset di pagi hari dan malam hari untuk jenis kendaraan berbeda.&nbsp;<br></p>', '2023-10-12 07:34:48', '2023-10-12 07:34:48');
