INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (148, 107, NULL, 14, '<p style=\"margin:0\">1. Kenapa harus lemari? kenapa tidak pintu utama untuk menjaga keamanan dari garda depan</p><p style=\"margin:0\">2. Pada studi litelatur dan masalah belum mensitasi sumber referensi<br>3. format referensi belum sesuai format IEEE<br>4. Tambahkan diagram blok pada karakteristik produk</p>', '2023-10-13 14:41:55', '2023-10-13 14:41:55');
