INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (331, 125, NULL, 91, '<p style=\"margin:0\"><span style=\"color: rgb(55, 65, 81); font-family: Söhne, ui-sans-serif, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, &quot;Helvetica Neue&quot;, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; white-space-collapse: preserve; background-color: rgb(247, 247, 248);\">Meskipun ada bagian \"Referensi\" di akhir halaman, tampaknya daftar pustaka belum lengkap. Pastikan untuk menyertakan semua sumber yang Anda kutip dalam proposal Anda.</span><br></p>', '2023-10-19 16:09:09', '2023-10-19 16:09:09');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (332, 125, NULL, 91, '<p style=\"margin:0\"><span style=\"color: rgb(55, 65, 81); font-family: Söhne, ui-sans-serif, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, &quot;Helvetica Neue&quot;, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; white-space-collapse: preserve; background-color: rgb(247, 247, 248);\">Anda perlu memberikan penjelasan teknis yang lebih rinci mengenai bagaimana sistem Anda bekerja, terutama bagian kontrol bluetooth dan mikrokontroller serta IoT jika menggunakan teknologi tersebut.</span><br></p>', '2023-10-19 16:10:35', '2023-10-19 16:10:35');
