INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (351, 84, NULL, 94, '<p style=\"margin:0\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">Waalaikumussalam wr wb,</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">File proposal&nbsp;yang telah direvis&nbsp;ada sedikit peninggkatan&nbsp;namun belum menjawab beberapa point revisi sebelumnya, diantaranya:</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">1. Permasalahan hanya terbatas pada masalah sosial yang terjadi. Tidak eksplisit menjelaskan permasalahan secara teknikal yang ada dengan memberikan scientific contribution yang lebih dari riset terdahulu pada topik tersebut!&nbsp;Untuk lebih memudahkan dalam hal ini, coba jawab parameter kuantitatif apa yang penulis improve dari sistem yang mirip seperti ini dari rujukan yang bereputasi!</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">2. Ide ini sudah banyak yang mengkaji, diantaranya:</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">DOI 10.1088/1742-6596/978/1/012111</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">doi:10.1088/1757-899X/1084/1/</span><wbr style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">012122</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">10.1016/j.procs.2019.08.159</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><a href=\"https://doi.org/10.18494/SAM3811\" target=\"_blank\" data-saferedirecturl=\"https://www.google.com/url?q=https://doi.org/10.18494/SAM3811&amp;source=gmail&amp;ust=1697893502584000&amp;usg=AOvVaw2LbOFLelCGzb-Q1xyh2VmV\" style=\"color: rgb(17, 85, 204); font-family: Arial, Helvetica, sans-serif; font-size: small; background-color: rgb(255, 255, 255);\">https://doi.org/10.18494/<wbr>SAM3811</a><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">Tidak ditemukan penjelasan secara eksplisit inovasi, kelebihan dan novelty apa dari ide yang diajukan!</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">3.&nbsp;Apa parameter kuantitatif yang akan diimprove? berapa targetnya? karena di akhir nanti pastinya anda akan simpulkan bahwa sistem anda sebisa mungkin lebih unggul dari sistem yang sudah ada, unggul dari segi apa? harus bisa terukur!</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">Apabila masih belum faham pertanyaan atau instruksi apa yang harus diperbaikinya, boleh coba kita set untuk diskusi&nbsp;luring sehingga lebih jelas.</span><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><br style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\"><span style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">Wassalam,</span><br></p>', '2023-10-20 13:05:19', '2023-10-20 13:05:19');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (352, 84, NULL, 205, '<div dir=\"ltr\" style=\"color: rgb(34, 34, 34); font-family: Arial, Helvetica, sans-serif; font-size: small;\">Assalamualaikum wr. wb.<div><br></div><div>Selamat Pagi salam sejahtera.</div><div>Reivisi&nbsp;3 sudah di selesaikan&nbsp;sesuai dengan koreksi dari bapak dengan memberikan parameter kuantitatif yang akan di improve. Ada beberapa penambahan dan penyesuaian lagi pada revisi 3 ini, dengan itu maka saya Izin mengirim Revisi Proposal Seminar dengan link berikut <a href=\"https://drive.google.com/file/d/1Pt9ZGVWyuQIXg8zRjmF8HOS0ETb__BVC/view?usp=share_link\" target=\"_blank\">Revisi 3</a>.</div><span class=\"im\" style=\"color: rgb(80, 0, 80);\"><div><br></div><div>Terimakasih atas perhatiannya. Wassalamualaikum wr. wb</div><div><br></div><div>Salam hangat&nbsp;</div><font color=\"#888888\"><font color=\"#888888\">Muhammad Farhan Nurpratama</font></font></span></div>', '2023-10-21 01:26:14', '2023-10-21 01:26:14');
