INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (380, 116, NULL, 229, 'izin jawab pak, pertama terkait media sosial saya revisi penggunaan diksi nya dengan konten digital, karena jika membahas media sosial maka kita harus meneliti juga objek yang bersangkutan tapi untuk system yang saya buat ini lebih cenderung ke perancangan dan untuk tahapan pertama ini tidak akan di kaitkan ke media sosial dulu karena dikhawatirkan menjadi suatu hal yang tidak bisa saya tangani jadi saya memutuskan untuk cenderung ke perancangan system ini dengan subjek percobaan diambil dari konten digital yang ada di internet bukan lagi difokuskan ke media sosial', '2023-10-24 02:26:04', '2023-10-24 02:26:04');
