INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (825, 419, NULL, 1, '<p style=\"margin:0\">Apa hubungannya suhu, kelembaban dll dengan lansia?</p>', '2024-04-24 11:26:41', '2024-04-24 11:26:41');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (828, 419, NULL, 403, '<p style=\"margin:0\">mohon maaf sebelumnya saya sudah menjawab di telegram.&nbsp;</p><p style=\"margin:0\">Mohon maaf izin menjawab pak hubungan suhu, kelembaban dan kebisingan dengan lansia itu pada kenyamanan lingkungan ruangan lansia pak, pada suhu mungkin tingkat tinggi dan rendahnya suhu kamar lansia dapat mengganggu kulitas istirahat dan suhu juga dapat memperburuk kondisi medis tertentu. Untuk kelembaban&nbsp; tingkat kelembaban yang tidak terkontrol akan menyebabkan berbagai masalah kesehatan karena kamar tidur lansia memiliki tingkat kelembaban yang tinggi, kebetulan dalam topik ini saya mengarah pada latar belakang lansia yang menderita gejala stroke yang sulit untuk melakukan aktivitas. untuk hubungan kebisingan pada sekitar lingkungan kamar yang dapat mengakibatkan terganggunya pemulihan karena gangguan tidur juga pada penderita stroke berpengaruh pada tingkat stress yang dapat mempengaruhi tekanan darah. untuk hubungan suhu, kelembaban dan kebisingan serta tombol bantuan untuk menciptakan ruangan yang nyaman pada tidur dan pemulihan lansia yang menderita gejala stroke. mohon maaf pak terimakasih<br></p>', '2024-04-24 16:37:51', '2024-04-24 16:37:51');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (829, 417, NULL, 1, '<p style=\"margin:0\">Your proposal submission has been received. \n                        Please be patient, the assignment of reviewer/supervisor is processing</p>', '2024-04-24 22:55:09', '2024-04-24 22:55:09');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (830, 392, NULL, 14, '<p style=\"margin:0\">Cat: <br>-Voice Interaction dan Disabilitasnya bagaimana? Disabilitas yg dituju apakah spesifik atau general?</p><p style=\"margin:0\">-Pada bagian latar belakang belum muncul permasalahan yang dihadapinya untuk solusi yg ditawarkan</p><p style=\"margin:0\">- State of The Artnya diperbaiki</p>', '2024-05-02 12:17:17', '2024-05-02 12:17:17');
