INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (953, 482, NULL, 14, '<p style=\"margin:0\">urgensi dari penelitian ini apa? apakah di alat2 anneling furnace blm ada kontrol suhu?</p>', '2024-09-19 13:21:13', '2024-09-19 13:21:13');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (954, 451, NULL, 14, '<p style=\"margin:0\">alat ini dirancang untuk digunakan penyedia layanan air?<br>sensor yg digunakan hanya 1? Tolong tambahkan beberapa sensor yg berkaitan dengan data yg dapat diakses oleh user dari PDAM rumah (contoh: data konsumsi air dsb). Sehingga bisa menggunakan multi gateway sensor.</p>', '2024-09-19 13:33:46', '2024-09-19 13:33:46');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (955, 460, NULL, 14, '<p style=\"margin:0\">Bagaimana tahu jenis hama yg ada didaerah tersebut?</p>', '2024-09-19 13:38:24', '2024-09-19 13:38:24');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (956, 460, NULL, 14, '<p style=\"margin:0\">proposal tidak sesua dengan format, banyak bagian yg belum disampaikan</p>', '2024-09-19 13:39:33', '2024-09-19 13:39:33');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (957, 460, NULL, 14, '1. latar belakang belum tergambar jelas.<br>2. Jenis hama apa yang akan dijadikan objek? hama secara general atau hama tertentu? Bagaimana cara mengetahui jenis hama tersebut dari sisi sistem?<br><br>', '2024-09-19 13:41:08', '2024-09-19 13:41:08');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (958, 486, NULL, 14, '<p style=\"margin:0\">1. Ini proposal skripsi atau stoir?<br>2.&nbsp;&nbsp;<span style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;, serif; font-size: 12pt; font-weight: 700; white-space-collapse: preserve;\">Pendekatan pemecahan masalah </span><span style=\"color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;, serif; font-size: 12pt; white-space-collapse: preserve;\"> blm ada sitasi terkait penelitian yg relevan.\n3. </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); font-weight: 700; font-style: italic; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">State of the art</span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); font-weight: 700; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\"> dan kebaruan </span><span style=\"font-size: 12pt; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; vertical-align: baseline; white-space-collapse: preserve;\">blm jelas, apa kontribusi penelitian ini jika dibandingkan dengan penelitian yg relevan sebelumnya\n4. alat yg akan dibuat blm tergambarkan dengan baik pada ringkasan ataupun state of the art.</span></p>', '2024-09-19 13:46:42', '2024-09-19 13:46:42');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (959, 486, NULL, 14, '<p style=\"margin:0\">penelitian ini menggunakan alat apa saja? sensor yang digunakan untuk self diagnosis pada smoke detector apa? Indikator apa saja yang ada danharus dicek pada alat smoke detector?</p>', '2024-09-19 13:47:43', '2024-09-19 13:47:43');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (960, 459, NULL, 14, '<p style=\"margin:0\">1. pada latar belakang sitasi dari data masih kurang<br>2. state of the art atau kontribusi dari penelitian ini blm ada<br>3.&nbsp; data curah hujan didapatkan darimana?</p>', '2024-09-19 13:53:11', '2024-09-19 13:53:11');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (961, 470, NULL, 14, '<p style=\"margin:0\">1. Daftar pustaka blm dimasukan<br>2. Pendekatan masalah masih kurang, silahkan kaji mengenai metode atau prinsip kerja yang akan digunakan dalam pengolahan data dari data throttle menjadi suara dengan mengubah2 frekuensi kerapatan suara sesuai dengan tarikan throtlle.<br>3. diringkasan diperdetail lagi penjelasannya, serta tambahan sistem ioT untuk mengubah jenis suara yang dihasilkan</p>', '2024-09-19 13:56:55', '2024-09-19 13:56:55');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (962, 466, NULL, 14, '<p style=\"margin:0\"><b>1. Pendekatan Pemecahan Masalah </b>tambahan sitasi dari penelitian sebelumnya yg relevan<br>2.&nbsp;<b>State of Art dan Kebaruan </b>belum terlihat, coba bandingkan dengan sitasi penelitian terkait sebelum2nya</p>', '2024-09-19 14:16:46', '2024-09-19 14:16:46');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (963, 490, NULL, 14, '<p style=\"margin:0\">1.&nbsp;<b>Latar Belakang dan Rumusan Masalah Yang Akan Diteliti&nbsp;</b>&nbsp;blm muncul, masalah apa yang ada pada proses fermentasi sehingga dibutuhkan alat ini?<br>2.&nbsp;<b>Pendekatan pemecahan masalah </b>tambahkan lagi sitasi dari penelitian yg relevan sebelumnya.<br>3. Ringkasan disebutkan otomatis, alat ini apakah monitoring saja atau ada alat yg digerakan atau dikontrol?</p>', '2024-09-19 14:24:17', '2024-09-19 14:24:17');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (964, 472, NULL, 14, '<p style=\"margin:0\">1.&nbsp;<span style=\"color: rgb(0, 0, 0); font-family: Cambria, serif; font-size: 12pt; white-space-collapse: preserve;\">Pendekatan Pemecahan Masalah tambahkan lagi sitasinya terkait penelitian sebelumnya yg relevan\n2. Keterbaruannya apa? moniroting? apa yang dimonitoring? dan apakah ini penelitiannya termasuk membuat alat baggingnya?</span></p>', '2024-09-19 14:32:01', '2024-09-19 14:32:01');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (965, 472, NULL, 14, '<p style=\"margin:0\">ringkasan alat lebih diperjelas</p>', '2024-09-19 14:32:54', '2024-09-19 14:32:54');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (966, 478, NULL, 14, '<p style=\"margin:0\">akses tidak bisa dibuka.<br><br>dari hasil diskusi terakhir ttg topik ini, jadi urgensinya apa? monitoring tekanan ban ini dilakukan pada saat apa?</p>', '2024-09-19 14:36:42', '2024-09-19 14:36:42');
