INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (968, 476, NULL, 14, '<p style=\"margin:0\">1.&nbsp;Pendekatan pemecahan masalah jelaskan tentang penelitian sebelumnya yg relevan dengan topik<br>2.&nbsp;&nbsp;State of the art keterbaruan jelaskan keterbaruannya apa secara detail. Apakah termasuk membuat alat pemotongnya juga?</p>', '2024-09-19 14:44:55', '2024-09-19 14:44:55');
