INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1005, 459, NULL, 464, 'Assalamualaikum warahmatullahi wabarakatuh<br>Selamat siang bapak/ibu dosen sebelumnya mohon maaf jika mengganggu waktunya saya Luthfi Maulana dari Prodi PTOIR dengan NIM 2102882 sebelumnya saya mendapatkan pemberitahuan dari sistem terkait dengan beberapa hal yang harus di perbaiki pada proposal saya,terkait dengan hal tersebut saya telah memperbarui link dokumen gdrive pada proposal saya.<br><br>Sekian yang ingin saya sampaikan,mohon maaf apabila ada kesalahan dalam penyusunan kalimat.<br>Wassalamualaikum warahmatullahi wabarakatuh', '2024-09-22 12:43:55', '2024-09-22 12:43:55');
