INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1011, 478, NULL, 456, '<p style=\"margin:0\">Akses Drive Sudah di Perbaiki :&nbsp;https://docs.google.com/document/d/1IkKWaqCHOwTJJkQinb7jVMR3fhHvOzCK/edit?usp=sharing&amp;ouid=117979234640088175250&amp;rtpof=true&amp;sd=true</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Urgensi nya itu unutkmengeksplorasi TPMS baru untuk mengatasi masalah yang ada di kendaraan dapat mengatur tekanan ban dan tekanan angin secara tidak langsung yang dapat di monitoring di LCD Kendaraan. Monitoring tekanan ban dilakukan pada saat keadaan kendaraan itu hidup.</span><br></p>', '2024-09-22 18:10:25', '2024-09-22 18:10:25');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1012, 472, NULL, 474, '<p style=\"margin:0\">Assalamualaikum bu, mohon maaf update revisi malam. Untuk proposal STOIR sudah saya revisi bu yang harus direvisi. Sekali lagi mohon maaf update dan komentar pada malam hari bu</p>', '2024-09-22 21:10:23', '2024-09-22 21:10:23');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1014, 482, NULL, 455, '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; font-style: normal; font-variant-caps: normal; font-stretch: normal; font-size: 12px; line-height: normal; font-family: &quot;.SF UI&quot;; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-variant-emoji: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal;\"><span style=\"font-family: &quot;.SFUI-Regular&quot;;\">urgensi dari penelitian ini ialah untuk mengoptimalkan proses annealing dalam meningkatkan kekerasan logam dengan mengendalikan laju suhu pada mesin, untuk mecegah terjadinya NG pada material logam, dalam alat annealing sudah ada kontrol suhu dengan menggunakan thermocouple tipe K</span></p>', '2024-09-23 11:02:33', '2024-09-23 11:02:33');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1015, 482, NULL, 455, '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; font-style: normal; font-variant-caps: normal; font-stretch: normal; font-size: 12px; line-height: normal; font-family: &quot;.SF UI&quot;; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-variant-emoji: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal;\"><span style=\"font-family: &quot;.SFUI-Regular&quot;;\">maka dari itu digunakanlah matlab/simulink untuk menentukan nilai PID yang baik dalam proses annealing</span></p>', '2024-09-23 11:03:12', '2024-09-23 11:03:12');
