INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1018, 486, NULL, 14, '2.&nbsp;&nbsp;<span style=\"font-size: 12pt; white-space-collapse: preserve; color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;, serif; font-weight: 700;\">Pendekatan pemecahan masalah </span><span style=\"font-size: 12pt; white-space-collapse: preserve; color: rgb(0, 0, 0); font-family: &quot;Times New Roman&quot;, serif;\"> blm ada sitasi terkait penelitian yg relevan.\n3. </span><span style=\"font-size: 12pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); font-weight: 700; font-style: italic; vertical-align: baseline;\">State of the art</span><span style=\"font-size: 12pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); font-weight: 700; vertical-align: baseline;\"> dan kebaruan </span><span style=\"font-size: 12pt; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-variant-position: normal; white-space-collapse: preserve; font-family: &quot;Times New Roman&quot;, serif; color: rgb(0, 0, 0); vertical-align: baseline;\">blm jelas, apa kontribusi penelitian ini jika dibandingkan dengan penelitian yg relevan sebelumnya\n4. alat yg akan dibuat blm tergambarkan dengan baik pada ringkasan ataupun state of the art.\n\n\n<span style=\"color: rgb(33, 37, 41); font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; whit