INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1082, 484, NULL, 93, '<p style=\"margin:0\">- telepon seluler yang digunakan oleh tunanetra memiliki spesifikasi khusus, seperti telepon seluler yang memiliki keypad, atau button.</p><p style=\"margin:0\">- topik yang diajukan telah dipublikasi oleh beberapa orang, baik publikasi internasional atau nasional.</p><p style=\"margin:0\">1. Rahmad C, ST M K, Rawansyah MP, Rochastu TK. Object Detection System Sebagai Alat Bantu Mendeteksi Objek Sekitar untuk Penyandang Tunanetra.</p><p style=\"margin:0\">2.&nbsp;<a href=\"https://link.springer.com/article/10.1007/s11042-016-3617-6\" target=\"_blank\">https://link.springer.com/article/10.1007/s11042-016-3617-6</a></p><p style=\"margin:0\">3.&nbsp;<a href=\"https://sci-hub.ru/10.1007/978-3-030-37218-7_92\" target=\"_blank\">https://sci-hub.ru/10.1007/978-3-030-37218-7_92</a></p><p style=\"margin:0\">- tidak terlihat state of the art dan kebaruan dari topik yang diajukan</p>', '2024-09-26 13:04:31', '2024-09-26 13:04:31');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1083, 486, NULL, 14, '<p style=\"margin:0\">sitasi mengenai penelitian yang revelan maish kurang</p>', '2024-09-26 13:05:13', '2024-09-26 13:05:13');
