INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1086, 460, NULL, 93, '<ul><li>penulisan proposal perlu diperbaiki. gunakan kata-kata yang sesuai untuk penulisan akademik.</li><li>studi literatur perlu dilakukan secara mendalam untuk memperoleh state of the art dari topik yang diajukan</li><li>terdapat sitasi yang tidak dicantumkan pada bagian referensi</li><li><span style=\"color: inherit; font-size: 1rem;\">apakah penggunaan PIR akan efektif untuk digunakan pada seluruh kondisi cuaca (hujan, panas, dsb)?</span></li><li>\"Manfaat penelitian adalah membantu meringankan kerja petani dalam menangani&nbsp;<span style=\"color: inherit; font-size: 1rem;\">masalah hama burung di sawah, meningkatkan produktivitas kerja petani dan hasil panen.\"..&nbsp; hasil penelitian referensi [3] tidak memberikan hasil kerja petani dan hasil panen.</span></li><li><span style=\"color: inherit; font-size: 1rem;\">topik ini sudah ada yang membuatnya. (</span>https://www.researchgate.net/profile/Robby-Endra/publication/347690066_Analisis_Cara_Kerja_Sensor_Ultrasonic_Dan_Motor_Servo_Menggunakan_Mikrokontroler_Arduino_Uno_Untuk_Pengusir_Hama_Disawah/links/5fe32604299bf140883796a7/Analisis-Cara-Kerja-Sensor-Ultrasonic-Dan-Motor-Servo-Menggunakan-Mikrokontroler-Arduino-Uno-Untuk-Pengusir-Hama-Disawah.pdf)</li><li><br></li></ul>', '2024-09-26 17:21:26', '2024-09-26 17:21:26');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1087, 461, NULL, 471, '<p style=\"margin:0\">Penjelasan&nbsp;<span style=\"color: inherit; font-size: 1rem;\">mengapa perlu adanya materi&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\"><span lang=\"id\" style=\"font-size: 12pt; line-height: 24px; font-family: Cambria, serif; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;\">Konsentrasi Keahlian Teknik Pengolahan Minyak, Gas dan Petrokimia sudah saya tambahkan ke latar belakang proposal. Selain itu, iya benar, aplikasi ini dikhususkan untuk pembelajaran SMK.</span></span></p>', '2024-09-27 20:57:55', '2024-09-27 20:57:55');
