INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1127, 462, NULL, 472, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh..</p><p style=\"margin:0\">Bapak, izin mengirimkan hasil revisi terbaru. Pada file yang terkini, judul serta bagian pemecahan masalah dan latar belakang juga sudah diperbaiki.&nbsp;&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">File hasil revisi dapat diakses melalui tautan berikut:&nbsp;&nbsp;</p><p style=\"margin:0\">[Nama file: Wira Hadi Kusuma_Proposal STOIR_Revisi_1]</p><p style=\"margin:0\">https://drive.google.com/drive/folders/12333L6RvApCj0D8-0Y6Tn-pL8londa6l</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Mohon kesediaan Bapak untuk memeriksa kembali hasil revisi proposal STOIR saya pak. Terima kasih banyak Pak..&nbsp;&nbsp;</p><p style=\"margin:0\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh..</p>', '2024-10-11 05:42:08', '2024-10-11 05:42:08');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1128, 482, NULL, 455, '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px; font-style: normal; font-variant-caps: normal; font-stretch: normal; font-size: 12px; line-height: normal; font-family: &quot;.SF UI&quot;; font-size-adjust: none; font-kerning: auto; font-variant-alternates: normal; font-variant-ligatures: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-position: normal; font-variant-emoji: normal; font-feature-settings: normal; font-optical-sizing: auto; font-variation-settings: normal;\"><span style=\"font-family: &quot;.SFUI-Regular&quot;;\">baik pak, sebelumnya terimakasih pak, izin kan saya memperkenalkan diri nama saya Ade Nandar Faturachman dengan no NIM 2106502, izin menjawab pak, untuk mesin yang akan saya analisi merupaka mesin annealing heat treatmen dengan 3 metode kelajuan suhu, yang pertama kenaikan, lalu hold (penahanan suhu), dan yang terakhir ialah lahu pendinginan atau quenching, analisis yang akan saya lakukan yaitu melakukan perhitungan nilai PID menggunakan simulink/matlab merujuk pada P&amp;iD mesin dan membandingkan hasilnya dengan nilai PID pada jurnal rujukan yang saya dapatkan, untuk outputnya nanti membandingkan hasil perhitungan simulasi dengan data aktual pada mesin, untuk kenaikan suhu hingga titik suhu ditentukan berapa waktu yang ditempuh, untuk control penahanan suhu berapa jam yang di perlukan dan untuk laju pendinginan hingga titik yang dibtentukan berapa waktunyang diperlukan, outputnya berupa grafik suhu yang ditampilkan pada display hmi dan screen decorder pada mesin, mungkin seperti itu pak.</span></p>', '2024-10-13 01:10:37', '2024-10-13 01:10:37');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1129, 519, NULL, 14, '<p style=\"margin:0\">Your research topic is in review process; \n                    please contact and ask the assigned reviewer to follow up the review process!.</p>', '2024-10-15 10:10:14', '2024-10-15 10:10:14');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1130, 519, NULL, 93, '<p style=\"margin:0\">- beberapa referensi tidak ditemukan dalam google scholar, mohon lampirkan <i>link </i>dari seluruh refensi yang digunakan.</p><p style=\"margin:0\">- perhatikan aturan dalam pembuatan proposal, mulai dari jumlah kata, format sitasi, jumlah kata dalam ringkasan maksimal 300 kata.&nbsp;</p><p style=\"margin:0\">-&nbsp;\"hasil data yang dikumpulkan dari sensor tersebut diproses dan di&nbsp;<span style=\"color: inherit; font-size: 1rem;\">analisis menggunakan teknik pengenalan pola visual yang didasarkan pada algoritma YOLO V10.\" mohon jelaskan bagaimana cara YOLO V10 mampu mengolah data angka hasil pembacaan sensor.</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">- alur gambar yang ditampilkan pada metode penelitian tidak tersusun dengan baik. pada diagram blok yang ditampilkan, langkah apa yang dilakukan setelah, studi literatur, analisis komponen-komponen, pengumpulan data, dan implementasi YOLO V10?&nbsp;</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">- silakan pelajari cara membuat state of the art yang benar.&nbsp;</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">- tambahkan referensi terkait YOLO yang mampu diintegrasikan dengan sensor MQ2.</span></p>', '2024-10-19 04:52:49', '2024-10-19 04:52:49');
INSERT INTO `arsys_discussion` (`id`, `research_id`, `discussion_type`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1131, 523, NULL, 14, '<p style=\"margin:0\">Your research topic is in review process; \n                    please contact and ask the assigned reviewer to follow up the review process!.</p>', '2024-10-21 12:08:49', '2024-10-21 12:08:49');
