INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (1, 1, 55, 12, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah telah melaksanakan Ujian Sidang Pre-defence dengan baik.&nbsp;</p>', '2023-11-24 11:58:25', '2023-12-21 12:03:32');
