INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (66, 1, 12, 26, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense dilaksanakan di hari Rabu tanggal 17 Januari 2024 dihadiri oleh dosen pebimbing yaitu Pak Iwan Kustiawan dan Bu Silmi Ath Thahirah dan dosen penguji yaitu Pak Enjang A. Juanda, Pak Agus Heri, dan Pak Wasimudin Surya<br><br>Adapun catatan dari dosen penguji yaitu:<br>1. mengubah judul dari teknologi menjadi aplikasi<br>2. menambahkan teori dasar pengenalan wajah pada bab 2<br>3. menambahkan paragraf rekomendasi jurnal<br>4. memperbaiki urutan pada sub bab 2<br>5. memperbaiki judul pada tabel<br><br>catatan dari dosen pebimbing yaitu:&nbsp;<br>1. mengubah judul menjadi&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Rancang Bangun Aplikasi Pengenalan Wajah Berbasis Computer\nVision Untuk Meningkatkan Keamanan Penjemputan Siswa<br>2. menambahkan teori dasar pengenalan wajah<br></span></p><p class=\"MsoNormal\"><o:p></o:p></p>', '2024-01-12 11:13:23', '2024-01-19 07:20:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (67, 1, 182, 3, 6, 2, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah telah pre-defense</p>', '2024-01-12 12:49:59', '2024-01-22 16:02:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (68, 1, 42, 26, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tanggal 17Januari 2024. Penguji yang hadir adalah Pak Prof. Jaja Kustija, Pak Bambang Trisno,&nbsp; dan Pak Saripudin. Pembimbing yang hadir adalah Pak Elih Mulyana dan Pak Yadi Mulyadi. Sidang dimulai pukul 08.03 sampai dengan 09.01. Sidang dibuka oleh Pak Elih dan ditutup oleh saya sendiri.<br></p>', '2024-01-12 13:39:55', '2024-01-19 19:52:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (69, 1, 274, 3, 5, 3, 1, 1, 1, '<p style=\"margin:0\">Pahami mengenai project rangkaian TRIAC dan LDR</p><p style=\"margin:0\">Tambahkan penelitian yang relevan di bab 2, kaitkan dengan penelitian yang kamu lakukan</p><p style=\"margin:0\">Subjek penelitian, alasan dipilih 4 subjek penelitian kenapa?</p><p style=\"margin:0\">Tambahkan referensi jurnal di kisi-kisi observasi dan wawancara</p><p style=\"margin:0\">Aspek pjbl tidak terlihat, jelaskan project based, tambahkan modul ajar atau penjelasan project</p><p style=\"margin:0\">Kesalahan konsep, harus ada penjelasan</p>', '2024-01-12 23:03:24', '2024-01-19 03:08:23');
