INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (74, 1, 66, 30, 3, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense terlaksana pada tanggal 19 April 2024, pukul 09.34 - 10.40 di ruangan dosen 12-13 DPTE.</p><p style=\"margin:0\">Kehadiran dosen pembimbing:</p><ol><li>(Tidak hadir) Prof. Dr. Hj. Budi Mulyani, M.Si. : Memiliki kegiatan lain yang harus dihadiri</li><li>(Hadir) Silmi Ath Thahirah Al Azhima, S.T., M.T. : Hadir dan menjadi moderator sidang</li></ol><p style=\"margin:0\">Kehadiran dosen penguji:</p><ol><li>(Hadir) Didin Wahyudin, S.Pd., MT., Ph.D.</li><li>(Hadir) Dr. Erik Haritman, S.Pd., M.T.</li><li>(Tidak hadir) Mariya Al Qibtiya, S.Si., M.T. : Sakit</li></ol><p style=\"margin:0\">Sidang berjalan dengan lancar dengan beberapa masukan dari dosen penguji:</p><ol><li>Buat judul menjadi lebih spesifik pada apa yang diteliti</li><li>Sertakan juga jenis regresi apa yang digunakan dan bagaimana cara menggunakannya</li><li>Hindari overclaim pada riset yang dilakukan</li></ol><p style=\"margin:0\"><br></p>', '2024-04-01 08:51:56', '2024-04-20 23:03:49');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (75, 1, 269, 30, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah telah selesai melaksanakan sidang tertutup pre defense. Dosen penguji hadir seluruhnya, dan ada beberapa revisi pada skripsi saya</p>', '2024-04-02 12:08:10', '2024-04-21 16:17:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (76, 1, 142, 30, 1, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang sudah dilaksanakan, penguji hadir semua.</p>', '2024-04-03 17:48:34', '2024-04-19 14:37:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (77, 1, 94, 30, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang telah dilaksanakan dengan lancar,<br>pembimbing hadir: Wasimudin Surya Saputra, S.T., M.T.<br>penguji hadir :<br>Prof. Dr. H. Jaja Kustija, M.Sc.<br>Dr. Elih Mulyana, M.Si.<br>Dr. Bambang Trisno, MSIE.</p>', '2024-04-07 22:11:01', '2024-04-25 11:34:07');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (78, 1, 82, 30, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Saya sudah melaksanakan sidang skripsi pada pukul 10.00-11.00 dengan dosen penguji yang hadir hanya dua yaitu Bapak Tasma Sucita dan Bapak Maman Somantri, sedangkan Bapak Wawan Purnama tidak hadir</p>', '2024-04-08 11:18:23', '2024-04-19 21:32:06');
