INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (80, 1, 70, 30, 7, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang telah terlaksana dan dosen pembimbing serta semua dosen penguji telah hadir&nbsp;</p>', '2024-04-14 11:15:10', '2024-04-22 12:23:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (81, 1, 258, 30, 4, 1, 1, 1, 1, 'Alhamdulillah sidang berjalan dengan lancar, Pembimbing I berkenan hadir, 2 orang penguji hadir, 1 orang berhalangan hadir. Alhamdulillah, semoga semua selalu diberi kesehatan. Aamiin', '2024-04-16 14:21:46', '2024-04-20 04:42:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (82, 1, 213, 30, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Saya telah melakukan pre-defense pada hari Jumat 19 April 2024&nbsp;</p>', '2024-04-16 15:00:28', '2024-04-20 10:13:05');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (83, 1, 92, 30, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang dibuka oleh Bapak Muhammad Adli Rizqullah pada pukul 09:30 dan ditutup oleh Bapak Muhammad Adli Rizqullah pukul 10:20. Sidang dihadiri oleh semua penguji dan pembimbing.</p><p style=\"margin:0\">terdiri dari 2 sesi, yaitu sesi pertama yaitu presentasi selama 10 menit dan sesi ke dua yaitu tanya jawab selama 40 menit.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bapak Agus Heri adalah, referensi mengenai perbandingan implementasi hardware dan software, memasukan rangkaian AES konvensional dan sumbernya.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bu Siscka Elvyanti adalah untuk memperbaiki kalimat permutasi pada proses subbyte transformation.</p><p style=\"margin:0\">Revisi yang disampaikan oleh Bu Arjuni Budi Pantjawati adalah untuk menggunakan nomor gambar dan tabel pada penjelasannya, memperbaiki gambar Flowchart cara kerja AES, dan memberikan penjelasan mengenai trade off pada sistem apakah masih bisa ditoleransi atau tidak.</p>', '2024-04-16 15:35:03', '2024-04-19 11:49:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (84, 1, 240, 30, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang telah terlaksana dan semua dosen penguji dan dosen pembimbing hadir semua. Terimakasih</p>', '2024-04-17 10:00:48', '2024-04-22 12:05:16');
