INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (133, 1, 426, 47, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 25 Juli pukul 08.00-09.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Bambang Trisno.&nbsp;</p><p style=\"margin:0\">2. Bapak Dr. Elih Mulyana.&nbsp;</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Dalam penyusunan latar belakang dan kesimpulan dianggap terlalu panjang</p><p style=\"margin:0\">2. Disarankan untuk menambahkan cara kerja atau panduan penggunaan Aplikasi Dialux</p>', '2024-07-05 19:49:40', '2024-07-26 13:01:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (134, 1, 338, 51, 2, 3, 1, 1, 1, '<p style=\"margin:0\">sudah mengikuti pre defense pada tanggal 12 juli 2024, dan sudah menyelesaikan revisi dari para penguji</p>', '2024-07-06 06:20:48', '2024-08-12 07:37:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (135, 1, 39, 48, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang skripsi tertutup pada hari jumat, 19&nbsp; Juli 2024 berhasil dilaksanakan dengan lancar. Pada kesempatan sidang kali ini dihadiri oleh :<br>1. Ibu Arjuni Budi sebagai pembimbing sekaligus moderator<br>2. Ibu Tuti Suartini sebagai Penguji 1<br>3. Bapak Wawan Purnama sebagai Penguji 2<br>4. Bapak Agus Heri sebagai Penguji 3</p><p style=\"margin:0\">Notulensi yang didapat pada sidang skripsi ini adalah sebagai berikut:<br>1. Flowchart harus diperbaiki agar lebih sesuai dengan skema sistem yang digunakan.<br>2. Simulasi yang digunakan sebaiknya bersifat \"apple to apple\" bukan berdasarkan rata - rata hasil simulasi.<br>3. Penelitian sifatnya memberikan solusi pada subjek penelitian, dikarenakan penelitian kali ini bersifat simulasi, menyebabkan tidak memberikan solusi langsung pada subjek penelitian.&nbsp;<br>4. Penelitian ini harus melibatkan masyarakat sekitar, dishub, dan pemerintah setempat jika ingin diimplementasikan secara langsung, dikarenakan diharuskan mengubah&nbsp; keadaan lokasi tujuan penelitian.<br>5. Dikarenakan penelitian kali ini dilakukan pada jenjang S1 (Skripsi) menggunakan simulasi saja sudah cukup.<br>6. Disarankan memahami indeks warna untuk pengolahan gambar computer vision.</p><p style=\"margin:0\"><br></p>', '2024-07-06 22:08:05', '2024-08-09 13:22:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (136, 1, 244, 48, 3, 1, 1, 1, 1, '<p style=\"margin:0\"><a href=\"https://drive.google.com/drive/folders/1xeulk_haUw0BkQDPa0udOJA3_vEliWId\" target=\"_blank\">Report</a><br></p>', '2024-07-12 03:39:02', '2024-08-20 10:11:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (137, 1, 301, 48, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah sidang berhasil dilaksanakan dengan dua dosen penguji dikarenakan satu dosen penguji tidak bisa hadir, sidang berakhir dengan beberapa revisi dari penguji yang akan diperbaiki untuk <i>final defense</i> nanti.</p>', '2024-07-12 05:21:52', '2024-07-31 14:31:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (138, 1, 310, 48, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang tertutup, pada tanggal 19 Juli 2024 dengan dosen penguji sebagai berikut:<br>1. Prof. Dr. H. Enjang Akhmad Juanda, M.Pd, M.T.<br>2. Dr. Aip Saripudin, S.Si, M.T.<br>3. Mariya Al Qibtiya, S.Si, M.T.<br>Sidang berakhir dengan beberapa revisi dari dosen penguji yang akan diperbaiki untuk final defense.<br>Terima Kasih.</p>', '2024-07-12 05:27:15', '2024-07-31 14:49:09');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (139, 1, 40, 48, 4, 1, 1, 1, 1, '<p style=\"margin:0\"><a href=\"https://drive.google.com/drive/u/1/folders/17ixzzUUKyYwWdgBOdfcCb0p-IKKNNgxJ\" target=\"_blank\">https://drive.google.com/drive/u/1/folders/17ixzzUUKyYwWdgBOdfcCb0p-IKKNNgxJ</a><br></p>', '2024-07-12 05:46:26', '2024-08-19 15:42:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (140, 1, 352, 48, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Pre defense dilaksanakan pada pagi hari ini pada tanggal 19 Juli 2024 jam 07.00-08.00 di Lab. Elind lt. 5 Gd. A FPTK.&nbsp; Pre defense dilaksanakan dengan baik, namun ada beberapa masukan dari para dosen penguji yaitu perbaikan dalam penulisan, perbaiki hasil pengujian BDV.</p>', '2024-07-12 11:50:10', '2024-07-19 12:48:57');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (141, 1, 255, 48, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang Tertutup Hari Jumat, Tanggal 19 Juli 2024, Pada Pukul 10.00-11.00 dengan Dosen Penguji&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Arjuni Budi Pantjawati,&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Aip Saripudin,&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Mariya Al Qibtiya, Sudah selesai dilaksanakan</span></p>', '2024-07-12 16:39:26', '2024-08-08 09:29:10');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (142, 1, 378, 47, 5, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada hari kamis, tanggal 25 Juli 2024 pada pukul 11.00 - 12.00, serta dihadiri oleh dosen penguji :</p><p style=\"margin:0\">1. Bapak Dr. H. Bambang Trisno, M.SIE.</p><p style=\"margin:0\">2. Bapak Dr. Erik Haritman, S.Pd., M.T.</p><p style=\"margin:0\">3. Bapak Resa Pramudita, S.Pd., M.T.</p><p style=\"margin:0\">Beberapa masukan dan saran setelah sidang dilaksanakan, diantaranya :</p><p style=\"margin:0\">1.	Pembatasan masalah di sebutkan dengan detail mengenai indikator pembelajaran yang digunakan, contoh : penelitian ini dibatasi hanya mencakup indicator belajar kognitif.</p><p style=\"margin:0\">2.	Pada bab 2 setelah tabel penelitian terdahulu dibuat keterangan hasil dari penelitian sebelumnya.</p><p style=\"margin:0\">3.	Pada lembar angket lebih baik menggunakan skor untuk mengukur indicatornya.</p><p style=\"margin:0\">4.	Pada bab 3, pada sub bab instrument penelitian, table keterangan nama, kelas, dan mata pelajaran dihapus.</p><p style=\"margin:0\">5.	Pada validitas data, tidak perlu menjelaskan bentuk validasi pada penelitian tindakan kelas.</p><p style=\"margin:0\">6.	Pada prosedur penelitian, tambahkan table keterangan materi yang diajarkan pada saat penelitian berlangsung.</p><p style=\"margin:0\">7.	Tinjau lebih lanjut mengenai tujuan pembelajaran gambar Teknik di SMK.</p>', '2024-07-14 20:44:36', '2024-08-15 20:09:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (143, 1, 309, 48, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang Pre-Defense pada tanggal 19 Juli 2024, yang dimulai pada pukul 09.00 sampai dengan 10.00. sidang berjalan dengan lancar sesuai dengan jadwal yang telah di tetapkan, dengan di hadiri oleh satu dosen pembimbing dan tiga dosen penguji. Adapun untuk masukan dari dosen penguji lebih menitikberatkan pada penulisan agar lebih di sesuaikan lagi dengan pedoman UPI, dan ada beberapa saran terhadap sub bab baru yang harus ditambahkan dalam skripsi</p>', '2024-07-15 09:55:40', '2024-07-20 12:20:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (144, 1, 358, 54, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Sudah mengikuti predefense pada tanggal 24 juli 2024, dan sudah menyelesaikan revisi dari para penguji</p>', '2024-07-15 11:09:13', '2024-08-13 14:45:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (145, 1, 158, 48, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Perbaikan format penulisan</p>', '2024-07-15 12:31:06', '2024-08-02 14:18:10');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (146, 1, 31, 48, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-defense dilaksanakan pada hari Jum\'at, tanggal 19 Juli 2024. Sidang tersebut dihadiri oleh:</p><ol><li>Bapak Iwan Kustiawan sebagai moderator dan dosen pembimbing</li><li>Bapak Muhammad Adli Rizqullah sebagai dosen penguji</li><li>Bapak Saripudin sebagai dosen penguji</li></ol><p style=\"margin:0\">Sidang pre-defense dilaksanakn pada pukul 11.00 WIB di ruangan lab Eldas. Ibu Tuti Suartini, berhalangan hadir sebagai dosen penguji karena ada urusan mendadak.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Adapun notulensi yang didapat pada sidang pre-defense tersebut adalah sebagai berikut:</p><ol><li>Tambahkan signifikansi antara penelitian ini dengan penelitian lain yang terkait</li><li>Tambahkan penjelasan dan juga alasan yang lebih rinci mengenai parameter dan juga model lingkungan simulasi yang digunakan dalam penelitian ini</li><li>Perjelas kesimpulan dari hasil penelitian</li><li>Lebih memahami konsep efektivitas metode ray tracing yang dimaksud</li></ol>', '2024-07-15 23:47:57', '2024-08-19 17:15:18');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (147, 1, 336, 48, 4, 11, 1, 1, 1, '<p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Ringkasan Sidang Skripsi</span><br></p><p style=\"margin:0\">Sidang skripsi berlangsung dengan baik selama satu jam. Saya memaparkan hasil penelitian yang telah saya lakukan.</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Tanggapan Penguji</span><br></p><p style=\"margin:0\">Secara umum, para penguji mengapresiasi penelitian saya, namun mereka mengusulkan banyak revisi terkait perbaikan penulisan. Beberapa bagian perlu disempurnakan agar lebih jelas dan sesuai dengan standar penulisan ilmiah.</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Kesimpulan</span><br></p><p style=\"margin:0\">Sidang ini memberikan wawasan baru mengenai pentingnya perhatian terhadap detail dalam penulisan ilmiah.</p>', '2024-07-16 10:25:19', '2024-08-19 13:51:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (148, 1, 264, 48, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang pre-defense telah selsai dilaksanakan pada hari jum\'at, 17 Juli 2024 di ruang dosen (12-13)&nbsp;</p><p style=\"margin:0\">Terdapat beberapa masukan dari penguji terkait kesalahan penulisan dan istilah. Terdapat juga tambahan&nbsp; pada bab dua dan bab tiga mengenai spesifikasi antena dari perangkat yang digunakan pada simulasi dan alur dari \"flow chart\" , terdapat sedikit penambahan pada bab 4 berupa penjelasan mengenai gambar dari perubahan diagram konstelasi.&nbsp;</p>', '2024-07-16 10:33:11', '2024-08-08 22:44:31');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (149, 1, 360, 54, 3, 2, 1, 1, 1, '<p style=\"margin:0\">sudah mengikuti pre defense pada tanggal 24 juli 2024 dan sudah menyelesaikan revisi dari para penguji</p>', '2024-07-17 13:27:20', '2024-08-13 14:34:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (150, 1, 423, 47, 5, 1, 1, 1, 1, '<p class=\"MsoNormal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Sidang\ntertutup dilaksanakan pada tanggal 25 Juli 2024 pukul 11.00-12.00 bertempat di\nLab. Elind dan dihadiri oleh dosen penguji yaitu Bapak Dr. Aip Saripudin, M.T.\ndan Bapak Didin Wahyudin, M.T., Ph.D. serta Dosen Pembimbing sekaligus Moderator\nyaitu Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.<br></span><span style=\"font-family: &quot;Times New Roman&quot;, serif; color: inherit; font-size: 1rem;\">Dalam\nsidang tertutup, terdapat masukan dari para dosen penguji, diantaranya:</span></p><p class=\"MsoNormal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">-&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -18pt; color: inherit; font-size: 1rem;\">Penulisan\npada beberapa halaman yang kurang tepat dan harus diperbaiki<br>-&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -24px;\">Memperbaiki kejelasan pada nama tabel dan isi tabel agar tidak terjadi kesalahpahaman.</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -18pt; color: inherit; font-size: 1rem;\"><br>-&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -24px;\">Tinjau lebih lanjut mengenai penulisan rumus yang digunakan dalam metode penelitian</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -18pt; color: inherit; font-size: 1rem;\"><br>-&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -24px; color: inherit; font-size: 1rem;\">Tinjau lebih lanjut mengenai uji normalitas yang digunakan<br>-&nbsp;</span><span style=\"font-family: &quot;Times New Roman&quot;, serif; text-indent: -24px; color: inherit; font-size: 1rem;\">Tinjau lebih lanjut mengenai penulisan karya ilmiah UPI dalam menulis skripsi</span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">3.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">4.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoListParagraphCxSpLast\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo1\"><!--[if !supportLists]--><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">5.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span></p>', '2024-07-18 11:35:02', '2024-08-16 21:00:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (151, 1, 372, 54, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Sudah mengikuti Pre-Defense pada tanggal 24 Juli 2024 dan sudah di revisi serta di validasi hasil revisi oleh dosen penguji dan dosen pembimbing.&nbsp;</p>', '2024-07-18 16:27:40', '2024-08-15 12:40:58');
