INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (155, 1, 356, 54, 4, 2, 1, 1, 1, '<p class=\"MsoNormal\"><span lang=\"EN-US\">Sidang tertutup dilaksanakan pada tanggal 24\nJuli 2024 pukul 10.00-11.00, dihadiri oleh dosen penguji:<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">1. Bapak Prof. Dr.&nbsp;Jaja Kustija, MSc<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">2. Bapak Dr. Elih Mulyana, M.Si<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">Beberapa masukan setelah sidang\ndilaksanakan, diantaranya:<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">1. Menambahkan Gambaran Arsitektur IoT<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">2. Menambahkan gambar teknis alat (pada\nlampiran)<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">3. Memperbaiki abstrak <o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">4. Menambahkan hasil pengukuran total&nbsp; panjang dan berat kabel<o:p></o:p></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\"><span lang=\"EN-US\">5.Memperbaiki Gambar dan Tabel<o:p></o:p></span></p>', '2024-07-19 11:23:39', '2024-07-30 21:02:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (156, 1, 351, 54, 2, 3, 1, 1, 1, '<p style=\"margin:0\">sudah mengikuti pre-defense pada tanggal 24 Juli 2024, dan sudah menyelesaikan revisi dan menghadap kepada penguji</p>', '2024-07-19 14:03:54', '2024-08-13 17:07:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (157, 1, 368, 54, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Pak/Bu, Khoiri izin lapor bahwa saya sudah mengikuti pre-defense pada tanggal 24 Juli 2024 dan sudah menyelesaikan revisi dari para penguji. Terima kasih</p>', '2024-07-19 17:03:04', '2024-08-13 12:47:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (158, 1, 363, 54, 4, 1, 1, 1, 1, '<p style=\"margin:0\">sudah mengikuti pre defense pada tanggal 24 juli 2024, dan sudah menyelesaikan revisi para penguji</p>', '2024-07-19 17:40:37', '2024-08-13 14:50:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (159, 1, 346, 54, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Pak didin</p><p style=\"margin:0\">Kalau mau dibuat general, hilangkan bolanya. Nanti dirumusan masalah dipaparkan detailnya. Kalau disebutkan bola, bola apa? Kalau mau dibuat lebih detail.</p><p style=\"margin:0\">Kalau CV itu ke kamera, kalau di VAR tidak mungkin. Mungkin itu imageprocessing atau video processing.</p><p style=\"margin:0\">Formatting : walaupun ada subsection tidak perlu menjorok</p><p style=\"margin:0\">Dalam rumusan masalah coba dikaji lagi.</p><p style=\"margin:0\">Penelitian yg relevan, sebaiknya tidak berbentuk tabel. Buat dalam narasi</p><p style=\"margin:0\">Rujukan penelitian kurang relevan, seharusnya penelitian bagaimana implemebtasi visikomputer. Cari rujukan ttg penelitiaan bola.</p><p style=\"margin:0\">Gambar terlalu kecil</p><p style=\"margin:0\">Halaman 15 lebih menjelaskana cara kerja bukan desain.</p><p style=\"margin:0\">Referensinya kurang, minimal 10 lagi</p><p style=\"margin:0\"><br></p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Pak adli</p><p style=\"margin:0\">tambahkan peringatan ketika gagal deteksi frame</p><p style=\"margin:0\">Tidak ada penjelasan isi law of the game, masukan penjelasan kriterianya</p><p style=\"margin:0\">Dijelaskan kriteria baiknya itu apa -&gt; tidak mendeteksi selain bola</p><p style=\"margin:0\">Tambahkan keterangan dilampiran, dengan tabel 4.2&nbsp; diselaraskan. Keterangannya ga keliatan</p><p style=\"margin:0\">Keterangan gol atau engga kenapa tetep muncul walau gol udah beres?</p><p style=\"margin:0\">Kenapa kalau out ga ada keterangannya? Kurang penjelasannya pada sistemnya</p><p style=\"margin:0\">Apa perbedaan persenan dalam deteksi gol. Untuk apa persenan itu?</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Pak saripudin</p><p style=\"margin:0\">Abstrak diperbaiki</p><p style=\"margin:0\">Rumusan masalah formatnya perbaiki</p><p style=\"margin:0\">Bab 2 coba dicek, ada kajian ttg teknologi bidang</p><p style=\"margin:0\">Metode eksperimen -&gt; sitasinya drmana?</p><p style=\"margin:0\">Perancangan sistem rujukannya apa? Menggunakan metode apa?</p><p style=\"margin:0\">Bab 4 cek lagi ururan penjelasannya, ada pengulangan yg harusnya di bab 3</p><p style=\"margin:0\">Daftar pustaka ditambah dan terbaru</p>', '2024-07-19 22:35:55', '2024-08-16 17:17:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (160, 1, 392, 54, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Sudah melakukan pre defense pada tanggal 24 juli 2024, serta telah direvisi oleh para penguji serta pembimbing</p>', '2024-07-22 06:00:36', '2024-08-14 13:22:01');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (161, 1, 260, 55, 1, 1, 1, 1, 1, 'Sidang skripsi berjalan lancar dengan durasi 1 jam . Saya mempresentasikan hasil penelitian mengenai jaringan FTTH berbasis EPON di Desa Arjasari.<br>Penguji umumnya memberikan apresiasi atas penelitian saya, namun banyak revisi yang diminta terkait dengan perbaikan penulisan. Beberapa bagian perlu diperbaiki agar lebih jelas dan sesuai dengan kaidah penulisan ilmiah.Sidang ini memberikan pandangan baru mengenai pentingnya detail dalam penulisan ilmiah', '2024-07-23 10:25:51', '2024-08-19 11:17:22');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (162, 1, 418, 52, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari selasa, tanggal 13 agustus 2024 pukul 07.00 - 8.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1. Prof. Dr. Jaja Kustija, M.Sc. (Dosen Pembimbing)</p><p style=\"margin:0\">2. Dr. Erik Haritman, S.Pd., M.T (Dosen Penguji 1)</p><p style=\"margin:0\">3. Dr. Yadi Mulyadi M.T. (Dosen Penguji 2)</p><p style=\"margin:0\">4. Dr. saripudin, S.Pd., M.T. (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Mengganti posisi penomoran halaman sesuai pedoman KTI UPI</p><p style=\"margin:0\">2. Penamaan referensi daftar pustaka sesuai pedoman KTI UPI</p><p style=\"margin:0\">3. Abstrak ( jumlah kata diringkas ) sesuai pedoman KTI UPI</p><p style=\"margin:0\">4. Terdapat beberapa kata yang menggunakan font tidak sesuai pedoman KTI UPI</p><p style=\"margin:0\">5. Kutipan tidak tertera pada beberapa hal yang terdapat di BAB II&nbsp;</p><p style=\"margin:0\">6. Pembahasan Internet of Things ( IoT) dilengkapi&nbsp;</p><p style=\"margin:0\">7. Penambahan penelitian terdahulu sesuai dengan topik yang dibahas</p><p style=\"margin:0\">8. Keterangan hasil alat diperjelas dalam (kondisi,hasil, dan keadaan)</p>', '2024-07-24 23:47:35', '2024-08-19 21:09:56');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (163, 1, 322, 52, 2, 1, 1, 1, 1, '<p class=\"MsoNoSpacing\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif\">Saat\nsidang tertutup (pre defense) yang dilaksanakan pada hari selasa, tanggal 13\nAgustus 2024 pukul 08.00 - 09.00 WIB yang dihadiri oleh:</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">1. Bapak Dr. Ir. Maman\nSomantri, S.Pd.M.T. (Dosen Pembimbing)</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">2.&nbsp; Bapak Dr.Yadi Mulyadi,M.T.&nbsp; (Dosen Penguji 1)</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">3.&nbsp; Bapak ⁠Prof.Dr.Jaja&nbsp; Kusteja,M.Sc. (Dosen Penguji 2)</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">4. Ibu ⁠Prof .Dr .Tuti\nSuartini,M.Pd . (Dosen Penguji 3)</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">Terdapat beberapa masukan\ndalam sidang tersebut, diantaranya:</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">1. Untuk tabel lanjutan harus\ndiberikan kepala tabel lagi.</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">2. Perbaikan symbol N_Gain.</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">3. Font padaa daftar pustakan\ntidak boleh kapital semua dan disamakan.</span></p>\n\n<p class=\"MsoNoSpacing\"><span lang=\"NO-BOK\" style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:NO-BOK\">4. Perbaikan Kesimpulan.<o:p></o:p></span></p>', '2024-07-25 09:14:19', '2024-08-15 19:02:14');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (164, 1, 330, 52, 3, 2, 1, 1, 1, '<p style=\"margin:0\"><span style=\"font-size:17px\" ;=\"\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari Selasa, tanggal 13 Agustus 2024 pukul 09.00 - 10.00 WIB yang dihadiri oleh:</span><br>\n<span style=\"font-size:17px\" ;=\"\">1. Dr. Ir. Maman Somantri, S.Pd., M.T., IPU. (Dosen Pembimbing)</span><br>\n<span style=\"font-size:17px\" ;=\"\">2. Dr. Tasma Sucita, S.T., M.T. (Dosen Penguji 1)</span><br>\n<span style=\"font-size:17px\" ;=\"\">3. Dr. Bambang Trisno, M.SIE. (Dosen Penguji 2)</span><br>\n<span style=\"font-size:17px\" ;=\"\">4. Dr. Ir. Elih Mulyana, M.Si., IPU. (Dosen Penguji 3)</span><br>\n<span style=\"font-size:17px\" ;=\"\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</span><br>\n<span style=\"font-size:17px\" ;=\"\">1. Memperbaiki penulisan skripsi serta abstrak dan pastikan sesuai dengan pedoman UPI</span><br>\n<span style=\"font-size:17px\" ;=\"\">2. Rumusan Masalah bisa di break down menjadi 4 bagian yaitu, membandingkan jenis analog-semi, membandingkan analog-smart meter dan membandingkan semi-smart meter</span><br>\n<span style=\"font-size:17px\" ;=\"\">3. Perbaikan flowchart alir penelitian pada bab 3</span><br>\n<span style=\"font-size:17px\" ;=\"\">4. Memberbaiki bab 4 setelah di break down rumus masalahnya</span><br>\n<span style=\"font-size:17px\" ;=\"\">5. Buat urutan ranking kwh yang direkomendasikan</span><br>\n<!--/data/user/0/com.samsung.android.app.notes/files/clipdata/clipdata_bodytext_240817_161635_676.sdocx--></p>', '2024-07-31 13:06:01', '2024-08-17 16:17:29');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (165, 1, 394, 55, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Pelaksanaan pre defense saya pada hari kamis 8 Agustus 2024 pukul 07.00 dengan penguji :</p><p style=\"margin:0\">1. Bapak Wasimudin Surya Saputra, S.T., M.T.</p><p style=\"margin:0\">2. Bapak Prof. Dr. Jaja Kustija, M.Sc.</p><p style=\"margin:0\">3. Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.</p><p style=\"margin:0\">telah selesai pada pukul 08.15.</p><p style=\"margin:0\">Alhamdulillah pelaksanaan pre defense ini berjalan dengan lancar dan tanpa hambatan yang berarti. Penguji memberikan beberapa masukan terkait skripsi saya. Revisi penulisan yang harus dilakukan pun hanya sedikit yaitu penulisan Abstrak dan juga flowchart yang kurang besar menyebabkan tidak terbaca. dan juga ada beberapa saran dan kritik membangun yang dilontarkan oleh penguji untuk skripsi saya ini.</p><p style=\"margin:0\">Sekian dan terimakasih.</p>', '2024-07-31 13:26:46', '2024-08-12 09:45:48');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (166, 1, 377, 57, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Sudah mengikuti pre defense pada tanggal 7 agustus 2024, dan sudah menyelesaikan revisi dari para penguji</p>', '2024-07-31 17:14:55', '2024-08-20 13:48:21');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (167, 1, 385, 52, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 13 Agustus 2024 pukul 08.00-09.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Ibu Dr. Siscka Elvyanti, S.Pd., M.T</p><p style=\"margin:0\">2. Bapak Dr. H. Bambang Trisno, M.SIE</p><p style=\"margin:0\">3. Bapak Dr. Elih Mulyana, M.Si.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Tinjau lebih lanjut mengenai topik yang diangkat.</p><p style=\"margin:0\">2. Tinjau lebih lanjut mengenai tabel hasil yang didapatkan</p><p style=\"margin:0\">3. Perbaikan terkait penulisan referensi</p>', '2024-07-31 17:26:32', '2024-08-14 18:02:54');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (168, 1, 405, 52, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari selasa, tanggal 13 agustus 2024 pukul 08.00 - 09.00 WIB yang dihadiri oleh:</p><p style=\"margin:0\">1.&nbsp;<span style=\"text-align: center; color: inherit; font-size: 1rem;\">Wawan Purnama,\nS.Pd., M.Si.&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">(Dosen Pembimbing)</span></p><p style=\"margin:0\">2. Ir. Hj. Arjuni Budi Pantjawati, M.T. (Dosen Penguji 1)</p><p style=\"margin:0\">3. Prof. Dr. Budi Mulyanti, M.Si. (Dosen Penguji 2)</p><p style=\"margin:0\">4. Silmi Ath Thahirah Al Azhi, S.T., M.T. (Dosen Penguji 3)</p><p style=\"margin:0\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</p><p style=\"margin:0\">1. Penambahan pada bagian abstrak agar lebih memperjelas permasalahan beserta solusi yang dihadirkan pada penelitian ini.</p><p style=\"margin:0\">2. Pertimbangkan kembali kata konteks beserta fungsi metode fuzzy Tsukamoto pada bagian latar belakang.</p><p style=\"margin:0\">3. Perubahan pada bagian batasan masalah agar lebih sesuai dengan isi pada penelitian ini dan tidak memasukan design penelitian kepada batasan masalah.</p><p style=\"margin:0\">4. Berikan diameter pengukuran kepada semua gambar yang ada bagian isi penelitian.</p><p style=\"margin:0\">5. Perbaikan flowchart pada metode fuzzy Tsukamoto.</p><p style=\"margin:0\">6. Perbaikan format penulisan judul tabel pada bab 4 bagian subbab 4.5 pada pengujian keseluruhan sistem.</p><p style=\"margin:0\">7. Penambahan untuk hasil percobaan data ini dibuat dalam bentuk grafik agar lebih mudah dipahami.</p><p style=\"margin:0\">8. Perbaikan penulisan daftar pustaka beserta kutipan-kutipan, yang cukup hanya menyebutkan nama orangnya saja tidak dengan gelarnya.</p>', '2024-08-01 08:41:51', '2024-08-14 13:26:26');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (169, 1, 364, 55, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Pre-Defence telah terlaksanakan dengan baik dan lancar, penguji memberikan beberapa saran dan sedikit bagian skripsi yang harus direvisi.</p>', '2024-08-01 12:34:59', '2024-08-16 14:01:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (170, 1, 388, 52, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 13 Agustus 2024 pukul 10.00-11.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Ibu Prof. Budi Mulyanti, M.Si.</p><p style=\"margin:0\">2. Ibu Prof. Dr. Tuti Suartini, M.Pd.</p><p style=\"margin:0\">3. Ibu Mariya Al Qibtiya, M.T.</p><p style=\"margin:0\">dan dosen pembimbing : Ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Pada bagian abstrak dan latar belakang dibuat lebih singkat dan jelas</p><p style=\"margin:0\">2. Pada bagian metode penelitian perjelas rancangan sistem.</p><p style=\"margin:0\">3. Pada bagian kesimpulan dibuat singkat dan jelas.</p><p style=\"margin:0\">4. Pada bagian gambar diperjelas/diperbesar.</p><p style=\"margin:0\">5. Perbaiki penulisan sitasi, tanda koma dan titik.</p>', '2024-08-02 09:53:09', '2024-08-14 12:13:18');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (171, 1, 308, 55, 2, 1, 1, 1, 1, '<p style=\"margin:0\"><span lang=\"EN-US\" style=\"font-size:11.0pt;line-height:\n106%;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;\nmso-fareast-theme-font:minor-latin;mso-font-kerning:0pt;mso-ligatures:none;\nmso-ansi-language:EN-US;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">Perkembangan\nteknologi informasi membutuhkan infrastruktur telekomunikasi yang handal,\nkhususnya dalam kapasitas <i>bandwidth</i>, reliabilitas, dan kualitas\ntransmisi. </span><span lang=\"FI\" style=\"font-size:11.0pt;line-height:106%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\nminor-latin;mso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:FI;\nmso-fareast-language:EN-US;mso-bidi-language:AR-SA\">Meskipun serat optik\nmenjadi solusi utama, kerentanannya terhadap gangguan seperti fiber cut masih\nmenjadi tantangan. Sistem proteksi ASON <i>(Automatically Switched Optical\nNetwork)</i> diimplementasikan untuk mengatasi masalah ini, namun\nefektivitasnya perlu dievaluasi lebih lanjut. Penelitian ini menganalisis\nsistem proteksi ASON pada link transmisi serat optik Bandung-Cirebon milik PT.\nMega Akses Persada (Fiberstar). Tujuan penelitian adalah mengevaluasi keandalan\ndan efektivitas ASON dalam menjaga stabilitas jaringan serat optik jarak jauh.\nFokus penelitian mencakup perbandingan kualitas Rx <i>level</i> sebelum dan\nsesudah perbaikan kabel serat optik, penilaian kemampuan ASON dalam memberikan\nbackup dibandingkan sistem tanpa proteksi, serta evaluasi kelayakan sistem\nberdasarkan parameter QoS <i>(Quality of Service)</i>. Metode penelitian\nmenggunakan pendekatan kuantitatif dengan analisis data. Hasil menunjukkan\npeningkatan kualitas Rx <i>level</i> setelah perbaikan, dengan peningkatan Q <i>factor</i>\nsebesar 0,48, OSNR <i>(Optical Signal to Noise Ratio)s</i> sebesar 3,28dB, redaman\ntotal sebesar 4,15 dB untuk Tx dan 3,02 untuk Rx, serta <i>power receiver</i>\nsebesar 0,71 dBm untuk NE<i>(Near End)</i> dan 0,34 dBm untuk FE <i>(Far End)</i>.\n</span><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:\n&quot;Times New Roman&quot;,serif;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\nminor-latin;mso-font-kerning:0pt;mso-ligatures:none;mso-ansi-language:EN-ID;\nmso-fareast-language:EN-US;mso-bidi-language:AR-SA\">Sistem ASON terbukti sangat\nefektif dengan switching time hanya 21 ms, mencapai efisiensi 99,99%\ndibandingkan sistem tanpa proteksi. Analisis QoS menunjukkan kinerja\n\"Sangat Baik\" pada semua parameter yang diuji dengan parameter jalur\nutama <i>throughput </i>mencapai 99,79%, <i>frame loss</i> 0, <i>latency</i></span><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:&quot;Calibri&quot;,sans-serif;\nmso-ascii-theme-font:minor-latin;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\nminor-latin;mso-hansi-theme-font:minor-latin;mso-bidi-font-family:&quot;Times New Roman&quot;;\nmso-bidi-theme-font:minor-bidi;mso-font-kerning:0pt;mso-ligatures:none;\nmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">\nsebesar 2,105 ms, dan <i>jitter </i>0 ms. Dan pada jalur proteksi untuk </span><i><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-font-kerning:\n0pt;mso-ligatures:none;mso-ansi-language:EN-ID;mso-fareast-language:EN-US;\nmso-bidi-language:AR-SA\">throughput </span></i><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-font-kerning:\n0pt;mso-ligatures:none;mso-ansi-language:EN-ID;mso-fareast-language:EN-US;\nmso-bidi-language:AR-SA\">mencapai 94,46%, <i>frame loss</i> 0, <i>latency</i></span><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:&quot;Calibri&quot;,sans-serif;\nmso-ascii-theme-font:minor-latin;mso-fareast-font-family:Calibri;mso-fareast-theme-font:\nminor-latin;mso-hansi-theme-font:minor-latin;mso-bidi-font-family:&quot;Times New Roman&quot;;\nmso-bidi-theme-font:minor-bidi;mso-font-kerning:0pt;mso-ligatures:none;\nmso-ansi-language:EN-ID;mso-fareast-language:EN-US;mso-bidi-language:AR-SA\">\nsebesar 15,9729 ms ms, dan <i>jitter </i>0 ms</span><span lang=\"EN-ID\" style=\"font-size:11.0pt;line-height:106%;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:Calibri;mso-fareast-theme-font:minor-latin;mso-font-kerning:\n0pt;mso-ligatures:none;mso-ansi-language:EN-ID;mso-fareast-language:EN-US;\nmso-bidi-language:AR-SA\">. Kesimpulannya, sistem proteksi ASON memberikan\nkeandalan dan kualitas layanan tinggi pada jaringan serat optik\nBandung-Cirebon, menunjukkan efektivitasnya dalam menjaga kontinuitas layanan\ndan meminimalkan dampak gangguan.</span><br></p>', '2024-08-02 15:15:34', '2024-08-19 09:02:50');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (172, 1, 74, 55, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Saya telah melaksanakan Pre-Defense pada tanggal 08-08-2024.</p>', '2024-08-02 16:41:03', '2024-08-19 14:33:21');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (173, 1, 393, 52, 4, 2, 1, 1, 1, '<p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">Saat sidang tertutup (pre defense) yang dilaksanakan pada hari jum\'at, tanggal 13 Agustus 2024 pukul </span><span class=\"selectable-text copyable-text\" style=\"color: var(--link); white-space-collapse: preserve;\">10.00 - 11.00</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> WIB yang dihadiri oleh:</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">1.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Resa Pramudita, S.Pd., M.T. (Dosen Pembimbing)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">2.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Dr. Tasma Sucita, S.T., M.T. (Dosen Penguji 1)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">3.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Dr. Elih Mulyana, </span><span class=\"selectable-text copyable-text\" style=\"color: var(--link); white-space-collapse: preserve;\">M.Si</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">. (Dosen Penguji 2)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">4.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Dr. Maman Soemantri, S.Pd., M.T., IPU. (Dosen Penguji 3)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">Terdapat beberapa masukan dalam sidang tersebut, diantaranya:</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">1.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Perbaiki abstrak dan sesuaikan dengan pedoman penulisan karya ilmiah UPI</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">2.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Penambahan kata \"penelitian\" dalam judul subbab Latar Belakang dan Rumusan Masalah</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">3.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Ubah kalimat efesiensi pada rumusan masalah menjadi rill daya (daya nyata)</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">4.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Menambahkan alasan-alasan mengambil judul penelitian tersebut</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">5.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Mengganti judul Bab II menjadi Kajian Pustaka, tambahkan dan perbanyak teori-teori Demand Side Management (DSM), Peralatan Listrik Rumah Tangga dan Optimalisasi</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">6.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Perbaiki judul-judul subbab pada Bab III menjadi :</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">        3.1 Desain penelitian</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">        3.2 Partisipan</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">        3.3 Instrumen penelitian</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">        3.4 Alur penelitian</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\">        3.5 Analisis data</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\" style=\"text-indent: 15px;\"><span class=\"selectable-text copyable-text x1sdyfia xss6m8b\" style=\"white-space-collapse: preserve;\">7.</span><span class=\"selectable-text copyable-text\" style=\"white-space-collapse: preserve;\"> Perbaiki  judul Bab IV menjadi Temuan dan Pembahasan, serta tambahkan pembahasan mengenai penelitian yang diambil</span></p><p class=\"selectable-text copyable-text x15bjb6t x1n2onr6\" dir=\"ltr\"><br></p>', '2024-08-03 11:10:33', '2024-08-19 05:45:42');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (174, 1, 402, 52, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang Ujian Pre-Defense. </p><p style=\"margin:0\">Pada tanggal 13 Agustus 2024 hari selasa, jam 09:15 - 10:22. Sidang dihadiri oleh:</p><p style=\"margin:0\">dosen penguji:&nbsp;</p><p style=\"margin:0\">1. Ibu Prof. Budi Mulyanti, M.Si</p><p style=\"margin:0\">2. Ibu Prof. Dr. Tuti Suartini, M.Pd.</p><p style=\"margin:0\">3. Ibu Mariya Al Qibtiya, M.T.</p><p style=\"margin:0\">serta dosen pembimbing:</p><p style=\"margin:0\">4. Ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.</p><p style=\"margin:0\">sidang berlangsung dengan lancar.</p>', '2024-08-03 14:05:03', '2024-08-13 15:09:44');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (175, 1, 395, 52, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Report Pre-Defense</p><p style=\"margin:0\">Dilaksanakan pada: Selasa, 13 Agustus 2024</p><p style=\"margin:0\">Dihadiri oleh: Bapak Erik Haritman selaku Dosen Pembimbing, Bapak Dadang Lukman Hakim selaku Dosen Penguji, dan Bapak Nurul Fahmi selaku Dosen Penguji.</p><p style=\"margin:0\">Revisi oleh Bapak Nurul Fahmi:</p><p style=\"margin:0\">- Jelaskan inovasi pada latar belakang (penggunaan VSD)</p><p style=\"margin:0\">- Referensi yang ada kebaruan (Maximal 5 tahun kebelakang)</p><p style=\"margin:0\">- Penulisan diperbaiki, kata asing dibuat italic</p><p style=\"margin:0\">- Tambahkan perbandingan metode menggunakan VSD dengan metode lain.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Revisi oleh Bapak Dadang Lukman Hakim:</p><p style=\"margin:0\">- Gambar yang tidak jelas digambar ulang, jangan di screenshot</p><p style=\"margin:0\">- Penulisan masih ada beberapa yang salah.</p><p style=\"margin:0\">- Kenapa tidak menggunakan beban pada motor?</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Sidang berjalan lancar dari awal sampai akhir. Sidang dimulai pada pukul 10.13 dan selesai pada pukul 11.02 WIB.&nbsp;</p>', '2024-08-03 15:38:27', '2024-08-15 23:58:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (176, 1, 328, 52, 3, 1, 1, 1, 1, '<p style=\"margin:0\">PRE-DEFENSE dilaksanakan pada hari Selasa, 13 Agustus 2024 pada pukul 09.00-10.00 dengan dihadiri oleh dosen pembimbing Dr. Erik Haritman S.Pd., M.T., dan para dosen penguji Dr. Siscka Elvyanti M.T., lalu Dr. Saripudin S.Pd., M.T., dan Pak Resa Pramudita S.Pd., M.T.<br></p>', '2024-08-03 16:32:06', '2024-08-14 17:31:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (177, 1, 252, 55, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Pelaksanaan pre defense pada hari kamis, jam 9 dengan penguji Bapak Prof. Dr. Jaja Kustija, M.Sc; Bapak Wasimudin Surya Saputra, S.T., M.T.; Bapak Dr. Elih Mulyana, M.Si. telah selesai dilaksanakan pada jam 10.</p>', '2024-08-04 01:09:35', '2024-08-08 21:03:14');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (178, 1, 80, 55, 3, 1, 1, 1, 1, '<p class=\"MsoNormal\"><span lang=\"EN-US\">Sidang <i>Pre-Defense</i>\ntelah dilaksanakan pada hari Kamis tanggal 8 Agustus 2024 dengan dosen penguji:<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo2\"><!--[if !supportLists]--><span lang=\"EN-US\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span lang=\"EN-US\">Bapak Agus Heri Setya Budi, M.T.<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpLast\" style=\"text-indent:-18.0pt;mso-list:l0 level1 lfo2\"><!--[if !supportLists]--><span lang=\"EN-US\">2.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span lang=\"EN-US\">Ibu Ir. Hj. Arjuni Budi Pantjawati,\nM.T.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">Sidang\nTelah berjalan dengan baik dan mendapatkan beberapa <i>feedback</i> dari dosen\npenguji, diantaranya:<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"text-indent:-18.0pt;mso-list:l1 level1 lfo1\"><!--[if !supportLists]--><i><span lang=\"EN-US\">1.<span style=\"font-style: normal; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></i><!--[endif]--><i><span lang=\"EN-US\">Feedback </span></i><span lang=\"EN-US\">dari Bapak Agus Heri Setya Budi,\nM.T. :<i><o:p></o:p></i></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-left:72.0pt;mso-add-space:\nauto;text-indent:-18.0pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span lang=\"EN-US\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol;mso-ansi-language:EN-US;mso-bidi-font-style:italic\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span><!--[endif]--><span lang=\"EN-US\">Penambahan\nmateri di bab 2<i><o:p></o:p></i></span></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-left:72.0pt;mso-add-space:\nauto;text-indent:-18.0pt;mso-list:l2 level1 lfo3\"><!--[if !supportLists]--><span lang=\"EN-US\" style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol;mso-ansi-language:EN-US;mso-bidi-font-style:italic\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optica