INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (233, 1, 511, 80, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang pre-defense dilaksanakan 16 Januari 2025 pukul 09.00-10.00 WIB, dihadiri oleh dosen penguji:</p><ol><li>&nbsp;Bapak Didin Wahyudin, S.Pd., M.T., Ph.D.</li><li>Bapak Dr. Tasma Sucita, M.T.</li><li>Bapak Dr. Ir. Dadang Lukman Hakim, M.T.</li></ol><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><ol><li>Menambahkan diagram blok sistem.</li><li>Menambahkan penjelasan data pada analisis data.</li><li>Memperbaiki penulisan sesuai dengan pedoman UPI.</li></ol>', '2025-01-10 14:26:25', '2025-01-18 16:54:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (234, 1, 526, 82, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 21 Januari 2025 pukul 08.00-09.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Didin Wahyudin, Ph.D</p><p style=\"margin:0\">2. Ibu Prof. Dr. Hj. Budi Mulyanti, M.Si</p><p style=\"margin:0\">2. Bapak Agus Heri Setya Budi, M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">- Fokus penulisan yang harus diperbaiki</p><p style=\"margin:0\">- Proses penentuan data dan acuan kondisi level kebencanaan yang harus digali lebih dalam lagi</p><p style=\"margin:0\">- Optimalisasi integrasi sistem</p><div><br></div>', '2025-01-14 05:41:33', '2025-02-21 08:18:50');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (235, 1, 362, 83, 6, 11, 1, 1, 1, '<p style=\"margin:0\">Sudah mendapatkan perbaikan dan masukan mengenai paper penelitian</p>', '2025-01-14 12:17:41', '2025-01-14 12:26:58');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (236, 1, 571, 84, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 14 Februari 2025 pukul 13.30-14.30, dihadiri oleh dosen pembimbing:</p><p style=\"margin:0\">Bapak Prof. Dr. Ade Gafar Abdullah, S.Pd., M.Si<br></p><p style=\"margin:0\">dosen penguji:</p><p style=\"margin:0\">1. Ibu Dr. Siscka Elvyanti, M.T.</p><p style=\"margin:0\">2. Bapak Prof. Dr. Enjang A. Juanda, M.Pd., M.T</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Tinjau lebih lanjut mengenai sumber dari gambar-gambar yang dicantumkan dan kejelasan gambar.</p><p style=\"margin:0\">2. Tambahkan penjelasan bahwa peneliti hanya sebagai pengamat bukan sebagai penguji di lapangan.</p><p style=\"margin:0\">3. Lengkapi bagian pembahasan dan hasil lengkapi data yang dihasilkan dari perhitungan.</p>', '2025-01-20 06:32:08', '2025-02-15 13:58:50');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (237, 1, 573, 84, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Pada ruang lingkup penelitian baiknya ditambahkan alasan pertimbangan tahun terbit dari jurnal yang digunakan. Masih ada perubahan halaman antara gambar dengan identitas gambar dan baiknya gambar dengan identitas gambar itu di halaman yang sama. Setelah Gambar 4.1, Gambar 4.2, dan Gambar 4.3 baiknya ditambahkan sedikit penjelasan terkait isi dari gambar-gambar tersebut.</p>', '2025-01-21 10:20:24', '2025-03-02 09:35:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (238, 1, 384, 84, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Terimakasih kepada bapak Dr. Tasma Sucita S.T.,M.T. selaku pembimbing dan bapak Dr. Yadi Mulyadi, M.T. dan bapak Wawan purnama, S.Pd, M.Si selaku penguji.</p>', '2025-01-23 05:53:47', '2025-02-27 10:38:18');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (239, 1, 575, 84, 2, 2, 1, 1, 1, '<p style=\"margin:0\">https://drive.google.com/file/d/1EMYneIthlJPITvL0Mjbb-CrJ7k4NBpw4/view?usp=sharing</p>', '2025-02-05 18:06:18', '2025-02-14 14:43:31');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (240, 1, 515, 87, 1, 11, 1, 1, 1, '<p style=\"margin:0\"><b>LAPORAN PELAKSANAAN SIDANG TERTUTUP&nbsp;&nbsp;</b></p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya, Alyana Savira Luqiana Asri, NIM 2109090 mahasiswa Program Studi Teknik Elektro, telah melaksanakan sidang tertutup skripsi pada Jumat, 7 Maret 2025, pukul 07.00-08.00 WIB, di Ruang Dosen 12-13. Sidang ini merupakan bagian dari proses akademik dalam menyelesaikan tugas akhir dengan judul \"<b>ANALISIS KETIDAKSEIMBANGAN BEBAN TERHADAP RUGI-RUGI DAYA PADA TRANSFORMATOR 150/20 KV UNIT 3 DI GARDU INDUK RANCAEKEK PT PLN (PERSERO)</b>\".&nbsp;&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Sidang tertutup ini dihadiri oleh pembimbing,&nbsp; dan tim penguji yang terdiri dari:&nbsp;&nbsp;</p><ol><li>Dr. Tasma Sucita, M.T&nbsp;</li><li>Prof. Dr. Jaja Kustija, M.Sc</li><li>⁠Dr. Yadi Mulyadi, M.T</li><li>Wasimudin Surya Saputra, S.T, M.T</li></ol><p style=\"margin:0\"><br></p><p style=\"margin:0\">Kepada tim KBK:</p><ol><li>Dr. Aip Saripudin, S.SI, M.T</li><li>Didin Wahyudin, M.T, Ph.D</li></ol><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selama sidang berlangsung, saya telah memaparkan hasil penelitian serta mendapatkan berbagai masukan dan saran untuk penyempurnaan skripsi. Tim penguji memberikan catatan perbaikan yang harus segera saya selesaikan sebelum menuju tahap sidang terbuka.&nbsp;&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar besarnya kepada dosen pembimbing, tim penguji, kepada tim KBK, serta seluruh pihak yang telah membantu dalam proses penyusunan dan penyelesaian skripsi ini. Semoga hasil penelitian ini dapat memberikan manfaat di bidang teknik elektro, khususnya dalam analisis sistem tenaga listrik.&nbsp;&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Demikian laporan ini saya buat sebagai bentuk pertanggungjawaban atas pelaksanaan sidang tertutup.&nbsp;&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Alyana Savira Luqiana Asri</p><p style=\"margin:0\">NIM: 2109090</p><p style=\"margin:0\">Program Studi Teknik Elektro</p>', '2025-02-14 23:57:05', '2025-03-09 07:13:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (241, 1, 509, 87, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Pre-Defense telah dilaksanakan pada hari Jumat, 7 Maret 2025, pukul 08:00 - 09:00. Terima kasih banyak kepada bapak dosen penguji serta bapak dosen pembimbing yang telah meluangkan waktunya untuk hadir pada sidang pre-defense. semoga ilmu yang diberikan menjadi pahala bagi bapak dosen sekalian.</p>', '2025-02-21 11:40:59', '2025-03-09 21:15:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (242, 1, 531, 87, 3, 11, 1, 1, 1, '<p style=\"margin:0\">Saya Intan Fauziyah dengan NIM 2109148 telah melakukan Pre-Defense pada Jumat, 7 Maret 2025 Pukul 09.00-10.00 WIB. Terima kasih kepada para dosen yang terlibat dosen pembimbing, tim dosen penguji, tim dosen KBK, serta ketua program studi Teknik Elektro atas ilmu, wawasan, waktu, energi, beserta kesempatannya sehingga saya bisa melakukan Pre-Defense dengan baik. Semoga segala kebaikan Allah gantikan dengan pahala yang berlipat ganda. Aamiin.</p>', '2025-02-21 11:43:52', '2025-03-09 20:36:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (243, 1, 529, 87, 4, 11, 1, 1, 1, '<p style=\"margin:0\">Pre-Defense telah dilaksanakan pada hari Jumat, 7 Maret 2025, pukul 10.00 - 11.00 WIB. Terima kasih kepada bapak dan ibu dosen penguji serta bapak dosen pembimbing yang telah hadir menyempatkan waktunya</p>', '2025-02-21 11:43:59', '2025-03-09 20:33:41');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (244, 1, 506, 88, 3, 9, 1, 1, 1, '<div>**LAPORAN PELAKSANAAN SIDANG TERTUTUP**&nbsp;&nbsp;</div><div><br></div><div>Saya, Dhea Yulika Sitorus mahasiswa Program Studi Teknik Elektro, telah melaksanakan sidang tertutup skripsi pada Jumat, 14 Maret 2025 di Ruang Ketua Lab. Telkom, Sidang ini merupakan bagian dari proses akademik dalam menyelesaikan tugas akhir dengan judul **\"ANALISIS OPTIMALISASI KINERJA CIRCULATING WATER PUMP (CWP) UNTUK MENINGKATKAN EFISIENSI ENERGI DAN PENGHEMATAN BAHAN BAKAR PADA PEMBANGKIT LISTRIK TENAGA UAP (PLTU) CIREBON\"**.&nbsp;&nbsp;</div><div><br></div><div>Sidang tertutup ini dihadiri oleh tim penguji yang terdiri dari:&nbsp;&nbsp;</div><div>1. Dr. Elih Mulyan, M.Si</div><div>2. ⁠⁠Wasimudin Surya Saputra, S.T, M.T</div><div>3. Dr. Ir. Maman Somatri, S.Pd., M.T</div><div>4. ⁠Dr. H. Bambang Trisno, MSIE</div><div><br></div><div>Kepada tim KBK:</div><div>1. Dr. Aip Saripudin, S.SI, M.T</div><div>2. Didin Wahyudin, M.T, Ph.D</div><div><br></div><div>Selama sidang berlangsung, saya telah memaparkan hasil penelitian serta mendapatkan berbagai masukan dan saran untuk penyempurnaan skripsi. Tim penguji memberikan catatan perbaikan yang harus segera saya selesaikan sebelum menuju tahap sidang terbuka.&nbsp;&nbsp;</div><div><br></div><div>Saya mengucapkan terima kasih kepada dosen pembimbing, tim penguji, kepada tim KBK, serta seluruh pihak yang telah membantu dalam proses penyusunan dan penyelesaian skripsi ini. Semoga hasil penelitian ini dapat memberikan manfaat di bidang teknik elektro.&nbsp;</div><div><br></div><div>Demikian laporan ini saya buat sebagai bentuk pertanggungjawaban atas pelaksanaan sidang tertutup.&nbsp;&nbsp;</div><div><br></div><div><br></div><div>Dhea Yulika Sitorus&nbsp;</div><div>NIM: 2103624</div><div>Program Studi Teknik Elektro</div>', '2025-03-03 12:58:13', '2025-03-14 22:52:22');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (245, 1, 530, 85, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Tambahan Saran:</p><p style=\"margin:0\">Cantumkan penjelasan mengenai cleaning data yang dipakai</p>', '2025-03-04 10:12:18', '2025-03-24 13:42:54');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (246, 1, 514, 88, 4, 9, 1, 1, 1, '<p style=\"margin:0\">1. Tambahkan penjelasan UltraTEV Plus2 di Bab 2<br>2. Nilai PPC di abstrak dituliskan rentang nilainya<br>3. Poin ucapan terimakasih hanya untuk manusia<br>4. Tabel jangan terpotong<br>5. Datanya diolah dulu, baru dianalisis<br>6. Kesimpulan persingkat lagi</p>', '2025-03-04 19:58:24', '2025-03-17 20:55:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (247, 1, 527, 85, 3, 2, 1, 1, 1, '1. Judul terlalu banyak singkatan<br>2. Sebutkan alasan penggunaan 5 GHz dan implementasinya di latar belakang<br>3. Cari penelitian terdahulu yang secara real nya bukan simulasi<br>4. Diperjelas NRZ nya itu sebagai modulasi atau line coding<br>5. Prinsip kerja DCF dan CFBG lebih diperjelas dan apa yang membedakan keduanya<br>6. Teori EDFA harus dipisahkan di sub bab lain, jangan menyatu dengan kompensator dispersi<br>7. Tambahkan analisis ketika kualitas sinyal menurun ketika menggunakan CFBG pada 16 kanal', '2025-03-05 08:20:53', '2025-03-30 09:41:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (248, 1, 540, 88, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang pre-defense pada hari jum\'at, 14 maret 2025 atas nama Fahrul Fahrizal (2100384) pada pukul 07.00-08.00 di ruang dosen 12-13, dengan dosen penguji dan pembimbing sebagai berikut:</p><p style=\"margin:0\">Dosen penguji:</p><p style=\"margin:0\">1. Dr. Yadi Mulyadi, M.T</p><p style=\"margin:0\">2. ⁠Prof. Dr. Jaja Kustija, M.Sc</p><p style=\"margin:0\">Dosen Pembimbing:</p><p style=\"margin:0\">Prof. Dr. Ade Gafar Abdullah, M.T.</p><p style=\"margin:0\">Penulis ucapkan terima kasih kepada dosen penguji dan pembimbing atas kehadirannya serta kritik dan saran kepada penulis agar skripsi yang telah dibuat menjadi lebih baik.</p>', '2025-03-06 18:03:56', '2025-03-17 20:28:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (249, 1, 585, 85, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre Defense&nbsp;</p><p style=\"margin:0\">Waktu sidang: Jum\'at\' 14 Maret 2025&nbsp;</p><p style=\"margin:0\">Durasi Presentasi: 09.00-10.00</p><p style=\"margin:0\">Tempat: Ruangan Lab. Elkom lantai 5 Gedung A FPTI UPI</p><p style=\"margin:0\">Dosen Pembimbing: Prof. Dr. Ade Gafar Abdullah, S.Pd, M.Si</p><p style=\"margin:0\">Dosen Penguji:&nbsp;</p><p style=\"margin:0\">1. Dr. Siscka Elvyanti, M.T&nbsp;</p><p style=\"margin:0\">2. Prof. Dr. Enjang Ahmad Juanda, M.Pd, M.T</p><p style=\"margin:0\">3. Erik Haritman, S.Pd, M.T</p><p style=\"margin:0\">Hasil Sidang Pre Defense 14 Maret 2025&nbsp;</p><p style=\"margin:0\">1. Perbaiki abstrak pada bagian implikasi, implikasi lebih spesifik.&nbsp;</p><p style=\"margin:0\">2. Hasil pembahasan dan metode yang pengaruh bergantung pada sumber literatur.</p><p style=\"margin:0\">3. Pembahasan secara teknis dalam kriteria pembangunan Floating Photovoltaic (FPV), tetapi prioritas kriteria salah satunya adalah kriteria economic assessment, yang dimana kriteria tersebut masuk dalam prioritas kriteria pembangunan FPV.</p>', '2025-03-06 22:55:21', '2025-04-10 22:12:04');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (250, 1, 579, 85, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Report Pre Defense 14 Maret 2025</p><p style=\"margin:0\">1. Penulisan di bagian abstrak dan bab 1 lebih dipertajam langsung membahas topik</p><p style=\"margin:0\">2. Terdapat beberapa kesalahan penulisan pada skripsi di bab 1 dan bab 4</p><p style=\"margin:0\">3. Penambahan saran yaitu pengembangan di bagian topik menjadi 5G</p><p style=\"margin:0\">4. Memperbaiki kembali parafrase kalimat agar sesuai dengan makna yang seharusnya</p>', '2025-03-07 06:46:02', '2025-03-17 14:01:05');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (251, 1, 504, 88, 4, 11, 1, 1, 1, '<p style=\"margin:0\">Saya Regina Nurul Cahya dengan NIM 2103914 telah melakukan Pre-Defense pada Jumat, 14 Maret 2025 Pukul 10.00-11.00 WIB. Terima kasih kepada para dosen yang terlibat dosen pembimbing, tim dosen penguji, tim dosen KBK, serta ketua program studi Teknik Elektro atas ilmu, wawasan, waktu, energi, beserta kesempatannya sehingga saya bisa melakukan Pre-Defense dengan baik. Semoga segala kebaikan Allah gantikan dengan pahala yang berlipat ganda. Aamiin.</p>', '2025-03-07 19:05:44', '2025-04-07 20:50:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (252, 1, 667, 89, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Sidang Pre-Defense, 11 April 2025</p><p style=\"margin:0\">Waktu : 07.00-08.00</p><p style=\"margin:0\">Pada sidang hari ini terdapat revisi dari dosen penguji diantaranya sebagai berikut.</p><p style=\"margin:0\">Dosen penguji yaitu pak erik haritman merevisi skripsi saya yaitu :</p><ol><li><span style=\"color: inherit; font-size: 1rem;\">merevisi kata pengantar</span></li><li><span style=\"color: inherit; font-size: 1rem;\">menambahkan kata indonesia dari EVCS, dan </span></li><li><span style=\"color: inherit; font-size: 1rem;\">typo-typo yang terdapat pada skripsi.</span></li></ol><p style=\"margin:0\">Selanjutnya, revisi dari pak wasim sebagai dosen penguji yaitu:</p><ol><li> kata-kata harus konsisten dari setiap babnya </li><li>Lalu revisi tabel dan pengurutan.</li></ol><p style=\"margin:0\">Lalu dari pak yadi yaitu :</p><ol><li>menambahkan kata pengantar mengenai EVCS.</li><li>menambahkan tabel frekuensi kemunculan sub-kriteria.</li></ol>', '2025-04-04 15:22:58', '2025-04-11 10:19:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (253, 1, 598, 89, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Hari/Tanggal Sidang: 11 April 2025</p><p style=\"margin:0\">Hasil diskusi dan saran dari sidang pada hari ini:</p><p style=\"margin:0\">1. Skripsi teknik tidak mengenal kuantitatif/kualitatif, hanya menjelaskan bagaimana metode penelitian dan masukan diagram alur penelitian nya saja</p><p style=\"margin:0\">2. Keterbaruan dari tren topik yang sedang dibahas</p><p style=\"margin:0\">3. Jelaskan devinisi kinerja, jelaskan bagaimana kinerja dari syarat-syarat umum nya</p><p style=\"margin:0\">4. Sajikan data apakah ada trip OCR dan GFR di 2 tahun pengujian</p><p style=\"margin:0\">5. Standar proteksi disebutkan di tujuan</p><p style=\"margin:0\">6. Penjelasan dari rumus</p><p style=\"margin:0\">7. Dasar teori dari pengaruh-pengaruh kinerja</p>', '2025-04-08 14:57:36', '2025-04-11 10:05:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (254, 1, 524, 91, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Pre defence telah dilaksanakan pada hari Selasa tanggal 15 April pukul 07.00-08.00. Terima kasih.</p>', '2025-04-10 13:58:18', '2025-04-17 13:56:48');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (255, 1, 518, 91, 3, 11, 1, 1, 1, '<p style=\"margin:0\">Saya telah melaksanakan sidang tertutup pada hari selasa 15 april 2025 jam 09.00 dengan dosen penguji bapak Wasimudin Surya Saputra, S. T, M. T. , bapak Agus Heri Setya Budi, S. T, M. T, dan bapak Dr. Bambang Trisno, MSIE</p>', '2025-04-10 14:21:29', '2025-04-16 10:59:01');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (256, 1, 560, 91, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Pre defense telah dilaksanakan pada 15 april 2025, pukul 08.00&nbsp;</p><p style=\"margin:0\">Terima kasih&nbsp;</p>', '2025-04-11 10:06:01', '2025-04-18 13:21:29');
