INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (258, 1, 609, 96, 2, 9, 1, 1, 1, '<p style=\"margin:0\">Pre defence telah dilaksanakan pada 14 Mei 2025, pada pukul 08.00 di Ruang kepala Lab Elkom&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Terima kasih</p>', '2025-04-29 10:49:48', '2025-05-14 19:43:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (259, 1, 554, 96, 1, 11, 1, 1, 1, '<p style=\"margin:0\">Pre defence telah daksanakam pada Rabu, 14 Mei 2025, pada pukul 07.00 di Ruang Dosen 12-13</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Terima kasih</p>', '2025-05-01 14:38:02', '2025-05-16 18:37:53');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (260, 1, 522, 96, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Pre defence telah daksanakam pada Rabu, 14 Mei 2025, pada pukul 08.00 di Ruang Dosen 12-13</p><p style=\"margin:0\">Terima kasih</p>', '2025-05-01 14:41:21', '2025-05-16 18:15:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (261, 1, 597, 95, 1, 10, 1, 1, 1, '<p style=\"margin:0\"><u>Pre-defense</u> yang dilaksanakan pada tanggal <u>23 Mei 2025</u>, atas nama <b>Alvin Dzaki Pratama Darmawan</b>, NIM 2104188,&nbsp;<span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">berjudul \"</span><span style=\"color: inherit; font-size: 1rem;\"><i>Landslide Prediction Data Processing Using Logistic Regression Algorithm\",&nbsp;</i>telah dilaksanakan dan diuji secara langsung oleh <b>Ibu Siscka Elvyanti</b> dan <b>Bapak Erik Haritman</b>.</span><span style=\"color: inherit; font-size: 1rem;\">&nbsp;pada sekitar pukul 07:00 WIB di FPTK, Gedung A, Lantai 3, Perpustakan FPTE.</span></p>', '2025-05-04 01:48:35', '2025-06-23 11:00:42');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (262, 1, 581, 95, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah sidang berjalan dengan lancar sesuai dengan jadwal yang telah ditentukan, namun masih ada beberapa hal yang harus direvisi dan revisinya akan segera dilakukan.</p>', '2025-05-06 15:18:30', '2025-08-12 11:33:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (263, 1, 555, 96, 3, 9, 1, 1, 1, '<p style=\"margin:0\">Pre-defence telah dilaksanakan pada Rabu 14 Mei 2025, pada pukul 09.00-10.00 di ruang ketua Lab. Telekomunikasi.</p><p style=\"margin:0\">Terima kasih</p>', '2025-05-08 09:38:35', '2025-05-16 22:40:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (264, 1, 500, 96, 4, 9, 1, 1, 1, '<p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><b><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">LAPORAN\nPELAKSANAAN SIDANG TERTUTUP</span></b><span style=\"font-size:12.0pt;font-family:\n&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:\nEN-ID\"><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Saya, Nur\nArmalita Purwati, mahasiswa Program Studi Teknik Elektro, telah melaksanakan\nsidang tertutup skripsi pada hari Rabu, 14 Mei 2025, bertempat di Ruang Ketua\nLab Telkom. Sidang ini merupakan salah satu tahapan akademik dalam penyelesaian\nskripsi dengan judul:<br>\n<b>\"PENGATURAN <i>POTENTIAL TRANSFORMER</i> (PT) PADA MODUL SINKRONISASI\nDAN <i>GENERATOR PROTECTION RELAY</i> DI PLTU CIREBON\"</b><o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Sidang\ntertutup ini dihadiri oleh tim penguji dan dosen pembimbing yang terdiri dari:<o:p></o:p></span></p><ol start=\"1\" type=\"1\">\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Dr. Aip Saripudin, M.T.<o:p></o:p></span></li>\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Wasimudin Surya Saputra,\n     S.T., M.T.<o:p></o:p></span></li>\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Dr. Siscka Elvyanti, M.T.<o:p></o:p></span></li>\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l1 level1 lfo1;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Dr. Ir. H. Dadang Lukman\n     Hakim, M.T.<o:p></o:p></span></li>\n</ol><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Kepada Tim KBK:<o:p></o:p></span></p><ol start=\"1\" type=\"1\">\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l0 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Dr. Aip Saripudin, M.T.<o:p></o:p></span></li>\n <li class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\n     line-height:normal;mso-list:l0 level1 lfo2;tab-stops:list 36.0pt\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:\n     &quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Didin Wahyudin, M.T., Ph.D.<o:p></o:p></span></li>\n</ol><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Dalam\npelaksanaan sidang, saya telah menyampaikan hasil penelitian yang telah\ndilakukan, serta menerima berbagai masukan dan saran konstruktif dari tim\npenguji sebagai bahan perbaikan untuk penyempurnaan naskah skripsi. Beberapa\ncatatan perbaikan telah disampaikan dan akan segera saya tindak lanjuti sebelum\nmemasuki tahapan sidang terbuka.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Saya mengucapkan\nterima kasih yang sebesar-besarnya kepada dosen pembimbing, tim penguji, tim\nKBK, serta seluruh pihak yang telah memberikan bimbingan dan dukungan selama\nproses penyusunan hingga pelaksanaan sidang tertutup skripsi ini. Semoga hasil\npenelitian ini dapat memberikan kontribusi positif di bidang teknik elektro,\nkhususnya dalam analisis sistem tenaga listrik.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\">Demikian\nlaporan ini saya susun sebagai bentuk pertanggungjawaban atas pelaksanaan\nsidang tertutup. Atas perhatian dan dukungannya, saya ucapkan terima kasih.<o:p></o:p></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\nline-height:normal\"><span style=\"font-size:12.0pt;font-family:&quot;Times New Roman&quot;,serif;\nmso-fareast-font-family:&quot;Times New Roman&quot;;mso-fareast-language:EN-ID\"><br>\nNur Armalita Purwati<br>\nNIM: 2100909<br>\nProgram Studi Teknik Elektro<o:p></o:p></span></p>', '2025-05-08 20:22:52', '2025-05-14 22:13:09');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (265, 1, 596, 96, 3, 11, 1, 1, 1, '<p style=\"margin:0\">1) Rumusan Masalah point 1 diganti menjadi \"Bagaimana mengintegrasikan hasil deteksi dari <i>computer vision&nbsp;</i>&nbsp;dan Radar FMCW untuk deteksi pejalan kaki?<br>2) Rumusan Masalah point 2 diganti menjadi \"Bagaimana performa sistem integrasi dalam mendeteksi pejalan kaki di ruang tertutup, ruang terbuka, dan jalan raya zebra cross?<br>3) Data pengukuran dari sisi YOLOv8s harusnya ditampilkan di tampilan GUI sistem<br>4) Faktor pencahayaan di Bab IV belum ada data pengukurannya<br>5) Flowchart perhitungan integrasinya ditambahkan<br>6) Urgensi tujuan penelitian untuk pejalan kakinya lebih ditekankan kembali<br>6) Rata-rata pengujiannya jangan diambil dari satu kali pengujian saja, tetapi dari seluruh pengujjian<br><br></p>', '2025-05-09 14:11:13', '2025-05-16 10:55:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (266, 1, 576, 95, 2, 10, NULL, 1, 1, NULL, '2025-05-12 10:32:21', '2025-05-14 13:34:13');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (267, 1, 613, 95, 2, 11, 1, 1, 1, '<ul><li><li><span style=\"color: inherit; font-size: 1rem;\">Wasimudin Surya Saputra terimakasih telah membimbing peneliti selama beberapa bulan, sehingga peneliti dapat menyelesaikan penelitian ini</span><br></li></li><li>Tasma Sucita: terimakasih atas masukan untuk bagian penulisan yang baik dan benar</li><li>Yadi Mulyadi : terimakasih atas saran dan pertanyaan yang telah diberikan kepada peneliti&nbsp;</li><li>Maman Somantri: terimakasih atas saran perbaikan hasil penelitian yang dilakukan peneliti, sehingga peneliti dapat memahami letak kesalahan penelitian yang dilakukan peneliti</li></ul>', '2025-05-14 11:59:21', '2025-06-06 13:45:01');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (268, 1, 607, 95, 1, 11, 1, 1, 1, '<p style=\"margin:0\">-Abstrak diperjelas untuk tujuan ,metodenya</p><p style=\"margin:0\">-next halaman sub tabel ditulis kembali</p><p style=\"margin:0\">-daftar pustaka tidak ada yang capslok</p><p style=\"margin:0\">-kesimpulan disamakan lagi dengn tujuan</p><p style=\"margin:0\">-gambar pada bab 4 diperjelas lagi agar mudah dimengerti</p>', '2025-05-14 12:03:25', '2025-06-17 16:50:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (269, 1, 606, 95, 3, 11, 1, 1, 1, '<p style=\"margin:0\">Pre-defence telah daksanakam pada 23 Mei 2025, pada pukul 09.00 di Ruang Dosen (12-13)<br><span style=\"color: inherit; font-size: 1rem;\"><br>Judul \"PENGARUH PERUBAHAN BEBAN TERHADAP EFISIENSI TRANSFORMATOR DAYA DI PT PLN INDONESIA POWER UBP SAGULING - SUB UNIT PLTA CIKALONG\"<br></span><span style=\"color: inherit; font-size: 1rem;\"><br>Dosen Pembimbing&nbsp;<br></span><span style=\"color: inherit; font-size: 1rem;\">Wasimudin Surya Saputra, S.T., M.T</span></p><p style=\"margin:0\">Dosen penguji<br><span style=\"color: inherit; font-size: 1rem;\">Dr. Tasma Sucita, M.T.<br></span><span style=\"color: inherit; font-size: 1rem;\">Dr. Ir. Maman Somantri, S.Pd., M.T<br></span><span style=\"color: inherit; font-size: 1rem;\">Dr. H. Bambang Trisno, M.SIE<br></span><span style=\"color: inherit; font-size: 1rem;\"><br>Hasil Pre-defence<br></span><span style=\"color: inherit; font-size: 1rem;\">1. Perbaiki struktur penulisan sesuai dengan pedoman<br></span><span style=\"color: inherit; font-size: 1rem;\">2. Kembangkan kembali hasil penelitian<br></span><span style=\"color: inherit; font-size: 1rem;\"><br>Terima kasih</span></p>', '2025-05-14 12:24:37', '2025-06-06 14:11:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (270, 1, 580, 95, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 23 Mei 2025 pukul 10.00-11.00, dihadiri oleh Dosen Pembimbing yaitu Ibu Ir. Hj. Arjuni Budi Pantjawati dan juga dihadiri Dosen Penguji, yaitu:</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">1. Ibu Dr. Siscka Elvyanti, M.T.</span></p><p style=\"margin:0\">2. Bapak Dr. Erik Haritman, S.Pd., M.T.</p><p style=\"margin:0\">2. Bapak Prof. Dr. Enjang Ahmad Juanda, M.Pd., M.T.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Tambahkan lebih banyak gambar pada BAB II</p><p style=\"margin:0\">2. Perbaiki penulisan, seperti singkatan dan penggunaan huruf tebal.</p><p style=\"margin:0\">3. Tambahkan pengujian integrasi dengan metode black box</p>', '2025-05-15 16:55:45', '2025-06-16 06:53:29');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (271, 1, 590, 100, 3, 2, 1, 1, 1, '<p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">LAPORAN HASIL\nSIDANG SKRIPSI<o:p></o:p></span></b></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Program Studi\nPendidikan Teknik Elektro</span></b><span style=\"font-size:12.0pt;line-height:\n107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"><br>\n<b>Fakultas Pendidikan Teknologi dan Kejuruan</b><br>\n<b>Universitas Pendidikan Indonesia</b><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">&nbsp;</span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Nama Mahasiswa:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\nmso-ansi-language:EN-ID\"> Linda Andriani N.<br>\n<b>NIM:</b> 2101397<br>\n<b>Judul Skripsi:</b><br>\nEvaluasi Keandalan Sistem Jaringan Distribusi 20 kV pada Penyulang TKYO\nMenggunakan Metode <i>Failure Mode and Effect Analysis</i> (FMEA) di PT. PLN\n(Persero)<o:p></o:p></span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Hari, Tanggal\nSidang:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"> Jumat, 13 Juni 2025<br>\n<b>Waktu:</b> 09.00 – 10.00 WIB<br>\n<b>Tempat:</b> Ruang Dosen 12 &amp; 13 Program Studi Pendidikan Teknik Elektro<br>\n<b>Dosen Penguji:</b><o:p></o:p></span></p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Dr. Tasma Sucita, M.T. – Penguji I<o:p></o:p></span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Dr. Bambang Trisno, M.SIE– Penguji II<o:p></o:p></span></li>\n</ol><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">&nbsp;</span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">CATATAN REVISI:<o:p></o:p></span></b></p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Abstrak:</span></b><span style=\"font-size:12.0pt;\n     line-height:107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:\n     EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Perbaiki struktur abstrak agar mencerminkan\n      secara lengkap tujuan, metode, hasil utama, dan kesimpulan penelitian.<o:p></o:p></span></li>\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Gunakan kalimat aktif dan pastikan konsistensi\n      antara abstrak bahasa Indonesia dan abstrak bahasa Inggris.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Rumusan Masalah Penelitian:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Rumusan masalah perlu lebih fokus dan spesifik\n      terhadap permasalahan keandalan serta penerapan metode FMEA.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab I (Pendahuluan):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Tambahkan <b>data dampak pemadaman secara statik</b>,\n      misalnya jumlah gangguan dalam setahun, total lama padam, jumlah\n      pelanggan terdampak, serta sektor-sektor vital yang terpengaruh.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab II (Tinjauan Pustaka):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Tambahkan <b>kajian teori pada Subbab 2.3</b>,\n      misalnya teori-teori penunjang mengenai keandalan distribusi, pendekatan\n      analisis risiko.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab III (Metodologi Penelitian):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Perbaiki sistematika penulisan agar lebih\n      runtut, terutama pada penjelasan.<o:p></o:p></span></li>\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Gunakan kalimat yang jelas dan sesuai kaidah\n      ilmiah; hindari pengulangan informasi.<o:p></o:p></span></li>\n </ul>\n</ol><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">&nbsp;</span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">FORMAT DAN TEKNIS\nPENULISAN:<o:p></o:p></span></b></p><p style=\"text-align: justify;\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><ul style=\"margin-top:0cm\" type=\"disc\">\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Periksa kembali format penulisan skripsi,\n     termasuk margin, jenis huruf, ukuran font, spasi, serta penomoran halaman,\n     tabel, dan gambar.<o:p></o:p></span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Sesuaikan penulisan daftar pustaka dengan pedoman\n     yang berlaku di Program Studi <o:p></o:p></span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Koreksi penulisan yang masih terdapat kesalahan\n     ketik atau ejaan yang tidak sesuai PUEBI.<o:p></o:p></span></li>\n</ul>', '2025-05-26 15:34:50', '2025-06-17 19:05:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (272, 1, 670, 100, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Revisi</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">1. Tambahkan terkait latar belakang atau lebih spesifik, terkait alasan meneliti, pokok-pokok pikiran, hubungannya diri efikasi diri ke identitas vokasional</span></p><p style=\"margin:0\">2. teori yang menyatakan efikasi diri berhubungan dengan identitas vokasional (perkuat), tambahkan juga kesimpulannya bahwa hasilnya memperkuat teori&nbsp;</p><p style=\"margin:0\">3. uji normalitas, tambahkan diagram nya, jelaskan seperti apa</p><p style=\"margin:0\">4. tambahan: kisi-kisi instrumen di bab 3, itu ada dijelaskan aspek instrumennya</p><p style=\"margin:0\">5. jelaskan kerangka berpikirnya, jangan dari febrianti, tapi efikasi diri dari bandura, identitas vokasional dari marcia</p>', '2025-05-31 20:11:12', '2025-06-17 12:58:13');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (273, 1, 334, 100, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 11 Juni 2025 pukul 08.00–09.00, dihadiri oleh dosen pembimbing dan penguji:</p><p style=\"margin:0\">Dosen Pembimbing:</p><p style=\"margin:0\">Bapak Resa Pramudita, S.Pd., M.T.</p><p style=\"margin:0\">Dosen Penguji:</p><p style=\"margin:0\">1. Bapak Dr. Erik Haritman, S.Pd., M.T.</p><p style=\"margin:0\">2. Ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.</p><p style=\"margin:0\">3. Ibu Prof. Dr. Hj. Budi Mulyanti, M.Si.</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, di antaranya:</p><p style=\"margin:0\">1. Pengujian dan Data:</p><p style=\"margin:0\">a. Hasil pengujian dan data perlu dijelaskan secara lebih rinci agar dapat digunakan sebagai dasar kesimpulan.</p><p style=\"margin:0\">b. Bab 3 tentang pengujian perlu dilengkapi dan diperinci lebih dalam.</p><p style=\"margin:0\">c. Data pengujian sistem harus disajikan secara sistematis dan mendukung analisis.</p><p style=\"margin:0\">2. Penulisan dan Teori:</p><p style=\"margin:0\">a. Tambahkan penjelasan mengenai metode pencarian jurnal dalam menyusun landasan teori.</p><p style=\"margin:0\">b. Tingkatkan literasi ilmiah dengan memperbanyak referensi jurnal yang relevan dan terbaru.</p><p style=\"margin:0\">c. Bab 2 perlu menggunakan informasi dan gambar yang sesuai dengan topik alat yang dirancang.</p><p style=\"margin:0\">3. Perbaikan Penulisan Akademik dan Penelitian:</p><p style=\"margin:0\">a. Kesimpulan harus berdasarkan data pengujian dan tidak bersifat umum.</p><p style=\"margin:0\">b. Perbaiki rumusan masalah dan tujuan penelitian agar lebih spesifik, konsisten, dan sejalan dengan latar belakang serta hasil.</p><p style=\"margin:0\">c. Batasan masalah, terutama poin 1 dan 2, perlu direvisi agar lebih fokus.</p><p style=\"margin:0\">d. Tegaskan objektif penelitian secara ilmiah dan terukur.</p><p style=\"margin:0\">e. Jelaskan gap (kesenjangan) dari penelitian sebelumnya secara lebih detail.</p><p style=\"margin:0\">f. Pendekatan penelitian sebaiknya bersifat kuantitatif, bukan kualitatif, karena melibatkan pengujian sistem.</p><p style=\"margin:0\">4. Struktur Laporan:</p><p style=\"margin:0\">a. Bab 4 dan 5 harus menunjukkan hasil evaluasi berdasarkan model R&amp;D.</p><p style=\"margin:0\">b. buat abstrak setelah akhir proses penyusunan agar mencerminkan hasil final.</p><p style=\"margin:0\">c. Pada abstrak, perbaiku kalimat agar tidak langsung mengklaim keberhasilan alat atau label yang belum ada. Gunakan frasa “berencana menjadikan Z4 sebagai label di masa depan.”</p><p style=\"margin:0\">5. Perangkat Keras dan Komponen:</p><p style=\"margin:0\">a. Berikan penjelasan dan perhitungan yang lebih rinci mengenai pemanfaatan dan peran masing-masing komponen dalam alat.</p><p style=\"margin:0\">b. Sertakan pula analisis terhadap kekurangan dari alat yang telah dibuat.</p><p style=\"margin:0\">6. Tambahan dari Dosen Pembimbing:</p><p style=\"margin:0\">a. Perbaiki sedikit bentuk fisik alat agar lebih rapi dan kokoh. Disarankan menggunakan bahan yang lebih kuat seperti kayu atau triplek, bukan kardus.</p><p style=\"margin:0\">b. Desain pada Bab 4 yang sebelumnya berupa gambar tangan perlu diubah menjadi desain 3D digital menggunakan software seperti Autodesk Fusion 360 (CAD) atau perangkat lunak sejenis.</p>', '2025-06-02 15:02:24', '2025-06-23 20:50:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (274, 1, 563, 98, 1, 9, 1, 1, 1, '<ul><li>Pre defence telah daksanakam pada 11 Juni 2025, pada pukul 07.00 di Ruang Ketua Lab Telekomunikasi</li></ul><div>Terima kasih</div>', '2025-06-03 16:02:50', '2025-06-17 15:20:44');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (275, 1, 645, 100, 2, 2, 1, 1, 1, '<p style=\"margin:0\">teruntuk bapak Dr. Yadi Mulyadi, M.T., terimakasih karna telah menjadi dosen pembimbing saya sehingga saya dapat menyelesaikan penelitian saya</p><p style=\"margin:0\">Teruntuk bapak Wasimudin Surya Saputra, S.Pd., M.T. dan Dr. Tasma Sucita, S.T.,M.T., terimakasih karena telah memberi saran dan masukan dalam skripsi saya sehingga saya dapat mengetahui hal apa yg perlu diperbaiki pada penelitian saya</p>', '2025-06-04 09:56:12', '2025-06-15 22:40:26');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (276, 1, 553, 98, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Pre Defense telah dilaksanakan pada Rabu, 11 Juni 2025 pukul 10.00 WIB - 11.00 WIB bertempat di Lab. Elektronika Dasar.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Terima Kasih</p>', '2025-06-04 19:28:20', '2025-06-11 12:15:44');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (277, 1, 558, 98, 2, 9, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 11 Juni 2025 pukul 08.00-9.00 di Lab. Eldas Gedung A FPTI UPI, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Aip saripudin, M.T.</p><p style=\"margin:0\">2.&nbsp;<span style=\"color: inherit; font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 1rem;\">Bapak Agus Heri Setyabudi, M.T.</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 1rem;\">3. Bapak Dr. Bambang Trisno, MSIE.</span></p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Memperbaiki beberapa kata yang masih typo atau salah ketik.</p><p style=\"margin:0\">2. Perbaiki perhitungan pada Bab 4.</p><p style=\"margin:0\">3. Memperbaiki kesimpulan dengan rumusan masalah.</p><p style=\"margin:0\"><span style=\"color: inherit; font-family: &quot;Source Sans Pro&quot;, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 1rem;\">4. Menambahkan beberapa kesimpulan dan rekomendasi penelitian</span></p>', '2025-06-05 08:45:32', '2025-06-20 11:40:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (278, 1, 602, 100, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 11 Juni 2025 pukul 07.00-08.00, dihadiri oleh dosen penguji:</p><ol><li>Ibu&nbsp;Dr. Siscka Elvyanti, MT</li><li><span style=\"color: inherit; font-size: 1rem;\">Ibu&nbsp;</span>Prof. Dr. Tuti Suartini, M.Pd</li><li>Bapak Dr. Erik Haritman, S.Pd., M.T.</li></ol><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><ul><li><span style=\"color: inherit; font-size: 1rem;\">Menambahkan </span><span data-start=\"258\" data-end=\"319\" style=\"color: inherit; font-size: 1rem;\">rujukan yang relevan terkait durasi penggunaan smartphone&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">untuk memperkuat dasar teoritis penelitian</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menjelaskan secara lebih jelas </span><span data-start=\"444\" data-end=\"494\" style=\"color: inherit; font-size: 1rem;\">alasan mengapa literasi digital perlu diteliti</span><span style=\"color: inherit; font-size: 1rem;\">, khususnya dalam konteks penggunaan smartphone oleh siswa SMK.</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menegaskan bahwa penelitian ini bersifat </span><span data-start=\"604\" data-end=\"625\" style=\"color: inherit; font-size: 1rem;\">korelasional umum</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menyampaikan </span><span data-start=\"737\" data-end=\"783\" style=\"color: inherit; font-size: 1rem;\">standar ideal durasi penggunaan smartphone</span><span style=\"color: inherit; font-size: 1rem;\"> dari berbagai sumber&nbsp;</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Memastikan bahwa </span><span data-start=\"875\" data-end=\"928\" style=\"color: inherit; font-size: 1rem;\">tidak terdapat treatment pada populasi penelitian</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Melakukan </span><span data-start=\"1000\" data-end=\"1049\" style=\"color: inherit; font-size: 1rem;\">refleksi kritis terhadap instrumen penelitian</span><span style=\"color: inherit; font-size: 1rem;\">, terutama dalam hal kesesuaian konteks dan kejelasan indikator terhadap karakteristik siswa SMK</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menambahkan dalam </span><span data-start=\"1170\" data-end=\"1243\" style=\"color: inherit; font-size: 1rem;\">kesimpulan nilai koefisien korelasi beserta signifikansi statistiknya</span><span style=\"color: inherit; font-size: 1rem;\">, agar interpretasi hasil lebih kuat dan terukur.</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menyertakan </span><span data-start=\"1310\" data-end=\"1369\" style=\"color: inherit; font-size: 1rem;\">penjelasan mengenai alasan distribusi data tidak normal</span><span style=\"color: inherit; font-size: 1rem;\">, serta menjelaskan konsekuensinya terhadap pemilihan uji statistik.</span></li><li><span style=\"color: inherit; font-size: 1rem;\">Menyempurnakan penjabaran </span><span data-start=\"1469\" data-end=\"1496\" style=\"color: inherit; font-size: 1rem;\">tujuan penelitian kedua</span></li><li><span data-start=\"1600\" data-end=\"1705\" style=\"color: inherit; font-size: 1rem;\">Menafsirkan angka-angka hasil analisis (seperti nilai korelasi dan signifikansi) dengan lebih naratif</span><span style=\"color: inherit; font-size: 1rem;\">, agar lebih mudah dipahami&nbsp;</span></li></ul>', '2025-06-05 11:00:54', '2025-06-17 05:54:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (279, 1, 521, 98, 5, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 11 Juni 2025 pukul 11.00-12.00 di Lab. Eldas Gedung A FPTI UPI, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Tasma Sucita, S.T, M.T.</p><p style=\"margin:0\">2. Bapak&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Agus Heri Setyabudi, M.T.</span></p><p style=\"margin:0\">3. Bapak&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Dr. Erik Haritman, S.Pd., M.T.</span></p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Memperbaiki beberapa kata yang masih typo atau salah ketik.</p><p style=\"margin:0\">2. Perbaiki daftar pustaka agar menggunakan huruf yang konsisten.</p><p style=\"margin:0\">3. Menambahkan beberapa materi atau landasan lagi di bab 2 agar teori yang dipakai jadi lebih kuat lagi.</p>', '2025-06-05 15:31:00', '2025-06-17 09:23:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (280, 1, 593, 100, 1, 2, 1, 1, 1, '<p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">LAPORAN HASIL\nSIDANG SKRIPSI<o:p></o:p></span></b></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Program Studi\nPendidikan Teknik Elektro</span></b><span style=\"font-size:12.0pt;line-height:\n107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"><br>\n<b>Fakultas Pendidikan Teknologi dan Kejuruan</b><br>\n<b>Universitas Pendidikan Indonesia</b><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">&nbsp;</span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Nama Mahasiswa:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\nmso-ansi-language:EN-ID\"> Afifah Tahta Arasyka<br>\n<b>NIM:</b> 2103042<br>\n<b>Judul Skripsi:</b><br>\nAnalisis Perancangan Pemasangan <i>Recloser</i> pada Jaringan Distribusi 20 kV di\nPenyulang TKYO PT PLN (Persero) UP3 Cimahi<o:p></o:p></span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">Hari, Tanggal\nSidang:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\"> Jumat, 13 Juni 2025<br>\n<b>Waktu:</b> 09.00 – 10.00 WIB<br>\n<b>Tempat:</b> Ruang Dosen 12 &amp; 13 Program Studi Pendidikan Teknik Elektro<br>\n<b>Dosen Penguji:</b><o:p></o:p></span></p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Prof. Dr. Jaja Kustija, M.Se &nbsp;– Penguji I</span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Dr. Bambang Trisno, M.SIE – Penguji II</span></li><li class=\"MsoNormal\"><span style=\"font-size: 12pt; line-height: 17.12px; font-family: &quot;Times New Roman&quot;, serif;\">Dr. Elih Mulyana, M.Si – Penguji III</span></li><li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n</ol><p class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:\n&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">&nbsp;</span></p><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">CATATAN REVISI:<o:p></o:p></span></b></p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Judul:</span></b><span style=\"font-size:12.0pt;\n     line-height:107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:\n     EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Judul “perencanaan” terlalu kompleks. Sebaiknya diskusikan\n      dengan dosen pembimbing mengenai judul. Lebih baik ditambahkan “Evaluasi”\n      atau “Analisis Perancangan”<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Abstrak:</span></b><span style=\"font-size:12.0pt;\n     line-height:107%;font-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:\n     EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Perbaiki struktur abstrak agar mencerminkan\n      secara lengkap tujuan, metode, hasil utama, dan kesimpulan penelitian.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Rumusan Masalah Penelitian:</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Rumusan masalah perlu lebih fokus dan spesifik\n      terhadap permasalahan keandalan serta pengaruh pemasangan <i>recloser </i>terhadap\n      nilai SAIDI dan SAIFI.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab I (Pendahuluan):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Tambahkan kondisi spesifik sebelum pemasangan <i>recloser\n      </i>pada latar belakang, misalnya jumlah gangguan dalam setahun, total\n      lama padam, jumlah pelanggan terdampak, serta sektor-sektor vital yang\n      terpengaruh.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab II (Tinjauan Pustaka):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Perbaiki sistematika penulisan agar lebih\n      runtut, terutama pada penjelasan.<o:p></o:p></span></li>\n </ul>\n <li class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Bab III (Metodologi Penelitian):</span></b><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\"><o:p></o:p></span></li>\n <ul style=\"margin-top:0cm\" type=\"circle\">\n  <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n      mso-ansi-language:EN-ID\">Flowchart langkah penelitian sebaiknya disatukan\n      saja, jangan dipisah.<o:p></o:p></span></li>\n </ul>\n</ol><p class=\"MsoNormal\"><b><span style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif;mso-ansi-language:EN-ID\">FORMAT DAN TEKNIS\nPENULISAN:<o:p></o:p></span></b></p><ul style=\"margin-top:0cm\" type=\"disc\">\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Periksa kembali format penulisan skripsi,\n     termasuk margin, jenis huruf, ukuran font, spasi, serta penomoran halaman,\n     tabel, dan gambar.<o:p></o:p></span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Sesuaikan penulisan daftar pustaka dengan pedoman\n     yang berlaku di Program Studi <o:p></o:p></span></li>\n <li class=\"MsoNormal\"><span style=\"font-size:12.0pt;line-height:107%;font-family:&quot;Times New Roman&quot;,serif;\n     mso-ansi-language:EN-ID\">Koreksi penulisan yang masih terdapat kesalahan\n     ketik atau ejaan yang tidak sesuai PUEBI.<o:p></o:p></span></li>\n</ul><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\"><span lang=\"IN\">&nbsp;</span></p>', '2025-06-05 15:55:00', '2025-07-10 17:20:28');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (281, 1, 443, 100, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 11 Juni 2025 pukul 10.00-11.00, dihadiri oleh kedua dosen penguji.</p><p style=\"margin:0\">Pelaksanaan sidang tertutup berjalan dengan lancar, baik dari penyampaian penelitian, pemberian pertanyaan dan jawaban, serta feedback dari hasil penelitian.</p><p style=\"margin:0\">Terdapat beberapa masukan setelah sidang diantaranya:</p><p style=\"margin:0\">1. Menyesuaikan kembali dengan pedoman penulisan UPI</p><p style=\"margin:0\">2. Menambahkan alasan dari efek perbedaan pengukuran</p>', '2025-06-05 17:07:34', '2025-06-12 21:52:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (282, 1, 617, 101, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Perbaikan blok diagram dan flowchart</p>', '2025-06-10 14:43:37', '2025-07-07 13:13:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (283, 1, 750, 103, 4, 1, 1, 1, 1, 'The pre-defense has been done with several suggestions from the examiners.<br><br>1. There is a need to use consistent pronouns for the participant.<br>2. Using English in presentation should be more confident and control, especially the tempo<br>3. There\'s still a lack of data treatment report, like data homogenity, how to confirming gain from treatment, how to confirmed the cause-effect due to small population.<br><br><br>There are also questions, such as:<br><br>1. What is the reason of using lora for the research<br>2. Why using TAM and why analyzed it using regression<br>3. How to measure that the implementation of the technology is effective.<br>4. Why keep using small participant<br><br>There\'s also a discussion, such as:<br><br>The final result of the research findings might be like that (Acceptance rate has no correlation with Effectiveness of technology) due to the use of One-group pretest-posttest, which usually used in pre-research. Also, might be about the instruments.<br>', '2025-06-23 09:47:59', '2025-07-10 19:49:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (284, 1, 663, 103, 2, 1, 1, 1, 1, '<p style=\"margin:0\">* pertimbangkan judul \"penerapan\"<br>* tambahkan keterangan untuk tabel persentil<br>* kesimpulan jadikan 1 paragraf<br>* bab 2 tambahkan penelitian relevan, untuk memetakan gap penelitian<br>* bab 4 tambahkan analisis naik turun grafik<br>* bab 1 tambahkan urgensi penerapan ai dalam kurikulum smk&nbsp;</p>', '2025-06-23 19:12:51', '2025-07-14 09:41:09');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (285, 1, 587, 103, 5, 2, 1, 1, 1, '<p style=\"margin:0\">Sidang Tertutup sudah dilaksanakan pada 9 Juli 2025, terimakasih</p>', '2025-06-26 10:19:59', '2025-07-15 08:07:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (286, 1, 728, 103, 5, 1, 1, 1, 1, '<p style=\"margin:0\">Pre-Defense: Rabu, 9 Juli 2025</p><p style=\"margin:0\">Dosen Pembimbing:&nbsp;<span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">Dr. Saripudin, S.PD., M.T.</span></p><p style=\"margin:0\"><span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">Dosen Penguji:&nbsp;</span></p><p style=\"margin:0\"><span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">1.&nbsp;</span><span style=\"color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px; background-color: rgba(0, 0, 0, 0.075);\">Dr. Aip Saripudin, M.T.</span></p><ul><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">perbaiki ucapan terimakasih, ucapan terimakasih diperuntukan untuk yang berperan penting dalam skripsi.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">hilangkan judul dan nama pada abstrak serta tambahkan latar belakang pada abstrak.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">ubah kata et al menjadi dkk.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">kata sebagai berikut yang merujuk pada tabel ganti dengan nama tabelnya saja.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">tabel yang terpotong tambahkan header lagi.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">pada angka standar deviasi samakan jumlah angka di belakang koma.</span></font></li><li><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">tambahkan nama di grafik pada sumbu Y.</span></font></li></ul><p style=\"margin:0\"><font color=\"#111111\" face=\"Lato, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica Neue, Arial, sans-serif, Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol\"><span style=\"font-size: 14px;\">2.&nbsp;</span></font><span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">Prof. Dr. Tuti Suartini, M.Pd.</span></p><ul><li><span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span></li><li>ebih baik hilangkan kata Daya Ingat di judul.</li><li>sebaiknya ubah uji normalitas dengan teknik yang lain karena sampelnya kurang dari 50.</li><li>tambahkan Uji Hipotesis yang sesuai.</li></ul><p style=\"margin:0\">3.&nbsp;<span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">Wawan Purnama, S.Pd., M.Si.</span></p><ul><li><span style=\"background-color: rgba(0, 0, 0, 0.075); color: rgb(17, 17, 17); font-family: Lato, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;; font-size: 14px;\">-</span></li></ul>', '2025-06-26 10:36:04', '2025-07-11 18:37:45');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (287, 1, 648, 103, 2, 2, 1, 1, 1, '<ul><li>perbaiki abstrak (main problem dan urgensi penelitian)</li><li>perbaiki tabel pada hal 15-18</li><li>perbedaan kontrol dan smart kontrol</li><li>tambahkan informasi pada schematic rangkaian</li><li>tambahkan blok diagram rangkaian</li><li>kesimpulan tidak selaras dengan&nbsp; tujuan</li></ul>', '2025-06-26 12:29:49', '2025-07-21 10:22:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (288, 1, 668, 103, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Alhamdulillah saya sudah melaksanakan sidang tertutup pada tanggal 9 juli 2024, terimakasih</p>', '2025-06-26 12:40:57', '2025-07-21 14:38:21');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (289, 1, 516, 103, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Saya sudah melaksanakan sidang tertutup pada tanggal 09 Juli 2025 pukul 09.00-10.00 Wib bertempat di Lab Elkom Lt. 5 Gd. A. Terimakasih</p>', '2025-06-27 07:19:19', '2025-07-16 11:50:52');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (290, 1, 641, 103, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabarakatuh<br><br>Alhamdulillah saya telah melaksanakan sidang pada tanggal 9 Juli 2025. Untuk revisian dan masukan sudah saya perbaiki dan ditambahkan sebagai berikut:<br>Revisi<br>1. Perbaikan kalimat untuk abstrak bahasa inggris.<br>2. Perbaikan kesalahan penulisan pada bab 5<br>3. pemindahan data dari bab 3 ke bab 4<br>4. pergantian sub-bab pada bab 4<br>5. perbaikan struktur pada bab 3<br><br>Masukan<br>1. penambahan desain penelitian<br>2. penambahan block diagram governor<br><br>Terima kasih<br>Wassalamualaikum warahmatullahi wabarakatuh</p>', '2025-06-30 09:15:56', '2025-07-18 21:14:43');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (291, 1, 656, 103, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Telah melaksanakan Pre Defense pada hari Rabu tanggal 9 Juli 2025 dengan dosen penguji:<span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span></p><ol><li><span style=\"color: inherit; font-size: 1rem;\">Ir. Hj. Arjuni Budi Pantjawati, M.T.</span></li><li>Dr. Yadi Mulyadi, M.T.</li><li>Dr. Erik Haritman, S.Pd., M.T.</li></ol><p style=\"margin:0\">Dan dengan terdapat revisi pada Bab 3</p>', '2025-07-02 10:09:16', '2025-07-11 11:53:05');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (292, 1, 727, 103, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Revisi Prof. Jaja Kustija :</p><p style=\"margin:0\">1. Ubah abstrak, tambah metode</p><p style=\"margin:0\">2. flowchart model</p><p style=\"margin:0\">3. formatting</p><p style=\"margin:0\">Revisi Bapak Dr. Aip Saripudin :</p><p style=\"margin:0\">1. Perubahan titik pada persen menjadi koma</p><p style=\"margin:0\">2. Gambar harus disebut pada paragraph</p><p style=\"margin:0\">3. Perubahan et al pada sitasi menjadi dkk</p><p style=\"margin:0\">4. Rumus dan singkatan diberi keterangan</p><p style=\"margin:0\">5. Data yang bersifat privasi jangan di blur semua</p><p style=\"margin:0\">6. Data pada data transformation di ubah</p><p style=\"margin:0\">7. Cari rumus untuk mencari akurasi</p><p style=\"margin:0\">8. Ubah kesimpulan menjadi fokus kepada tujuan penelitian saja</p>', '2025-07-02 13:17:25', '2025-07-10 20:31:13');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (293, 1, 501, 109, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Pada Rabu 16 Juli 2025 pukul 08.00 - 09.00 Alhamdulillah telah dilaksanakan sidang pre-defense, dengan dihadiri oleh dosen pembimbing yang terhormat dan saya banggakan : bapak Dr. Yadi Mulyadi, M.T., para dosen penguji yang terhormat dan saya banggakan: Bapak Dr. Tasma Sucita, ST.MT., Bapak Dr.Ir. Maman Somantri, S.Pd. MT.,IPM, Bapak Dr. Elih Mulyana, M.Si.</p><p style=\"margin:0\">Sangat banyak masukan membangun yang saya peroleh dari sidang pre defense hari ini. interaksi yang hangat, pertanyaan-pertanyaan yang membuat saya semakin paham untuk lebih berbenah lagi.</p><p style=\"margin:0\">beberapa rangkuman pertanyaan dan hal hal yang saya harus diperbaiki untuk kedepannya.</p><p style=\"margin:0\">- Penulisan berdasarkan pada pedoman UPI, ada kekeliruan di bab 2 yaitu studi pendahuluan dan perlu ditambahkan kemudian dikaji ulang. (Bapak Tasma Sucita)</p><p style=\"margin:0\">- Rumusan harus sesuai (matching) dengan temuan dan pembahasan dan harus ada jawaban di bab temuan dan pembahasan, misalnya dengan membuat pengelompokan data jawaban di bab temuan dan pembahasan berdasarkan rumusan masalah (Bapak Tasma Sucita)</p><p style=\"margin:0\">- Koordinasi relai atau individual reai? (Bapak Maman Somantri)</p><p style=\"margin:0\">-Diantara relai OCR dan GFR mana yang merupakan relai utama? berdasarkan apa (Bapak Maman Somantri)</p><p style=\"margin:0\">-Tambahkan di latar belakang tentang dampak yang akan dihadapi PLN ketika tidak terjadi penyaluran listrik kepada konsumen (Bapak Elih Mulyana)</p><p style=\"margin:0\">-Pada bab pembahasan rentang grafik diperbaiki (Bapak Elih Mulyana)</p><p style=\"margin:0\">-Penulisan Bab 3 supaya tidak ada space kosong, diperbaiki untuk penempatan diagram alirnya (Pak Yadi Mulyadi)</p><p style=\"margin:0\">-Untuk bab rumusan masalah sudah bagus mulai dari identifikasi masalah kemudian beranjak ke perumusan masalah cukup detail (Pak Tasma Sucita)</p><p style=\"margin:0\">Terimakasih semoga selalu diberi kesehatan dan panjang umur untuk para dosen tercinta.</p><p style=\"margin:0\"><br></p>', '2025-07-03 05:48:23', '2025-07-16 12:20:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (294, 1, 517, 109, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Link skripsi yang sudah di revisi : https://drive.google.com/file/d/1xk6ALfmhKhF3LFTuMSZ_-vujSqhZWBhm/view?usp=sharing</p>', '2025-07-03 06:11:18', '2025-07-20 17:29:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (295, 1, 545, 109, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Revisi Tugas Akhir :<br>1. Daftar Pustaka di urutkan sesuai abjad.<br><span style=\"color: inherit; font-size: 1rem;\">2. Ada bagian sitasi yang tidak di masukan ke daftar pustaka.<br>3. Bahasa Inggris harus cetak miring.<br>4. Tingkat keberhasilan / dampak positif dari prototipe dimasukan dalam rumusan masalah atau dimasukan dalam latar belakang.<br>5.&nbsp; Sitasi hanya nama depan dan belakang, kemudian diganti dkk.<br>6. Sumber foto tidak perlu.<br>7. Untuk rumus kurang tanda kurung dan semua di sesuaikan dengan satuan SI.<br>8. Harus menjelaskan di bagian analisis hasil bahwa yang mencoba hanya 5 orang dan sisanya observasi.<br>9. Gambar harus dibahas di bagian penjelasan dan dijelaskan.<br>10. Pengambilan jarak harus dijelaskan kenapa mengambil jarak sekian.<br>11. Dijelaskan bahwa 60 cm jarak terakhir dalam deteksi objek pada sensor infrared.<br>12. menambahkan penjelasan pengujian jarak perangkat antara ground station dengan airbone.<br>13. satuan pengukuran jarak di ukur menggunakan milimeter.<br>14. Abstrak dimasukan tentang alasan penting dalam membuat prototipe DME dan banyak typo di abstrak.<br>15. Kaprodi sudah bukan pak Iwan.&nbsp;</span></p><p style=\"margin:0\"><br></p>', '2025-07-03 06:46:12', '2025-07-18 19:32:15');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (296, 1, 574, 109, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Revisi:&nbsp;</p><p style=\"margin:0\">1. Tambahkan keterangan gambar</p><p style=\"margin:0\">2. Buat skema plts off grid pada more coffe &amp; space tersebut</p>', '2025-07-03 14:06:37', '2025-08-05 15:11:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (297, 1, 424, 109, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang pada Rabu, 16 Juli 2025</p>', '2025-07-08 10:26:54', '2025-07-24 07:59:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (298, 1, 671, 104, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabarakatuh<br><span style=\"color: inherit; font-size: 1rem;\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 22 Juli 2025. Untuk perbaikan dan masukan yaitu:</span></p><p style=\"margin:0\">1. ketidak konsistenan judul pada lembar skripsi dan ucapan terimakasih&nbsp;<br><span style=\"color: inherit; font-size: 1rem;\">2. perbaiki judul agar lebih menarik dan coba tambahkan metode dan analisis seperti CBM dan perhitungan saidi saidi di judul agar lebih spesifik</span></p>', '2025-07-08 10:40:31', '2025-07-31 15:21:49');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (299, 1, 411, 109, 1, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang telah dilaksanakan pada Hari Rabu Tanggal 16 Juli 2026 pukul 07.00-08.00 WIB</p>', '2025-07-08 10:48:26', '2025-07-17 22:18:55');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (300, 1, 703, 109, 4, 1, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 16 Juli 2025 pada pukul 10.00-11.00 yang dihadiri oleh dosen pembimbing yaitu Bapak Dr. Tasma Sucita, S.T., M.T. dan dosen penguji:</p><p style=\"margin:0\">1. Bapak Dr. Elih Mulyana, M.Si.</p><p style=\"margin:0\">2. Bapak Dr. H. Bambang Trisno, M.SIE.</p><p style=\"margin:0\">3. Bapak Didin Wahyudin, S.Pd., M.T., Ph.D.</p><p style=\"margin:0\">Beberapa saran untuk skripsi setelah sidang dilaksanakan ialah:</p><p style=\"margin:0\">1. Tambahkan perbedaan karakteristik IEEE 9-bus dengan jaringan aktual PLTU Indramayu. Jika tidak memungkinkan, berikan keterangan keterbatasan akses data jaringan aktual.</p><p style=\"margin:0\">2. Tambahkan referensi (rujukan) yang berkaitan dengan optimalnya penurunan biaya pembangkitan yang hasilnya kecil (tidak signifikan), untuk memperkuat pernyataan mengenai hasil temuan simulasi optimasi yang sangat kecil.</p><p style=\"margin:0\">3. Sebaiknya menambahkan alasan penggunaan variasi data historis operasional yang digunakan dalam meregresikan fungsi biaya.</p><p style=\"margin:0\">4. Tambahkan sensitivitas konvergensi iterasi Newton-Raphson terhadap variasi beban sistem.</p>', '2025-07-08 11:36:06', '2025-07-16 15:52:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (301, 1, 692, 104, 2, 1, 1, 1, 1, '<p style=\"margin:0\">1. Pada abstrak tata bahasanya masih kurang bagus dan kurang saling berkaitan secara keseluruhan</p><p style=\"margin:0\">2. Masih terdapa kata-kata yang typo</p><p style=\"margin:0\">3.&nbsp; Penggunaan tanda baca yang salah</p><p style=\"margin:0\">4. Penulisan rumus kurang tepat</p><p style=\"margin:0\">5. Penempatan tabel dan gambar ada kesalahan</p>', '2025-07-10 15:33:39', '2025-08-05 09:58:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (302, 1, 660, 109, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Telah melaksanakan sidang pre-defense pada Rabu, 16 Juli 2025 di Ruang Lab.Telkom Lantai 5 Gedung A</p>', '2025-07-10 20:34:54', '2025-07-17 21:24:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (303, 1, 640, 106, 3, 10, 1, 1, 1, '<pre style=\"text-align:justify;text-indent:14.2pt;\nline-height:150%;tab-stops:36.0pt\"><span style=\"font-size:12.0pt;line-height:\n150%;font-family:&quot;Times New Roman&quot;,serif\">Berdasarkan hasil diskusi dengan dosen pembimbing setelah proses ujian sidang maka dibuat tabel sebagai respon terkait pertanyaan dan saran yang diberikan oleh dosen penguji.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%;tab-stops:36.0pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penguji:<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Prof. Dr. Ade Gafar Abdulah, S.Pd., M.Si.<o:p></o:p></span></pre><table class=\"MsoTableGrid\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" width=\"529\" style=\"margin-left: -0.25pt; border: none;\">\n <tbody><tr>\n  <td width=\"34\" valign=\"top\" style=\"width: 25.5pt; border-width: 1pt; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-color: windowtext; border-image: initial; padding: 0cm 5.4pt;\"><pre style=\"text-align:center;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">No<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width: 137.55pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Komentar<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width: 233.85pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Respon<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">1.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Biasanya dalam proses <i>machine learning </i>itu kan yang dilihat nya adalah error nya yang berapa, nah kenapa kamu akurasi (mAP) yang di pilih?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Menurut penelitian Zhao et al., tahun 2024, </span><em><span style=\"font-size:12.0pt;line-height:150%;mso-fareast-font-family:&quot;Times New Roman&quot;;\n  mso-fareast-theme-font:major-fareast\">Mean Average Precision</span></em><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\"> (mAP) merupakan metrik evaluasi paling krusial dan menjadi standar industri untuk mengevaluasi sistem deteksi objek, termasuk deteksi kematangan buah. mAP sangat penting untuk mengevaluasi model YOLO karena menyediakan metrik tunggal yang mengenkapsulasi </span><em><span style=\"font-size:12.0pt;line-height:150%;mso-fareast-font-family:&quot;Times New Roman&quot;;\n  mso-fareast-theme-font:major-fareast\">precision</span></em><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\"> dan </span><em><span style=\"font-size:12.0pt;line-height:150%;mso-fareast-font-family:&quot;Times New Roman&quot;;\n  mso-fareast-theme-font:major-fareast\">recall across multiple classes. Di jelaskan pada hal 2-3 </span></em><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\"><o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">2.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Untuk dataset dan program disarankan untuk di <i>public</i> supaya nanti orang-orang lain bisa mengembangkan kedepannya<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Terkait dataset dan program sudah di upload di github sehingga orang-orang bisa akses lewat github tersebut, berikut link github nya <br>\nhttps://github.com/Saepulrohman12/Computer-Vision-Strawberry-Detection.git<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">3.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Kenapa harus varietas tristar yang dipilih kenapa ga varietas stroberi yang lainnya?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Varietas stroberi tristar adalah salah satu varietas <em>day-neutral</em> atau <em>ever-bearing</em> hasil pengembangan untuk produksi komersial. Karakteristik unik varietas ini terletak pada kemampuannya berbuah sepanjang musim tanpa tergantung pada panjang hari (<em>photoperiod</em>), berbeda dengan varietas <em>June-bearing</em> hanya berbuah sekali dalam setahun </span><!--[if supportFields]><span\n  style=\'font-size:12.0pt;line-height:150%;font-family:\"Times New Roman\",serif\'><span\n  style=\'mso-element:field-begin;mso-field-lock:yes\'></span>ADDIN CSL_CITATION {&quot;citationItems&quot;:[{&quot;id&quot;:&quot;ITEM-1&quot;,&quot;itemData&quot;:{&quot;DOI&quot;:&quot;10.1093/hr/uhae309&quot;,&quot;ISSN&quot;:&quot;20527276&quot;,&quot;abstract&quot;:&quot;Cultivated strawberry (Fragaria x ananassa) is a globally important fruit crop that shows promise as a candidate for various methods of controlled environment production. However, a better understanding of the mechanisms of the regulation of flowering is needed, as more frequent or consistent flowering would be advantageous in controlled production. It is well understood that flowering in F. x ananassa responds to both photoperiod and temperature; however, the mechanism behind this response is not fully understood, particularly in perpetually flowering cultivars. While some genes of interest have been identified, a more complete model has not been established. This is largely due to the complexity of the octoploid genome and a lack of current knowledge on the mechanism of temperature response in both seasonal- and perpetual-flowering F. x ananassa. A starting point for developing a better model of flowering response in cultivated strawberries lies in the simpler Fragaria vesca, which indicates an FvCO-FvFT1-FvSOC1-FvTFL1 module for control of seasonal flowering and a lack of functional FvTFL1 responsible for perpetual flowering. However, there are some key differences when discussing F. x ananassa’s perpetual flowering characteristics. Recent studies have helped to elucidate some of these differences, allowing for a putative model of seasonal flowering in F. x ananassa, as well as indicating where further questions need to be asked regarding perpetually flowering cultivars.&quot;,&quot;author&quot;:[{&quot;dropping-particle&quot;:&quot;&quot;,&quot;family&quot;:&quot;Darby&quot;,&quot;given&quot;:&quot;Ethan&quot;,&quot;non-dropping-particle&quot;:&quot;&quot;,&quot;parse-names&quot;:false,&quot;suffix&quot;:&quot;&quot;},{&quot;dropping-particle&quot;:&quot;&quot;,&quot;family&quot;:&quot;Islam&quot;,&quot;given&quot;:&quot;Tabibul&quot;,&quot;non-dropping-particle&quot;:&quot;&quot;,&quot;parse-names&quot;:false,&quot;suffix&quot;:&quot;&quot;}],&quot;container-title&quot;:&quot;Horticulture Research&quot;,&quot;id&quot;:&quot;ITEM-1&quot;,&quot;issue&quot;:&quot;2&quot;,&quot;issued&quot;:{&quot;date-parts&quot;:[[&quot;2025&quot;]]},&quot;title&quot;:&quot;Environmental and molecular regulation of flowering in cultivated strawberry (Fragaria x ananassa)&quot;,&quot;type&quot;:&quot;article-journal&quot;,&quot;volume&quot;:&quot;12&quot;},&quot;uris&quot;:[&quot;http://www.mendeley.com/documents/?uuid=2b99d963-7a0d-4857-aba2-e522efe42f6c&quot;]}],&quot;mendeley&quot;:{&quot;formattedCitation&quot;:&quot;(Darby &amp; Islam, 2025)&quot;,&quot;plainTextFormattedCitation&quot;:&quot;(Darby &amp; Islam, 2025)&quot;,&quot;previouslyFormattedCitation&quot;:&quot;(Darby &amp; Islam, 2025)&quot;},&quot;properties&quot;:{&quot;noteIndex&quot;:0},&quot;schema&quot;:&quot;https://github.com/citation-style-language/schema/raw/master/csl-citation.json&quot;}<span\n  style=\'mso-element:field-separator\'></span></span><![endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">(Darby &amp; Islam, 2025)</span><!--[if supportFields]><span\n  style=\'font-size:12.0pt;line-height:150%;font-family:\"Times New Roman\",serif\'><span\n  style=\'mso-element:field-end\'></span></span><![endif]--><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\"> ditunjukkan pada hal 16, dan kebetulan untuk tempat saya mengambil data di perkebunan stroberi rancabali, kab.bandung itu varietas nya tristar.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">4. <o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penelitian kamu ini termasuknya <i>supervised learning</i> atau <i>unsupervised learning</i>? dan kenapa alasannya?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Penelitian saya ini termasuk <i>supervised learning </i>karena ada data yang berlabel dan memiliki model yang dilatih untuk memprediksi output berdasarkan input, seperti gambar stroberi yang dilabeli dengan beberapa kategori belum matang, setengah matang, matang, terlalu matang<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">5.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam proses penelitian apa yang paling menjadi kendala?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam proses pra-pemrosesan data karena data 3699 harus di labeli satu per satu dengan tingkat kategori yang berbeda-beda, sehingga membutuhkan waktu yang cukup lama, lalu pada saat proses <i>training</i> yang membutuhkan waktu cukup lama sampai satu harian apabila tidak mencapai target akurasi yang diinginkan harus di <i>training </i>ulang dengan penambahan modifikasi di bagian <i>epochs </i>dan di file hyperparameter nya<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">6.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Terkait kategori kematangan stroberi kenapa mengambil empat kategori tersebut? Saran karena pada saat dilapangan para petani itu memanen buah stroberi nya tidak pas banget matang karena ada proses ekspor yang membutuhkan beberapa hari sehingga buah stroberi itu bisa matang diperjalanan<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam proses panen petani memang hanya mengambil stroberi yang sudah matang tetapi secara kasat mata petani terkadang suka kebingungan antara setengah matang, matang dan terlalu matang, sehingga pada saat proses panen ada beberapa stroberi yang sudah tidak layak untuk di pasarkan, sehingga penelitian ini bertujuan untuk membedakan tingkat kematangannya secara akurat menggunakan aplikasi.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">7.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Kenapa harus <i>learning rate </i>nya 0,001? Kalau nilai <i>default </i>dari YOLOv5 nya berapa?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">karena merupakan nilai yang relatif stabil dan umum digunakan pada saat fine-tuning model pretrained seperti YOLOv5. Nilai ini membantu proses pembelajaran model agar tidak terlalu cepat atau terlalu lambat saat melakukan penyesuaian terhadap fitur baru dari dataset stroberi tristar, apabila terlalu besar dapat menyebabkan model kehilangan pengetahuan awal, apabila terlalu kecil juga akan membuat training menjadi sangat lambat, nilai default dari YOLOv5 0.01<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">8.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Kenapa proses training awal harus 50 <i>epochs</i>?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Untuk proses training awal dilakukan 50 <i>epochs </i>dilakukan agar <i>head </i>model beradaptasi dulu ke data baru, lalu tahap kedua<i> unfreeze </i>agar <i>backbone </i>juga bisa belajar fitur yang lebih spesifik dan dilakukan optimasi sehingga nilai akurasi lebih meningkat, karena jika semua layer langsung dilatih semua dengan nilai <i>epochs </i>yang tinggi model bisa mengalami <i>overfitting </i>atau ketidakstabilan di awal <i>training.</i> Dan dapat di lihat pada gambar grafik 4.4a hal 45 bahwa di rentang <i>epochs </i>10 sudah mengalami saturasi yang dimana tidak ada peningkatan atau penurunan yang signifikan.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">9.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Di bagian tabel 3.2 kenapa dataset <i>training </i>lebih banyak dibandingkan yang lain? Lalu kenapa rasionya 8:1:1?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Karena tujuan utama model <i>machine learning </i>adalah belajar dari data maka data <i>training </i>perlu diberikan jumlah yang cukup besar, agar model bisa mengenali pola dan variasi data secara menyeluruh, menghindari underfitting karena data terlalu sedikit, apabila terlalu sedikit model akan sulit untuk belajar.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">80%: cukup untuk pembelajaran optimal.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">10%: cukup untuk tuning parameter dan early stopping.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%;tab-stops:91.6pt\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">10%: cukup untuk mengukur generalisasi akhir.<o:p></o:p></span></pre></td>\n </tr>\n</tbody></table><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dr. Erik Hartiman, S.Pd., M.T.<o:p></o:p></span></pre><table class=\"MsoTableGrid\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" width=\"529\" style=\"width: 14cm; margin-left: -0.25pt; border: none;\">\n <tbody><tr>\n  <td width=\"34\" valign=\"top\" style=\"width: 25.5pt; border-width: 1pt; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-color: windowtext; border-image: initial; padding: 0cm 5.4pt;\"><pre style=\"text-align:center;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">No<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width: 137.55pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Komentar<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width: 233.85pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Respon<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">1.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Tolong jelaskan kembali terkait gambar 3.8, kan disitu ada 2 ouput nah yang dipakai itu output yang pertama atau yang kedua? Saran untuk gambar nya nanti diperbaiki supaya memperjelas proses <i>transfer learning</i> dan <i>Fine-tuning</i><o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Untuk skematik struktur <i>transfer learning</i> dan <i>fine-tuning, </i>output yang digunakan adalah yang kedua untuk output yang pertama itu nantinya akan di <i>training </i>lagi untuk dilakukan proses <i>fine tuning</i> dengan bagian <i>backbone </i>di <i>unfreeze </i>sehingga semua layer di <i>training</i>. Gambar sudah di perbaiki di gambar 3.8 pada hal 34 diberikan highlight warna hijau<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">2.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Pada hal 36 untuk proses <i>preprocessing</i> bagian normalisasi rentang 0-255 menjadi 0-1 itu maksud nya warna atau apa? Tolong jelaskan bagaimana proses konversi nya itu? Apakah itu termasuk grayscale?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Gambar digital berwarna (RGB) pada umumnya memiliki nilai intensitas piksel dalam rentang 0 hingga 255 <a name=\"_Hlk203849408\">untuk setiap kanal warna (<i>Red, Green, Blue</i>)</a>. Jadi, satu piksel bisa bernilai:<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">R = 120<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">G = 200 <o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">B= 75 <o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Ketika dilakukan normalisasi, setiap piksel dibagi dengan 255 sehingga nilai nya:<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">R = 0,47<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">G = 0,78 <o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">B = 0,29<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Jadi dari hasil nilai tersebut yang disebut dengan normalisasi ke rentang 0-1, dan bukan termasuk grayscale.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Yang ditunjukkan di hal 36 dengan highlight warna hijau <o:p></o:p></span></pre></td>\n </tr>\n</tbody></table><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\nline-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Muhammad Adli Rizqulloh, S.Pd., M.T.<o:p></o:p></span></pre><table class=\"MsoTableGrid\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\" width=\"529\" style=\"width: 14cm; margin-left: -0.25pt; border: none;\">\n <tbody><tr>\n  <td width=\"34\" valign=\"top\" style=\"width: 25.5pt; border-width: 1pt; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-color: windowtext; border-image: initial; padding: 0cm 5.4pt;\"><pre style=\"text-align:center;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">No<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width: 137.55pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Komentar<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width: 233.85pt; border-top-width: 1pt; border-right: 1pt solid windowtext; border-bottom: 1pt solid windowtext; border-top-color: windowtext; border-image: initial; border-left: none; padding: 0cm 5.4pt;\"><pre style=\"text-align:\n  center;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;\n  font-family:&quot;Times New Roman&quot;,serif\">Respon<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">1.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam program yang kamu buat apa yang di maksud dengan boolean?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Boolean adalh tipe data logika dalam pemrograman yang hanya memiliki dua nilai yaitu <i>True </i>dan <i>False</i>.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">2.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Untuk di program yang training fungsi dari import torch, cv2, numpy itu apa?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Torch yaitu <i>framework</i> <i>deep learning </i>yang berfungsi untuk membangun dan melatih model <i>neural network</i>, menyimpan dan memuat bobot model, melakukan operasi tensor.<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Cv2 adalah <i>Opensource Computer Vision Library </i>yang berfungsi memproses gambar dan video, membaca atau menampilkan gambar, menggambar <i>bounding box, text, </i>dan filter<o:p></o:p></span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Numpy adalah library python untuk komputasi numerik yang berfungsi untuk operasi matematik pada array atau matrix, manipulasi data citra, vektor, dan hasil prediksi<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">3.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam proses training kamu menggunakan CUDA, fungsi dari CUDA itu buat apa? Kan sudah ada VGA yang digunakan <o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">CUDA berfungsi untuk mengakses GPU dalam proses komputasi, sehingga YOLOv5 bisa berjalan lebih cepat di GPU berkat CUDA terutama pada saat pelatihan, karena tanpa adanya library CUDA GPU tidak bisa melakukan proses komputasi pada saat pelatihan, <o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">4. <o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Library pathlib itu fungsi nya untuk apa?<o:p></o:p></span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Pathlib berfungsi untuk memanipulasi path (lokasi file/folder) secara objek-oriented, sehingga folder atau file yang dimasukan kedalam program akan terpanggil, apabila library tersebut tidak ada maka file atau folder tersebut tidak bisa bekerja.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">5. <o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\">\n  <p class=\"MsoNormal\" style=\"text-align:justify;line-height:normal\">Lalu\n  fungsi pathlib.WindowsPath = pathlib.PosixPath itu untuk apa?<o:p></o:p></p>\n  <pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></pre></td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Berfungsi untuk menjalankan file yang dibuat di windows pada sistem non windows (misalnya linux atau google colab), agar tidak terjadi error saat membuka path windows. Dengan override ini, semua path windows dianggap sama seperti path linux, sehingga proses training atau loading file tidak gagal.<o:p></o:p></span></pre></td>\n </tr>\n <tr>\n  <td width=\"34\" valign=\"top\" style=\"width:25.5pt;border:solid windowtext 1.0pt;\n  border-top:none;mso-border-top-alt:solid windowtext .5pt;mso-border-alt:solid windowtext .5pt;\n  padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">6.<o:p></o:p></span></pre></td>\n  <td width=\"183\" valign=\"top\" style=\"width:137.55pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\">\n  <p class=\"MsoNormal\" style=\"text-align:justify;line-height:normal\">Apakah\n  dalam program train.py nya menggunakan CUDA? apakah kamu buat sendiri untuk\n  program train.py nya?<o:p></o:p></p>\n  </td>\n  <td width=\"312\" valign=\"top\" style=\"width:233.85pt;border-top:none;border-left:\n  none;border-bottom:solid windowtext 1.0pt;border-right:solid windowtext 1.0pt;\n  mso-border-top-alt:solid windowtext .5pt;mso-border-left-alt:solid windowtext .5pt;\n  mso-border-alt:solid windowtext .5pt;padding:0cm 5.4pt 0cm 5.4pt\"><pre style=\"text-align:justify;line-height:150%\"><span style=\"font-size:12.0pt;\n  line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">Dalam file program train.py itu menggunakan CUDA, dengan mengimport torch.CUDA, untuk program saya tidak membuat secara manual tapi saya melakukan proses clonning YOLOv5 dari github yang ditunjukkan pada hal 66 bagian </span><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif;\n  mso-fareast-language:JA\">Install library dan mengclonning YOLOv5</span><span style=\"font-size:12.0pt;line-height:150%;font-family:&quot;Times New Roman&quot;,serif\">, sehingga otomatis semua komplemen dari YOLOv5 akan terdownload dibuat menjadi satu folder.<o:p></o:p></span></pre></td>\n </tr>\n</tbody></table><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"mso-bidi-font-size:12.0pt;line-height:150%;mso-bidi-font-family:&quot;Times New Roman&quot;\">&nbsp;</span></p>', '2025-07-10 21:43:31', '2025-07-19 21:31:21');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (304, 1, 620, 106, 2, 10, 1, 1, 1, '<p style=\"margin:0\">telah melaksanakan sidang terutup dengan lancar pada hari Rabu, 16 Juli 2025 pukul 08.00-09.00 di Ruang Perpustakaan FPTE<br>terdapat masukan masukan dari penguji terkait penulisan draft skripsi dan penelitian</p>', '2025-07-11 15:31:32', '2025-07-21 19:25:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (305, 1, 616, 106, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan sidang tertutup pada hari Rabu, 16 Juli 2025, dengan catatan masukan dari penguji:&nbsp;</p><p style=\"margin:0\">- Kaidah penulisan 2024 pada cover</p><p style=\"margin:0\">- Urutan Lampiran dan Daftar Pustaka mengacu kaidah penulisan 2024</p><p style=\"margin:0\">- Limitasi sistem pada hasil dan pembahasan</p><p style=\"margin:0\">- Pertimbangkan penyesuaian gestur tangan dengan standarisasi gestur/simbol tangan yang ada.</p><p style=\"margin:0\">- Penomoran dan rujukan Persamaan/Equation</p>', '2025-07-11 16:44:37', '2025-07-24 14:47:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (306, 1, 543, 109, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Muhammad Rifqi Nurul Hakim (2102786), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 16 Juli 2025 pukul 07.00-08.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Prof. Dr. Jaja Kustija, Msc Ibu Ir. Hj. Arjuni Budi Pancawati, M.T. dan Bapak Wasimudin Surya Putra, S.T, M.T.</p>', '2025-07-11 17:53:24', '2025-08-12 13:03:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (307, 1, 572, 109, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Muhamad Fajar Asianto (2103756), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 16 Juli 2025 pukul 08.00-09.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Prof. Dr. Jaja Kustija, M.Sc.; Bapak Wasimudin Surya Saputra, S.T., M.T.; dan Ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.</p>', '2025-07-11 17:53:24', '2025-08-06 12:55:47');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (308, 1, 599, 109, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Jundi Nashruddakwah (2107837), Teknik Elektro.</p><p style=\"margin:0\">Telah melaksanakan ujian sidang pre-defense pada hari Rabu, 16 Juli 2025 pukul 09.00-10.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Prof. Dr. Jaja Kustija, M.Sc. ; Bapak Wasimudin Surya Saputra, S.T., M.T. Dan Agus Heri Setya Budi, S.T., M.T.</p>', '2025-07-11 17:53:24', '2025-08-06 12:52:32');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (309, 1, 559, 109, 4, 2, 1, 1, 1, '<p style=\"text-align: justify; \">Sidang berjalan dengan lancar, dengan berbagai evaluasi, saran dan juga revisi yang diberikan oleh para dosen penguji. Sidang tertutup sudah dilaksanakan pada tanggal 16 Juli 2025 di jam 10.30, bertempat di ruangan laboratorium ELDAS. Kemudian, saya mengucapkan banyak terimakasih kepada dosen penguji yang sudah meluangkan waktu untuk menghadiri kegiatan pre-defense. Sekali lagi saya ucapkan banyak terimakasih.</p>', '2025-07-11 17:53:24', '2025-07-31 13:01:09');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (310, 1, 753, 104, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan pre-defense pada tanggal 22 Juli 2025 jam 07:00, dengan dosen penguji 1. Ibu Arjuni Budi Pantjawati dan 2. Ibu Budi Mulyanti.&nbsp;<br><br>Terdapat revisi pada:<br>1. perubahan kepala departemen menjadi ketua prodi pada kata pengantar<br>2. pemasukkan batasan masalah terkait pengambilan data<br>3. alur dan pemanggilan gambar 3.1<br>4. perubahan penampilan pada tabel 4.1 dan 4.2 agar lebih jelas<br>5. perampingan simpulan<br>6. update daftar pustaka terhadap perubahan-perubahan di atas</p>', '2025-07-14 09:22:40', '2025-07-24 11:02:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (311, 1, 651, 104, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabarakatuh&nbsp;</p><p style=\"margin:0\">Saya telah melaksanakan sidang pada tanggal 22 Juli 2025 untuk perbaikan dan masukan yaitu, abstrak, format halaman,&nbsp;<span style=\"color: inherit; font-size: 1rem;\">gambar 2.9, 2.10, 2.11</span><span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">gambar 3.7</span><span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">tabel 3.5 spesifikasi, tabel 4.2,</span></p><p style=\"margin:0\">Terima kasih</p><p style=\"margin:0\">Wassalamu\'alaikum warahmatullahi wabarakatuh</p>', '2025-07-14 09:40:14', '2025-07-22 22:24:29');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (312, 1, 661, 104, 2, 2, 1, 1, 1, '<div>Assalamualaikum Warahmatullahi Wabarakatuh&nbsp;</div><div>Saya telah melaksanakan sidang pada tanggal 22 Juli 2025 untuk perbaikan dan masukan yaitu, abstrak, format halaman, tabel 3.5 spesifikasi, tabel 4.2, gambar 3.7, gambar 2.9 2.10 2.11</div><div>Terima kasih</div><div>Wassalamu\'alaikum warahmatullahi wabarakatuh</div>', '2025-07-14 09:45:17', '2025-07-23 11:56:28');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (313, 1, 612, 104, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabarakatuh&nbsp;&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Saya telah melaksanakan sidang pada tanggal 22 Juli 2025 untuk perbaikan dan masukan yaitu: penyempurnaan judul, abstrak, penggunaan kata pengujian dan pengukuran, gambar tahanan kontak,&nbsp; memasukkan rumus rugi daya pada bab 2, penyempurnaan partisipan pada 3.2, Gambar 3.4, 4.1.1 sampai 4.1.3 menyesuaikan dengan rumusan masalah, warna grafik.</span></p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Terima kasih&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Wassalamu\'alaikum warahmatullahi wabarakatuh</span></p>', '2025-07-15 11:30:15', '2025-07-22 21:36:37');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (314, 1, 743, 104, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Hasil ujian sidang</p><p style=\"margin:0\">revisi dari bapak agus :<br>format laporan pada BAB I halaman 49<br>research gap pada halaman 18<br>sertakan definisi R&amp;D pada BAB III<br>sertakan definisi ahli<br>alur jika respons siswa negatif<br>seberapa penting respons siswa<br>bagian diseminasi pada BAB IV perlu dilengkapi</p><p style=\"margin:0\">revisi dari Bu Arjuni :<br>hapus \"departemen\" pada bagian ucapan terima kasih<br>tabel dan gambar harus dipanggil terlebih dahulu sebelum muncul<br>berikan hasil analisis penelitian sebelumnya</p>', '2025-07-15 12:56:43', '2025-08-21 11:59:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (315, 1, 742, 104, 5, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh<br>Saya telah melaksanakan sidang Pre-Defense pada tanggal 22 Juli 2025. Untuk perbaikan dan masukan yaitu, Redaksi kalimat pada judul, Perjelas gambar gambar yang berisikan kalimat&nbsp; agar dapat dibaca dengan mudah seperti gambar 2.3, 2.4, 2.5, Berikan penjelasan mengenai validitas keefektifan berupa perbandingan metode thermovisi dengan metode pengukuran suhu lainnya.&nbsp;<br>Terimakasih<br>Wassalamualaikum Warahmatullahi Wabarakatuh</p>', '2025-07-15 13:26:29', '2025-07-23 13:29:35');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (316, 1, 619, 107, 2, 10, 1, 1, 1, 'Berikut poin-poin yang perlu direvisi:<br>1. Memperbaiki penjelasan mengenai refrigeran jenis CFC pada latar belakang dengan jenis refrigeran pada 5 tahun terakhir, mengingat CFC telah dilarang penggunaannya.<br>2. Menambahkan penjelasan volume dan kuat menampung berat berapa untuk cooling box portabel tersebut<br>3. memperbaiki kesalahan penulisan dari segi ejaan.<br>4. Memperbaiki bagian dokumentasi visual dengan menempatkan penjelasan terlebih dahulu lalu gambar dokumentasinya.<br>5. Memperbaiki nama sumbu grafik pada fungsi keanggotaan fuzzy logic.', '2025-07-15 16:22:15', '2025-08-07 19:02:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (317, 1, 404, 110, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sudah dilaksanakan</p>', '2025-07-22 12:34:57', '2025-08-07 21:09:36');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (318, 1, 720, 114, 2, 2, 1, 1, 1, '<div>Assalamu\'alaikum Warahmatullahi Wabarakatuh.</div><div><br></div><div>Saya telah melaksanakan sidang Pre-Defense pada tanggal 07 Agustus 2025.</div><div><br></div><div>Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</div><div><br></div><div>1. Bab 2 Kajian Pustaka</div><div>a) Capacitive Voltage Transformer (CVT):</div><div>-Menambahkan tabel batas kesalahan tegangan dan penyimpangan fasa untuk CVT (Pengukuran dan Proteksi).</div><div>b) Current Transformer (CT):</div><div>-Lengkapi fungsi dan jenis CT.</div><div>-Menambahkan kelas ketelitian CT (Proteksi dan Metering).</div><div>-Menambahkan perhitungan rasio CT ideal.</div><div><br></div><div>2. Bab 4 Temuan dan Pembahasan</div><div>-Tabel pada temuan Sub-bab 4.1.2, yaitu tabel 4.3 dan tabel 4.4. Status kelayakan hasil uji tangen delta, fokus pada parameter dari masing-masing transformator.&nbsp;</div><div><br></div><div>Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</div><div><br></div><div>Demikian laporan hasil sidang skripsi ini saya sampaikan.</div><div><br></div><div>Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</div>', '2025-07-22 14:12:37', '2025-08-09 00:07:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (319, 1, 546, 110, 4, 3, 1, 1, 1, '<p style=\"margin:0\">ahmad ali yasin (2107301), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 30 Juli 2025 pukul 10.00-11.00 WIB di Laboratorium elektro telekomunikasi dengan dosen penguji Bapak Didin Wahyudin, M.T., Ph.D. ibu Ir. Hj. Arjuni Budi Pantjawati, M.T..; dan Bapak Agus Heri Setya Budi, M.T.</p>', '2025-07-22 14:29:58', '2025-08-08 16:43:54');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (320, 1, 646, 110, 1, 9, 1, 1, 1, '<p class=\"MsoNormal\" style=\"text-align:justify\"><b>Assalamualaikum Warahmatullahi Wabarakatuh.</b><o:p></o:p></p><p class=\"MsoNormal\" style=\"text-align:justify\">Alhamdulillah, proses sidang skripsi pre-defense (sidang tertutup) telah\nterlaksana dengan lancar pada hari Rabu, 30 Juli 2025 pukul 07.00 WIB dan\nselesai pada pukul 07.50 WIB. Sidang dilaksanakan tepat waktu dan menghasilkan\nbeberapa masukan penting dari para penguji, di antaranya:<o:p></o:p></p><ol style=\"margin-top:0cm\" start=\"1\" type=\"1\">\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Penulis\n     diharapkan dapat memperdalam pemahaman terkait konsep dasar PLTS,\n     khususnya mengenai prinsip konversi energi berdasarkan efek fotovoltaik.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Kajian\n     pustaka terkait ikan koi perlu diperluas dan dipaparkan secara lebih\n     komprehensif, mengingat hal tersebut menjadi dasar penting penerapan PLTS\n     dalam mendukung kebutuhan energi pada budidaya ikan koi.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Hasil\n     penelitian perlu lebih menggambarkan keterkaitan antara judul, rumusan\n     masalah, dan hasil penelitian secara kuantitatif.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Perlu\n     dilakukan evaluasi terhadap perbedaan kondisi antara musim kemarau dan\n     musim hujan dalam mengevaluasi pengaruh beberapa variabel lingkungan terhadap potensi penerapan PLTS.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Rata-rata\n     output energi harian dari panel surya perlu dipaparkan secara sistematis.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Standar\n     evaluasi yang digunakan dalam penelitian sebaiknya dijelaskan secara\n     eksplisit di Bab II (Kajian Pustaka), tidak hanya disebutkan dalam latar\n     belakang.<o:p></o:p></li>\n <li class=\"MsoNormal\" style=\"text-align:justify;mso-list:l0 level1 lfo1;\n     tab-stops:list 36.0pt\">Spesifikasi\n     teknis sistem yang digunakan dalam evaluasi potensi PLTS perlu dijelaskan berdasarkan data, agar pembaca memahami alasan\n     pemilihan parameter tersebut.<o:p></o:p></li>\n</ol><p class=\"MsoNormal\" style=\"text-align:justify\">Demikian laporan hasil sidang yang dapat saya sampaikan. Terima kasih\natas perhatian dan kesempatan yang telah diberikan.<o:p></o:p></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><b>Wassalamualaikum Warahmatullahi Wabarakatuh.</b><o:p></o:p></p>', '2025-07-24 12:10:08', '2025-08-03 23:01:41');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (321, 1, 589, 110, 2, 9, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh<br>Alhamdulillah proses Pre-Defense (Sidang Tertutup) telah terlaksana dengan lancar pada hari Rabu, 30 Juli 2025 pukul 08.00 WIB dan selesai pukul 09.00 WIB. Sidang dilaksanakan tepat waktu dan menghasilkan masukkan penting dari para penguji diantaranya:<br>1. Penulis diharapkan dapat lebih memperdalam pemahaman terkait konsep sistem kontrol pada turbin angin<br>2. Hasil penelitian perlu lebih diselaraskan, terutama pada perbandingan saat melakukan pengujian<br>3. Perlu dilakukan penambahan terkait penelitian sebelumnya yang sesuai<br>Demikian laporan hasil Pre-Defense yang dapat saya sampaikan. Terima kasih atas perhatian dan kesempatan yang telah diberikan.<br>Wassalamu\'alaikum Warahmatullahi Wabarakatuh</p>', '2025-07-24 12:18:35', '2025-08-08 10:51:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (322, 1, 535, 110, 3, 9, 1, 1, 1, '<p style=\"margin:0\"></p><h3>LAPORAN SEMINAR PRA-SKRIPSI (PREDEFENSE)</h3><p style=\"margin:0\"><strong>Nama</strong>       : Muhammad Haqil Aufar<br>\n<strong>NIM</strong>        : 2102249<br>\n<strong>Judul</strong>       : <em>Perancangan dan Implementasi Sistem Irigasi Otomatis Berbasis Internet of Things untuk Pengawasan dan Pengendalian Pertanian</em><br>\n<strong>Dosen Pembimbing</strong> : Dr. Aip Saripudin, S.Si., M.T.<br>\n<strong>Dosen Penguji</strong>   : Dr. Agus Heri Setya Budi, S.T., M.T.<br>\n       &nbsp; &nbsp;  Dr. Didin Wahyudin, M.Ed.<br>\n        &nbsp; &nbsp; Dr. Siscka Elvyanti, M.T.</p><p style=\"margin:0\"><strong>Tanggal Pelaksanaan</strong>: 30 Juli 2025</p><h3>Ringkasan Seminar</h3><p style=\"margin:0\">Seminar pra-skripsi dilaksanakan dengan mempresentasikan rancangan sistem irigasi otomatis berbasis <em>Internet of Things (IoT)</em> yang memanfaatkan berbagai sensor lingkungan seperti suhu, kelembapan tanah dan udara, intensitas cahaya, curah hujan, serta pH tanah. Sistem ini dikendalikan oleh ESP32 dan mengimplementasikan logika fuzzy sebagai pengambil keputusan utama terhadap aktuator berupa <em>solenoid valve</em> dan relay pompa. Data hasil pembacaan sensor ditampilkan melalui Arduino IoT Cloud dan Telegram bot untuk kebutuhan pemantauan jarak jauh.</p><h3>Catatan dan Tanggapan Dosen Penguji</h3><ol>\n<li>\n<p style=\"margin:0\"><strong>Pemahaman terhadap logika fuzzy</strong><br>\nPenguji meminta klarifikasi terhadap jumlah <em>rule</em> dalam fuzzy logic dan kombinasi input-outputnya. Ditekankan pentingnya pemahaman konsep dasar fuzzy, probabilitas kombinasi input, dan implementasinya agar tidak sekadar menggunakan library.</p>\n</li>\n<li>\n<p style=\"margin:0\"><strong>Segmentasi pengguna</strong><br>\nKritik utama dari penguji adalah belum jelasnya segmentasi pengguna. Sistem saat ini lebih cocok untuk kalangan yang memahami pemrograman (programmer/teknisi). Untuk penggunaan oleh petani umum, dibutuhkan sistem yang lebih <em>user-friendly</em> tanpa perlu login atau konfigurasi manual.</p>\n</li>\n<li>\n<p style=\"margin:0\"><strong>Pilihan platform cloud</strong><br>\nArduino IoT Cloud dinilai tidak praktis bagi sebagian besar petani karena keterbatasan gratisan dan kebutuhan login. Saran diberikan agar pengembangan selanjutnya mempertimbangkan platform yang lebih mudah digunakan atau membuat aplikasi khusus.</p>\n</li>\n<li>\n<p style=\"margin:0\"><strong>Visualisasi dan akurasi data</strong><br>\nPenguji mempertanyakan kemampuan menampilkan grafik dan visualisasi pada sistem, serta akurasi pembacaan sensor terkait konversi analog ke digital (ADC). Dijelaskan pentingnya pemilihan bit ADC (4-bit, 8-bit, dll.) dalam menentukan ketelitian pembacaan sensor.</p>\n</li>\n<li>\n<p style=\"margin:0\"><strong>Penggunaan logika fuzzy</strong><br>\nLogika fuzzy dianggap tepat jika digunakan untuk mengatasi ambiguitas dan kompleksitas data dari berbagai sensor secara bersamaan. Ditekankan pentingnya menguasai alasan teknis mengapa fuzzy digunakan dibanding logika digital biasa.</p>\n</li>\n<li>\n<p style=\"margin:0\"><strong>Implementasi di lapangan</strong><br>\nSistem telah diuji coba secara terbatas di rumah mahasiswa. Diharapkan pengujian ke depannya dilakukan secara lebih luas di lingkungan petani nyata.</p>\n</li>\n</ol><h3>Saran dan Rekomendasi Penguji</h3><ul>\n<li>\n<p style=\"margin:0\">Segera definisikan dengan jelas target pengguna: apakah sistem ini untuk hobi pribadi, petani rumahan, atau komersial.</p>\n</li>\n<li>\n<p style=\"margin:0\">Buat sistem yang lebih mudah digunakan oleh petani non-teknis, misalnya sistem <em>ready-to-use</em> tanpa proses konfigurasi teknis.</p>\n</li>\n<li>\n<p style=\"margin:0\">Pelajari kembali dasar konversi ADC, bit resolusi, serta peran masing-masing komponen dalam pembacaan sensor dan pengambilan keputusan fuzzy.</p>\n</li>\n<li>\n<p style=\"margin:0\">Lakukan visualisasi sistem fuzzy di MATLAB agar pemahaman terhadap sistem menjadi lebih jelas dan sistem dapat dikembangkan secara ilmiah.</p>\n</li>\n</ul><h3>Penutup</h3><p style=\"margin:0\">Saya, Muhammad Haqil Aufar, mengucapkan terima kasih atas kritik, saran, dan masukan dari para dosen penguji dan dosen pembimbing. Segala catatan dan evaluasi yang telah diberikan akan saya jadikan dasar perbaikan untuk penyusunan skripsi dan pengembangan sistem lebih lanjut.</p><p style=\"margin:0\">Wassalamualaikum warahmatullahi wabarakatuh.</p>', '2025-07-24 12:33:25', '2025-07-31 13:11:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (323, 1, 592, 110, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Faza Fadilah Almadani (2106600), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 30 Juli 2025 pukul 07.00-08.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.; Bapak Dr. Elih Mulyana, M.Si.; dan Bapak Wawan Purnama, S.Pd., M.Si.</p>', '2025-07-24 15:12:24', '2025-08-06 12:45:59');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (324, 1, 674, 110, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Raka Naufal Pasya (2107931), Teknik Elektro.</p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 30 Juli 2025 pukul 08.00-09.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Dr. Ir.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Maman Somantri, S.Pd., M.T.; Bapak Dr. Elih Mulyana, M.Si.; dan Bapak Wawan Purnama, S.Pd., M.Si.</span></p>', '2025-07-24 15:12:53', '2025-08-06 09:19:29');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (325, 1, 569, 110, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Aditya Hanggara Pratama (2102571), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 30 Juli 2025 pukul 09.00-10.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Dr. Elih Mulyana, M.Si.; Bapak Wawan Purnama, S.Pd., M.Si.; dan Bapak Dr. Ir. Dadang Lukman Hakim, M.T.</p>', '2025-07-25 11:36:01', '2025-08-14 08:07:32');
