INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (328, 1, 699, 114, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum saya telah menyelesaikan sidang terima kasih</p><p style=\"margin:0\">untuk yang direvisi:</p><p style=\"margin:0\">diksi judul</p><p style=\"margin:0\">abstrak</p><p style=\"margin:0\">sumber gambar</p>', '2025-07-28 12:56:21', '2025-08-08 19:37:10');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (329, 1, 643, 115, 1, 3, 1, 1, 1, '<p data-start=\"175\" data-end=\"206\"><span data-start=\"175\" data-end=\"204\">Laporan <br></span><span style=\"color: inherit; font-size: 1rem;\">Hasil </span><em data-start=\"214\" data-end=\"227\" style=\"color: inherit; font-size: 1rem;\">pre-defense</em><span style=\"color: inherit; font-size: 1rem;\"> yang dilaksanakan pada 12-08-2025 pada jam 07.00 menghasilkan beberapa revisi minor sebagai berikut:</span></p><ol data-start=\"316\" data-end=\"743\">\n<li data-start=\"316\" data-end=\"418\">\n<p data-start=\"319\" data-end=\"418\"><span data-start=\"319\" data-end=\"351\">Perbaikan penulisan (<em data-start=\"342\" data-end=\"348\">typo</em>)</span> pada beberapa bagian&nbsp; agar sesuai kaidah penulisan ilmiah.</p>\n</li>\n<li data-start=\"419\" data-end=\"538\">\n<p data-start=\"422\" data-end=\"538\"><span data-start=\"422\" data-end=\"470\">Penyesuaian penulisan istilah bahasa Inggris</span> menjadi <em data-start=\"479\" data-end=\"487\">italic</em> sesuai standar penulisan skripsi.</p>\n</li>\n<li data-start=\"539\" data-end=\"743\">\n<p data-start=\"542\" data-end=\"743\"><span data-start=\"542\" data-end=\"610\">Penekanan pengaruh atau faktor yang memengaruhi kinerja metalens</span> pada bagian simpulan dan abstrak, agar pembaca dapat langsung memahami keterkaitan hasil penelitian dengan faktor-faktor tersebut.</p></li></ol>', '2025-07-28 14:01:15', '2025-08-15 13:21:06');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (330, 1, 446, 111, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan predefense pada hari Rabu, 13 Agustus 2025 jam 10.00-11.00 WIB</p>', '2025-07-31 21:43:47', '2025-08-16 06:43:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (331, 1, 738, 114, 3, 2, 1, 1, 1, '<p style=\"margin:0\">saya telah melakukan perbaikan atas saran saran dari semua penguji diantaranya mengenai struktur penulisan perubahan format dari 2024 ke format 2021, lalu penambahan struktur abstrak yang kurang serta penambahan faktor perubahan sudut terhadap sinkronisasi antar fasa.</p>', '2025-08-01 13:17:45', '2025-08-15 12:13:46');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (332, 1, 647, 121, 1, 3, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 15 Agustus 2025.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">bab 2 kajian Pustaka</p><p style=\"margin:0\">tambahkan deskripsi di setiap pembahasan</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">bab 3&nbsp;</p><p style=\"margin:0\">tambahkan pengembangan system</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">bab 4</p><p style=\"margin:0\">tambahkan data berupa grafik</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">bab 5&nbsp;</p><p style=\"margin:0\">tambahkan saran berupa kendala dalam merancang sistem</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</p>', '2025-08-01 14:39:34', '2025-08-20 15:33:57');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (333, 1, 669, 115, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Berdasarkan sidang pre-defense yang telah dilaksanakan pada Selasa, 12 Agustus 2025, ditetapkan beberapa poin revisi yang wajib diselesaikan oleh mahasiswa. Rincian revisi tersebut adalah sebagai berikut:</p><p style=\"margin:0\">1. Revisi gambar: Semua gambar diletakan setelah paragraf yang mereferensikannya, sesuai pedoman. Menambahkan label yang jelas pada setiap komponen (sensor/aktuator) di gambar ilustrasi sistem. Ukuran dan resolusi gambar juga harus diperbesar agar detail tetap terbaca.<br>2. Diagram alur: Memperbaiki dan menyempurnakan diagram alur sistem agar alur logika dapat dipahami dengan lebih mudah dan intuitif oleh pembaca.<br>3. Penulisan Rumus: Memberikan penomoran pada setiap rumus yang digunakan. Selain itu, wajib menyertakan penjelasan mendetail untuk setiap variabel yang ada di dalam rumus tersebut.<br>4.Ruang lingkup pengujian: Merevisi bagian pengujian keandalan sensor PIR. Sesuai fokus judul, pengujian sensor PIR dinilai tidak relevan dengan evaluasi kinerja algoritma kontrol irigasi.<br>5. Judul: Mengubah judul skripsi menjadi \"Evaluasi Kinerja Algoritma Kontrol Pada Sistem Irigasi Cerdas\". Perubahan ini dilakukan untuk lebih akurat mencerminkan fokus penelitian yang berpusat pada evaluasi kinerja, bukan optimasi, serta pengujian yang lakukan pada lingkup prototipe.</p><p style=\"margin:0\"><br><br></p>', '2025-08-04 09:07:58', '2025-08-15 16:25:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (334, 1, 702, 115, 3, 3, 1, 1, 1, '<p style=\"margin:0\">terdapat beberapa catatan revisi<br>1. tujuan penelitian tidak secara langsung disebutkan sebagai media edukatif<br>2. hasil akhir penelitian sensor nya itu adalah tingkat error dari sensor<br>3. diskusikan lagi tentang objek tanamannya<br>4. flowchart sistem perlu diperbaiki karena isinya kurang tepat<br>5. ubah menjadi sistem irigasi otomatis</p>', '2025-08-04 09:12:40', '2025-08-14 15:53:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (335, 1, 686, 111, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Ananda Raihan Fajar (2104072), Teknik Elektro.</p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari rabu, 13 Agustus 2025 pukul 08.00-09.00 WIB di Laboratorium Elektronika Dasar dengan penguji Bapak Dr. Ir. H. Dadang Lukman Hakim, M.T., Bapak Wawan Purnama, S. Pd., Dr. Yadi Mulyadi, M.T.</p>', '2025-08-04 12:17:34', '2025-08-19 10:30:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (336, 1, 608, 111, 1, 2, 1, 1, 1, '<p style=\"margin:0\">Muhamad Sultan Nazhir (2109261), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 13 Agustus 2025 pukul 07.00-08.00 WIB di Laboratorium Elektronika Dasar dengan dosen penguji Bapak Prof. Dr. Jaja Kustija, M.Sc., dan Bapak Wawan Purnama, S.Pd., M.Si.</p>', '2025-08-04 13:07:16', '2025-08-13 10:02:55');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (337, 1, 604, 111, 1, 3, 1, 1, 1, '<p style=\"margin:0\">Raihan Satria Gamas (2100091), Teknik Elektro.<br><br>Telah melaksanakan ujian sidang pre-defense pada hari Rabu, 13 Agustus 2025 pukul 07.00-08.00 di Laboratorium Telekomunikasi dengan dosen penguji Prof. Dr. Hj. Budi Mulyanti M.Si; Bapak Iwan Kustiawan S.Pd., M.T., Ph.D.; Bapak Didin Wahyudin M.T., Ph.D.</p>', '2025-08-05 10:23:38', '2025-08-15 12:53:09');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (338, 1, 644, 111, 1, 9, 1, 1, 1, '<p class=\"MsoNormal\"><span lang=\"EN-US\">1. Latar belakang terlalu panjang<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">2. di akhir meyakinkan pembaca, bukan\nmenyimpulkan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">3. rumusan masalah dll tidak tercemrinkan\ndi judul<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">4. kurang gambar terutama bab 2<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">5. rumus harus menunjukkan sumber dari\nstandar industri<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">6. setiap gambar dipanggil<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">7. metode penelitian kurang gambar seperti\nflowchart dan diagram blok<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">8. abstrak kurang latar belakang kebanyakan\nteori (latar b, tujuan, taori, oenelitian, hasil)<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">9.&nbsp;\ngambar hitam background <o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">10. dijelaskan isi gambarnya<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">11. metode penelitian jangan perintah<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">12. selisih diberikan satuan, dll<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">13. halaman 51, efek ini (tidak bisa\ndiomongin) karena tidak dilakukan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">14. kesimpulan dan rumusan masalh jumlahnya\nsama<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">15. halaman pertama, penyusun skripsi<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">16. baku bahasa<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">17. satuan disamakan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">18.&nbsp;\nspasi dirapihkan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">19. rata kiri kanan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">20. kecepatan yang digunakn <o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">21. lokal dan tidak lokal, harusnya sama\nlokal<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">22. rumusah dan tujuan sama<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">23. et al menjadi dkk<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">24. variabel dibetulkan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">25. program cuplikan saja namun dijelaskan\nsisanya dilampiran<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"EN-US\">26. font disamaakn<o:p></o:p></span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\"><span lang=\"EN-US\">27. dashboard dirapihkan lagi<o:p></o:p></span></p>', '2025-08-06 12:43:48', '2025-08-19 13:17:37');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (339, 1, 653, 111, 2, 9, 1, 1, 1, '<p style=\"margin:0\">Laporan Sidang Pre-defense Rabu 13 Agustus 2025&nbsp;<br>1. Perbaikan logo pada cover&nbsp;<br>2. Perbaikan Abstrak<br>3. Perbaikan kutipan sumber referensi<br>4. Perbaikan tabel dan gambar menjadi lebih jelas<br>5. Perbaikan pemanggilan gambar<br>6. Perbaikan tanda baca titik dan koma<br>7. Tambahkan hasil simulasi berulang kali<br>8. Tambahkan analisis hasil simulasi latensi dan throughput</p>', '2025-08-06 12:44:46', '2025-08-14 16:15:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (340, 1, 665, 111, 2, 3, 1, 1, 1, '<p style=\"margin:0\">1. Abstrak tidak boleh ada singkatan.</p><p style=\"margin:0\">2. Tujuan penelitian harus diperjelas.</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">3.Gambar ilustrasi gunakan foto prototipe sendiri.</span></p><p style=\"margin:0\">4. Apakah simulasi representatif dengan subjek yang di teliti?</p><p style=\"margin:0\">5. Bandingka waktu respons dengan penelitian terdahulu</p>', '2025-08-06 12:57:10', '2025-08-17 19:32:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (341, 1, 444, 111, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Telah selesai dilaksanakannya sidang pre-defense pada 13 Agustus 2025 pukul 10.23 hingga pukul 11.23.</p>', '2025-08-06 13:01:25', '2025-08-13 19:10:54');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (342, 1, 655, 111, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 13 Agustus 2025 pukul 09.00-10.00, dihadiri oleh dosen penguji:</p><p style=\"margin:0\">1. Bapak Iwan Kustiawan,S.Pd.,M.T.,ph.D</p><p style=\"margin:0\">2. Ibu Ir.Hj.Arjuni Budi Pantjawati,M.T</p><p style=\"margin:0\">2. Bapak Didin Wahyudin,M.T.,ph.D</p><p style=\"margin:0\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:</p><p style=\"margin:0\">1. Penyesuaian judul menjadi ( pembuatan prototype solar tracking 2 axis dilengkapi dengan sistem monitoring secara realtime untuk memaksimalkan efisiensi energi )</p><p style=\"margin:0\">2. Penulisan di sesuaikan lagi dengan pedoman</p><p style=\"margin:0\">3. Perbaiki daftar pustaka agar sesuai</p>', '2025-08-06 13:08:26', '2025-08-17 09:00:26');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (343, 1, 677, 121, 1, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 07 Agustus 2025.</p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</p><ol><li>Ubah Logo</li><li>perbaikan spasi&nbsp;</li><li>pemberian space pada Judul Tabel dan deskripsi</li><li> Bab 3 Metode Penelitian: perbaikan flowchat</li><li>Bab 4 Hasil dan pembahasan: bab 4 tidak di jelaskan terkait pengembangannya disarankan; Perbaikan Rumusan Masalah</li></ol><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</span></p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</span></p><p style=\"margin:0\"><br></p>', '2025-08-06 19:41:11', '2025-08-15 16:58:12');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (344, 1, 681, 117, 2, 10, 1, 1, 1, '<p style=\"margin:0\"><a href=\"https://drive.google.com/drive/folders/1-1LywSL98EV4zxsbGOjNaPqH-Bb2sk9P\" target=\"_blank\">Sistem Monitoring Angin Secara Real-Time pada Mesin Kompresor Udara Berbasis Internet of Things (IoT)</a><br></p>', '2025-08-07 10:13:34', '2025-08-20 16:37:35');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (345, 1, 672, 122, 4, 9, 1, 1, 1, '<p style=\"margin:0\">PENGEMBANGAN FETNET: APLIKASI WEB ANTARMUKA UNTUK OPTIMISASI PENJADWALAN PERKULIAHAN MENGGUNAKAN ALGORITMA FET (FREE EVOLUTIONARY TIMETABLING)</p>', '2025-08-07 10:18:38', '2025-08-18 20:44:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (346, 1, 682, 117, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 13 Agustus 2025. Untuk perbaikan dan masukan yaitu :</p><p style=\"margin:0\">1. Penghapusan beberapa point dan revisi pada bagian KATA PENGANTAR</p><p style=\"margin:0\">2. Penambahan kata pada bagian ABSTRAK menjadi sebanyak 200 kata yang tadinya 160 kata</p><p style=\"margin:0\">3. Penambahan Novelty pada bagian LATAR BELAKANG</p><p style=\"margin:0\">4. Revisi dalam penyebutan Gambar</p><p style=\"margin:0\">5. Revisi penulisan pada bagian DAFTAR PUSTAKA</p><p style=\"margin:0\">6. Penambahan analisis pada bagian BAB IV</p><p style=\"margin:0\">7 Revisi penulisan pada bagian SARAN di BAB V</p>', '2025-08-07 20:20:14', '2025-08-19 02:46:03');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (347, 1, 629, 117, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 13 Agustus 2025. Untuk perbaikan dan masukan yaitu, Kesalahan ketik pada lembar pengesahan, Perjelas gambar gambar yang berisikan kalimat agar dapat dibaca dengan mudah seperti gambar 2.3, 2.4, 2.5, Sitasi dari gambar”yang saya ambil dari sumber internet dan melakukan pemanggilan pada penjelasan gambar, memperbaiki redaksi yang terdapat pada rumusan masalah dan tujuan penelitian, proses tahapan-tahapan penelitian yang harus di perbaiki, sub judul instrumen penelitian harus diperbaiki.</p>', '2025-08-07 22:10:07', '2025-08-16 15:19:25');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (348, 1, 622, 118, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 14 Agustus 2025. Untuk perbaikan dan masukan yaitu sebagai berikut :</p><p style=\"margin:0\">1. Menambahkan perbandingan setelah alat diimplementasikan pada peternakan</p><p style=\"margin:0\">2. Perbaikan Daftar Pustaka sesuai alfabet</p><p style=\"margin:0\">3. Perbaikan penlisan (penggunaan kalimat utama dan anak kalimat untuk setiap paragraf)</p><p style=\"margin:0\">4. Menambahkan datasheet sensor pada lampiran</p>', '2025-08-08 05:33:46', '2025-08-15 23:29:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (349, 1, 683, 118, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 14 Agustus 2025. Untuk perbaikan dan masukan yaitu sebagai berikut :</p><div>1. Abstrak ( memasukan general dan problem statement.</div><div>2. Data pada Densitas di penelitian (gram ke Kilogram/m3)</div><div>3. menambahkan penelitian terdahulu pada BAB 2</div><div>4. mengurutkan abjad pada daftar pustaka</div>', '2025-08-08 05:33:55', '2025-08-15 23:30:12');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (350, 1, 760, 115, 1, 9, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 12 Agustus 2025. Alhamdulilah skripsi saya dipuji baik oleh para penguji dan hanya ada perbaikan minor saja. Untuk perbaikan dan masukan yaitu sebagai berikut :</p><p style=\"margin:0\">1. Memasukkan sitasi sumber pada gambar</p><p style=\"margin:0\">2. Perbaikkan beberapa kata yang kurang tepat</p><p style=\"margin:0\">3. &nbsp;menyatukan grafik perbandingan potensi daya dan produksi daya</p>', '2025-08-08 05:34:01', '2025-08-15 14:31:24');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (351, 1, 73, 122, 1, 3, 1, 1, 1, 'Sidang sudah selesai dilaksanakan, skripsi perlu proses perbaikan', '2025-08-08 09:44:27', '2025-08-16 11:04:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (352, 1, 536, 111, 5, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang tertutup dilaksanakan pada tanggal 13 Agustus 2025 pukul 11.00-12.00, dihadiri oleh dosen penguji:<br>1.&nbsp;Bapak Prof. Dr. Enjang A. Juanda, M.Pd., M.T.<br>2.&nbsp;Bapak Dr. Erik Hariman, S.Pd., M.T.<br>3.&nbsp;Bapak Nurul Fahmi Arief Hakim, S.Pd., M.T<br><br>Beberapa masukan setelah sidang dilaksanakan, diantaranya:<br>1.&nbsp;Tinjau lebih lanjut mengenai latar belakang penelitian yang dilakukan dengan menambahkan alasan yang lebih kuat kembali.<br>2.&nbsp;Tambahkan penjelasan untuk tiap pemrograman koding yang dilakukan secara rinci untuk menambah pada bab 4.<br>3. Perbaikan gambar agar lebih jelas, ukurannya di perbesar untuk memudahkan melihat dan penambahan flowchart tiap program yang dibuat.</p>', '2025-08-08 09:55:44', '2025-08-14 18:57:34');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (353, 1, 636, 117, 5, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 13 Agustuas 2025. Untuk perbaikan dan masukan yaitu, Redaksi kalimat pada judul,&nbsp;</p>', '2025-08-08 11:15:53', '2025-08-15 14:11:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (354, 1, 594, 121, 2, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 15 Agustus 2025.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</p><p style=\"margin:0\">1. Bab 4 Temuan dan Pembahasan</p><p style=\"margin:0\">-Tabel pada temuan Sub-bab 4.1.2, yaitu tabel 4.3 tidak relevan dengan penelitian karena tidak ada implementasi solar tracking di gedung D dan juga Gambar 4.6 tidak relevan dengan penelitian.&nbsp;</p><p style=\"margin:0\">2. Di Bab Akhir Lampiran melampirkan data radiasi matahari dalam waktu 14-20 april 2025</p><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</p>', '2025-08-08 13:35:03', '2025-08-15 11:33:48');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (355, 1, 693, 121, 2, 3, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum saya sudah melaksanakan sidang tertutup, terimakasih</p>', '2025-08-08 15:43:28', '2025-08-15 14:28:10');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (356, 1, 714, 121, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 15 Agustus 2025.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan, antara lain:</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">1. Isi skripsi</p><p style=\"margin:0\">a. Memisahkan grafik menjadi masing-masing parameter kelistrikan setiap beban</p><p style=\"margin:0\">b. Menambahkan sumber pada gambar&nbsp;</p><p style=\"margin:0\">2. Diminta membuat video membuat program di Arduino Uno mengenai lampu on off</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</p>', '2025-08-08 17:56:22', '2025-08-15 11:40:51');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (357, 1, 262, 111, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan Pre-defense pada tanggal 13 Agustus 2025 jam 08.00 sampai dengan 09.00&nbsp;</p>', '2025-08-09 07:32:53', '2025-08-14 10:34:11');
