INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (359, 1, 519, 118, 3, 2, 1, 1, 1, '<p style=\"margin:0\"><a href=\"https://drive.google.com/drive/folders/1Csvgw5yi0aYPYc4cliHMkgHqIxzmCOok\" target=\"_blank\">https://drive.google.com/drive/folders/1Csvgw5yi0aYPYc4cliHMkgHqIxzmCOok</a></p><p style=\"margin:0\">Revisi :&nbsp; </p><p style=\"margin:0\">Pak Resa Pramudita : - penjelasan VSCode dipindahkan dari bab 4 ke bab 1. - penambahan teori pada bab 2 tentang VSCode.</p><p style=\"margin:0\">Pak Dadang lukman Hakim : - Penulisan pada bab 4 dan bab 5, bagian angka dan kalimat pada data hasil pengujian, dan kesimpulan pada bab 5.</p><p style=\"margin:0\">Pak Erik Haritman : - kerapihan pada keseluruhan penulisan, pada penulisan rumus.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\"><br></p><p style=\"margin:0\">&nbsp;</p>', '2025-08-09 12:36:09', '2025-08-22 12:11:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (360, 1, 639, 118, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum warahmatullahi wabarokatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 14 Agustus 2025, Untuk perbaikan dan masukan dari dosen penguji yaitu, Bab 4 dan bab 5 dibetulkan headingnya , Rumusan masalah dan harus ada di bab 4 hasil dan pembahasannya, penulisan skripsi secara keseluruhan disesuaikan dengan pedoman nya 2021</p>', '2025-08-09 13:18:01', '2025-08-16 18:59:14');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (361, 1, 680, 118, 3, 10, 1, 1, 1, '<p style=\"margin:0\">sidang tertutup sudah di laksanakan di hari kamis, 14 Agustus 2025. Terima kasih kepada dosen pembimbing, dan para dosen penguji yang telah menghadiri sidang pada hari tersebut.&nbsp;</p>', '2025-08-09 14:58:57', '2025-08-20 19:54:09');
