INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (363, 1, 725, 121, 4, 2, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 07 Agustus 2025.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">diksi yang digunakan pada judul skripsi</p><p style=\"margin:0\">Lalu penambahan korelasi pada bab 4</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</p>', '2025-08-09 19:53:57', '2025-08-20 06:45:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (364, 1, 691, 111, 4, 9, 1, 1, 1, '<p style=\"margin:0\">Bagaskara Anandayutya (2103229), Teknik Elektro.</p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Rabu, 13 Agustus 2025 pukul 10.00-11.00 WIB di Ruangan Kepala Laboratorium Telekomunikasi dengan dosen penguji Bapak Dr. Aip Saripudin M.T.; dan Ibu Dr. Siscka Elvyanti.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Prof. Dr. Enjang A. Juanda M.Pd., M.T. tidak dapat hadir untuk menguji sidang karena berhalangan.&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">Sidang pre defense turut disertai oleh 2 dosen pembimbing yaitu Ibu Ir. Hj. Arjuni Budi Pantjawati M.T.; dan Bapak Nurul Fahmi Arief Hakim S.Pd., M.T.,</span></p>', '2025-08-09 20:48:13', '2025-08-14 19:52:33');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (365, 1, 675, 111, 3, 2, 1, 1, 1, '<p style=\"margin:0\">Alamsyah Muhammad Saputra (2106142), Teknik Elektro. Telah dilaksanakan Pre Defense pada tanggal 13 Agustus 2025 jam 09.00-10.00 di ruangan laboratorium Eleltronika Dasar, dengan penguji Dr. Elih Mulyana, M.Si.; Dr. H. Bambang Trisno, M.SIE.; dan Dr. Tasma Sucita, M.T.&nbsp;</p>', '2025-08-10 07:19:16', '2025-08-19 16:06:45');
