INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (367, 1, 650, 121, 4, 1, 1, 1, 1, 'Pelajari lagi cara efesiensi itu bekerja seperti apa, tambahkan mekanisme diagram cara kerja MPPT Pertub &amp; Observe, Masukan hasil rumusan Masalah yang dipecahkan kedalam kesimpulan. Bandingkan MPPT dan PWM dengan kapasitas yang lebih kecil/sederhana&nbsp;', '2025-08-10 10:21:21', '2025-08-15 11:36:12');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (368, 1, 736, 121, 1, 2, 1, 1, 1, '<p dir=\"ltr\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p dir=\"ltr\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 15 Agustus 2025.</p><p dir=\"ltr\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</p><p dir=\"ltr\">1. Bab 2 Kajian Pustaka</p><p dir=\"ltr\"><br>\n</p><p dir=\"ltr\"><span style=\"font-size:0px\" ;=\"\">-</span> Menambahkan sumber dari setiap gambar yg diambil dari internet</p><p dir=\"ltr\"><br>\n</p><p dir=\"ltr\"><span style=\"font-size:0px\" ;=\"\">-</span> memperbaiki margin</p><p dir=\"ltr\"></p><p dir=\"ltr\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</p><p dir=\"ltr\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n</p><p dir=\"ltr\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</p>', '2025-08-10 11:03:24', '2025-08-15 11:22:55');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (369, 1, 214, 115, 4, 9, 1, 1, 1, '<p style=\"margin:0\">Waktu: 10.00-11.00</p><p style=\"margin:0\">Hasil dan Revisi:</p><p style=\"margin:0\">1. Pak Maman (Penguji 1): Korelasi antara fitur dan hasil prediksi perlu diperjelas</p><p style=\"margin:0\">2. Pak Elih (Penguji 2): Tambahkan fitur yang mempengaruhi kerusakan pada latar belakang, serta saran untuk penelitian selanjutnya.</p><p style=\"margin:0\">3. Pak Erik (Penguji 3): Tabel data dinamis perlu diperjelas karena belum menunjukkan total 50.000 data</p>', '2025-08-10 12:19:43', '2025-08-19 16:11:56');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (370, 1, 331, 115, 2, 9, 1, 1, 1, '<p style=\"margin:0\">Muhammad Andhika Triputra (2001686).<br>Teknik Elektro.<br><br>Telah melaksanakan ujian sidang Pre-Defense pada hari selasa 12 Agustus 2025, Pukul 08.00-09.00 WIB di Ruang Ketua Lab Telkom dengan dosen penguji :<br>- Bapak Dr. Aip Saripudin, M.T.<br>- Bapak Wawan Purnama, S.Pd., M.Si.<br>- Bapak Wasimudin Surya, S.T., M.T.</p><p style=\"margin:0\"><br></p>', '2025-08-10 12:22:20', '2025-08-14 00:57:49');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (371, 1, 717, 115, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Fajar Dwi Raditya (2102277), Teknik Elektro.<br><br>telah melaksanakan ujian sidang&nbsp;<i>pre-defense</i>&nbsp;pada hari Selasa, 12 Agustus 2025 pukul 10.00-11.00 WIB di Laboratorium Telekomunikasi dengan dosen penguji Bapak Dr. H. Bambang Trisno, M.SIE; Ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.; dan Bapak Didin Wahyudin, S.Pd., M.T., Ph.D.</p>', '2025-08-10 14:13:44', '2025-08-14 18:01:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (372, 1, 695, 115, 3, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamualaikum Warahmatullahi Wabaraqatuh</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 12 Agustus 2025. Untuk perbaikan dan masukan yaitu, Perbaikan kata pengantar, Jelaskan kebaruan dari penelitian, perbaiki blok diagram dan jelaskan lebih detail, tambahkan analisis dari hasil yang diperoleh,&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Perjelas gambar gambar agar dapat dibaca dengan mudah dan berikan penjelasan sebelum gambar tersebut lalu sebutkan nomor gambar,&nbsp;</span><span style=\"color: inherit; font-size: 1rem;\">koreksi konsistensi penulisan, perbaiki daftar pustaka.&nbsp;</span></p>', '2025-08-10 16:31:15', '2025-08-17 23:21:37');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (373, 1, 652, 122, 2, 9, 1, 1, 1, 'RANCANG BANGUN PURWARUPA SISTEM PARKIR OTOMATIS BERBASIS DETEKSI NIM PADA PLAT NOMOR MENGGUNAKAN METODE YOLOV8 DAN TESSERACT-OCR PADA RASPBERRY PI', '2025-08-10 17:08:15', '2025-08-18 20:44:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (374, 1, 556, 115, 3, 9, 1, 1, 1, '<p style=\"margin:0\">Muhammad Faris \'Abqari (2100659), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Selasa, 12 Agustus 2025 pukul 09.00-10.00 WIB di Ruang Ketua Laboratorium Elektronika Telekomunikasi dengan dosen penguji Bapak Dr. Ir. Dadang Lukman&nbsp;Hakim,&nbsp;M.T.; Bapak Dr. Aip Saripudin, M.T.; dan Bapak Dr. H. Bambang Trisno, M.SIE.</p>', '2025-08-10 17:35:54', '2025-08-19 08:42:16');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (375, 1, 697, 115, 2, 1, 1, 1, 1, '<p data-start=\"0\" data-end=\"305\">Alhamdulillah, pada Selasa, 12 Agustus 2025 pukul 08.00–09.00 WIB telah berlangsung sidang pra-defense skripsi di Laboratorium Elektronika Industri. Sesi berjalan lancar: presentasi disampaikan dengan tertib, diikuti tanya jawab yang fokus pada kejelasan metodologi, konsistensi istilah, serta kesiapan pengujian sistem.</p><p data-start=\"307\" data-end=\"1066\">Dalam diskusi, penguji menyampaikan beberapa catatan revisi untuk penyempurnaan naskah. Pertama, <span data-start=\"404\" data-end=\"415\">Abstrak</span> diminta memuat pernyataan tujuan penelitian secara eksplisit dan merapikan beberapa kalimat yang masih belum lengkap. Kedua, <span data-start=\"541\" data-end=\"555\">Kesimpulan</span> perlu disusun dalam bentuk poin-poin yang secara langsung menjawab tujuan penelitian. Ketiga, pada <span data-start=\"655\" data-end=\"665\">Bab II</span> terdapat kalimat yang salah/kurang tepat sehingga perlu dikoreksi sekaligus dicek konsistensi istilahnya. Selain itu, diberikan <span data-start=\"914\" data-end=\"933\">saran pengujian</span> tambahan, yaitu menjalankan dan memverifikasi sistem di komputer lain untuk memastikan performa dan kompatibilitas lintas perangkat.</p><p style=\"margin:0\">\n\n</p><p data-start=\"1068\" data-end=\"1425\" data-is-last-node=\"\" data-is-only-node=\"\">Sebagai tindak lanjut, penulis diminta menuntaskan revisi tersebut dan menyerahkan naskah perbaikan kepada pembimbing/penguji untuk verifikasi berikutnya.&nbsp; Seluruh catatan di atas menjadi dasar penyempurnaan menuju sidang berikutnya. Alhamdulillah, acara berjalan tertib dan konstruktif.</p>', '2025-08-10 17:58:48', '2025-08-12 14:37:39');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (376, 1, 746, 121, 3, 3, 1, 1, 1, '<p style=\"margin:0\">perbaikan judul yang ditambahkan \"implementasi manfaat\"</p><p style=\"margin:0\">perbaikan penulisan dan rujukan&nbsp;</p>', '2025-08-11 08:29:20', '2025-08-19 14:56:17');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (377, 1, 705, 122, 1, 9, 1, 1, 1, '<p style=\"margin:0\">Bagaimana kriteria dari performa pengujian?<br>Performa pengujian dilakukan dengan menggunakan 2 metode yaitu BLEU-1 dan BERTScore dimana BLEU-1 digunakan sebagai proses pengujian mesin penerjemahan yang umum digunakan dan BERTScore yang dinilai dapat mendekati proses evaluasi terjemahan manusia<br><br>Apa konteks dari <i>Whisper AI</i>?<br>Whisper AI digunakan dalam sistem ini sebagai <i>Automatic Speech Recognition </i>(pengenalan ucapan otomatis) yang mampu mendeteksi suara dan di transkripsikan menjadi teks dengan WER (<i>Word Error Rate) </i>hanya sebesar 12,3%<br><br>Apa saran dari kamu untuk mengimpruviasi sistem yang kamu buat agar lebih baik dari hasil terjemahan <i>Google Translate</i>?<br>Pengujian saya baru menggunakan <i>DeepL </i>versi gratis, untuk kedepan nya sistem dapat menggunakan <i>DeeL Pro </i>yang menyediakan pustaka terjemahan lebih luas<br><br>Jika akan diimplementasikan apakah harus menginstall semua software?<br>Untuk saat ini sistem yang dibuat perlu melakukan instalasi terhadap server lokal <i>Whisper AI&nbsp;</i>dan <i>VOICEVOX AI</i>, untuk penggunaan DeepL tidak perlu melakukan instalasi software karena sudah diakses menggunakan&nbsp; API<br><br>Revisi Penulisan dimana jarak spasi nya tidak konsisten 1,5 dan penulisan rumus yang dicantumkan tidak perlu ditulis ulang, cukup ditulis nomer disamping rumus dan disebutkan saja nomer rumus nya ketika mau digunakan.</p>', '2025-08-11 08:42:11', '2025-08-19 07:02:53');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (378, 1, 730, 122, 2, 3, 1, 1, 1, '<p style=\"margin:0\"><span style=\"font-size:17px\" ;=\"\">Sidang dilaksanakan pada hari kamis 14 Agustus 2025 mulak pukul 08.00 s/d 09.00</span><br>\n<span style=\"font-size:17px\" ;=\"\">00 dengan hasil sidang sebagi berikut :</span>\n<br><br><span style=\"font-size:17px\" ;=\"\">Susunan acara terdiri dari pembukaan, presentasi, Sesi Tanya Jawab (pengujian) oleh dosen penguji, penutupan</span><br>\n<span style=\"font-size:17px\" ;=\"\">Presentasi dilakukan sekitar 10 menit dan 50 menit untuk sesi tanya jawab</span><br>\n<span style=\"font-size:17px\" ;=\"\">Hasil penelitian \"Prediksi Loyalitas Pelanggan Tempat Cuci Kendaraan Menggunakan Metode Naive Bayes\" yaitu</span><br>\n<span style=\"font-size:17px\" ;=\"\">1. Perancangaan sistem prediksi dan integrasi dengan antarmuka pengguna grafis (GUI) berhasil dilakukan</span><br>\n<span style=\"font-size:17px\" ;=\"\">2. Validitas sistem diuji menggunakan metode black box dengan semua fitur berfungsi dengan baik</span><br>\n<span style=\"font-size:17px\" ;=\"\">3. Akurasi naive bayes 94.74% , presisi 100%, dan recall 93.3% </span><br>\n<span style=\"font-size:17px\" ;=\"\">4. Faktor yang dominan mempengaruhi loyalitas pelanggan yaitu kepuasan pelanggan, harga, dan kualitas layanan</span>\n<br><br><span style=\"font-size:17px\" ;=\"\">Hasil Masukan (revisi) dari dosen penguji</span><br>\n<span style=\"font-size:17px\" ;=\"\">1. Dosen penguji Ibu hj Arjuni :</span><br>\n<span style=\"font-size:17px\" ;=\"\">a. Perbaikan tanda titik pada halaman abstrak</span><br>\n<span style=\"font-size:17px\" ;=\"\">b. Pada bagian akhir Latar belakang masalah jangan langsung kesimpulan </span><br>\n<span style=\"font-size:17px\" ;=\"\">c. Perjelas gambar</span><br>\n<span style=\"font-size:17px\" ;=\"\">d. Pelajar naive bayes dan algoritma machine learning yang lain</span><br>\n<span style=\"font-size:17px\" ;=\"\">e. Lakukan penyeimbangan dataset</span><br>\n<span style=\"font-size:17px\" ;=\"\">f. Perbaiki implikasi</span>\n<br><br><span style=\"font-size:17px\" ;=\"\">2. Dosen penguuji Pak enjang</span><br>\n<span style=\"font-size:17px\" ;=\"\">a. Tertukan urutan pada rumusan masalah,tujuan antara no 2 dan 3</span><br>\n<span style=\"font-size:17px\" ;=\"\">3. Dosen penguji Pak Dadaang</span><br>\n<span style=\"font-size:17px\" ;=\"\">a. Masukan solusi cara peningkatan loyalitas untuk tiap parameter</span><br>\n<span style=\"font-size:17px\" ;=\"\">b. Perbaiki Penulisan tabel</span><br>\n<!--/data/user/0/com.samsung.android.app.notes/files/clipdata/clipdata_bodytext_250818_224615_940.sdocx--></p>', '2025-08-11 08:43:11', '2025-08-18 22:46:52');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (379, 1, 539, 122, 3, 3, 1, 1, 1, '<p class=\"MsoNormal\"><o:p>&nbsp;</o:p></p><p class=\"MsoNormal\">Sidang tertutup dilaksanakan pada tanggal 14 Agustus 2025\npukul 09.00-10.00, dihadiri oleh dosen penguji:<o:p></o:p></p><p class=\"MsoNormal\">1. Bapak Prof. Dr. Enjang A. Juanda, M.Pd., M.T.<o:p></o:p></p><p class=\"MsoNormal\">2. Bapak Dr. Dadang Lukman Hakim, M.T.<o:p></o:p></p><p class=\"MsoNormal\">2. ibu Ir. Hj. Arjuni Budi Pantjawati, M.T.<o:p></o:p></p><p class=\"MsoNormal\">Beberapa masukan setelah sidang dilaksanakan, diantaranya:<o:p></o:p></p><p class=\"MsoNormal\">1. Sederhanakan judul dan kalimat pada skripsi<o:p></o:p></p><p class=\"MsoNormal\">2. Perbaiki penulisan seperti kata asing dimiringkan(italic)\ndan lain lain<o:p></o:p></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\">3. Pisahkan gambar agar memperjelas penjelasan<o:p></o:p></p>', '2025-08-11 08:43:55', '2025-08-16 22:13:58');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (380, 1, 733, 121, 3, 1, 1, 1, 1, '<p data-start=\"110\" data-end=\"139\"><strong data-start=\"110\" data-end=\"137\">Laporan Hasil Prasidang 15 Agustus 2025</strong></p><p style=\"margin:0\">\n</p><ol data-start=\"141\" data-end=\"1005\">\n<li data-start=\"141\" data-end=\"547\">\n<p data-start=\"144\" data-end=\"547\"><strong data-start=\"144\" data-end=\"162\">Dr. H. Bambang Trisno, MSIE.</strong><br data-start=\"162\" data-end=\"165\">\nPenguji menyarankan agar pengujian sistem dilengkapi dengan tingkat keberhasilan yang disajikan dalam bentuk statistik dan tabel, sehingga dapat diperoleh data yang lebih konkret mengenai performa alat. Hasil pengujian tidak hanya ditampilkan dalam bentuk keterangan “berhasil” atau “tidak berhasil”, tetapi juga dilengkapi dengan persentase atau indikator kuantitatif lainnya.</p>\n</li>\n<li data-start=\"549\" data-end=\"787\">\n<p data-start=\"552\" data-end=\"787\"><strong data-start=\"552\" data-end=\"571\">Dr. Agus Heri Setya, M.T.</strong><br data-start=\"571\" data-end=\"574\">\nPada sesi tanya jawab, penguji menekankan bahwa mahasiswa perlu memperdalam pemahaman teori dasar mengenai teknologi RFID, termasuk prinsip kerja RFID serta mekanisme validasi data antara sistem dan RFID tag.</p>\n</li>\n<li data-start=\"789\" data-end=\"1005\">\n<p data-start=\"792\" data-end=\"1005\"><strong data-start=\"792\" data-end=\"808\">Dr. Elih Mulyana, M.Si.</strong><br data-start=\"808\" data-end=\"811\">\nDari segi penulisan, penguji menilai perlu adanya keserasian antara rumusan masalah, pembahasan pada Bab IV, dan kesimpulan pada Bab V, sehingga alur penelitian menjadi konsisten dan logis.</p></li></ol>', '2025-08-11 10:10:13', '2025-08-15 16:31:08');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (381, 1, 610, 121, 2, 1, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</p><p style=\"margin:0\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 07 Agustus 2025.</p><p style=\"margin:0\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:<br>1. Penulisan pada skripsi saya terutama pada tanda koma, typo pada beberapa kalimat.<br>2. Tabel yang dibikin kurang tepat dicantumkan pada bab yang seharusnya<br>3. Perubahan Judul&nbsp;<br>4. Lampirannya kurang lengkap</p><div><div>Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</div><div><br></div><div>Demikian laporan hasil sidang skripsi ini saya sampaikan.</div><div><br></div><div>Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</div></div>', '2025-08-11 11:29:01', '2025-08-20 15:07:13');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (382, 1, 631, 118, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Link hasil revisi:</p><p style=\"margin:0\"><a href=\"https://drive.google.com/drive/folders/1NztdF9Xfxz-gabGe_fZriV7D3XjBJvRY?usp=sharing\" target=\"_blank\">https://drive.google.com/drive/folders/1NztdF9Xfxz-gabGe_fZriV7D3XjBJvRY?usp=sharing</a></p><p style=\"margin:0\">Perbaikan:</p><p style=\"margin:0\">1. Perbaikan penulisan</p><p style=\"margin:0\">2. Perubahan pada bab 1</p><p style=\"margin:0\">3. Bab 2 dilengkapi</p><p style=\"margin:0\">4. Penambahan narasi yang lebih lengkap pada gambar dan grafik</p><p style=\"margin:0\">5. Bab 5 diubah untuk menyamai rumusan masalah</p>', '2025-08-11 13:12:27', '2025-08-22 11:21:30');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (383, 1, 739, 122, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Sidang sudah selesai dilaksanakan. Laporan dalam proses perbaikan</p>', '2025-08-11 18:36:52', '2025-08-16 18:01:53');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (384, 1, 624, 123, 1, 10, 1, 1, 1, '<p style=\"margin:0\">Afdal Maulana (2101613), Pendidikan Teknik Otomasi Industri dan Robotika.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Jumat, 15 Agustus 2025 Perpustakaan FPTE dengan dosen penguji Bapak Roer Eka Pawinanto, S.Pd., M.Sc., Ph. D., Bapak Wawan Purnama, S.Pd., M.Si. dan Bapak Ibnu Hartopo, M.Pd.</p>', '2025-08-12 10:34:40', '2025-08-20 15:27:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (385, 1, 637, 123, 2, 10, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan Pre defense pada tanggal 15 Agustus 2025 jam 08.00-09.00 wib</p>', '2025-08-12 13:36:49', '2025-08-15 16:24:15');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (386, 1, 621, 123, 3, 10, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum Wr. Wb..</p><p style=\"margin:0\">Selamat sore Bapak dan Ibu..&nbsp;</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">Izin Bapak dan Ibu, saya kemarin sudah menyelesaikan sidang pre defense saya.. Dari pre defense tersebut saya mendapatkan beberapa rekomendasi.. Rekomendasi tersebut berupa penulisan skripsi saya. Oleh karena itu, berikut saya lampirkan mengenai hasil pre defense kemarin dan draft skripsi yang telah diperbarui..</p><p style=\"margin:0\">https://drive.google.com/drive/folders/1DLnXPd-_cg6wR2Ne3fKizQx3AAbpwOgR?usp=drive_link</p><p style=\"margin:0\">Terima kasih banyak Bapak dan Ibu..</p><p style=\"margin:0\">Wassalamu\'alaikum Wr. Wb..</p>', '2025-08-12 16:41:17', '2025-08-19 16:35:04');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (387, 1, 431, 123, 4, 10, 1, 1, 1, '<p style=\"margin:0\">Telah dilaksanakan predefense pada tanggal 15 Agustus jam 10.00 sd 11.00</p>', '2025-08-12 19:59:29', '2025-08-16 08:16:23');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (388, 1, 678, 123, 4, 11, 1, 1, 1, '<div>Assalamualaikum Warahmatullahi Wabaraqatuh</div><div>Saya telah melaksanakan sidang Pre-Defense pada tanggal 15 Agustus 2025. Untuk perbaikan dan masukan yaitu sebagai berikut :</div><div>1. font referensi dan penulisan harus sesuai</div><div>2. pemberian paragraf penjelas sebelum menampilkan gambar</div><div>3.penambahan nomor untuk persamaan rumus</div><div>4. daftar isi, daftar gambar, daftar tabel dan lampiran tidak ditulis bold</div>', '2025-08-12 21:31:01', '2025-08-20 20:31:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (389, 1, 747, 122, 5, 3, 1, 1, 1, '<p style=\"margin:0\">Rancang Bangun&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Sistem Irigasi Tetes Otomatis Berbasis Arduino Uno untuk Tanaman Sansevieria di Dalam Ruangan.</span></p><div class=\"row\"></div>', '2025-08-13 05:50:25', '2025-08-20 12:00:05');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (390, 1, 267, 122, 6, 10, 1, 1, 1, '<p style=\"margin:0\"><br><a href=\"https://docs.google.com/document/d/1YegNIYDZlyepMAVZj7-hqb4fDZsyNAFG/edit?usp=sharing&amp;ouid=110677122083565704153&amp;rtpof=true&amp;sd=true\" target=\"_blank\">Draft Skripsi Rifqi Hanif Naufal 1808109</a></p>', '2025-08-21 14:59:36', '2025-08-22 19:33:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (391, 1, 690, 125, 1, 3, 1, 1, 1, '<p style=\"margin:0\">Nijamuhdin Hamdan Amjad (2107897), Teknik Elektro.</p><p style=\"margin:0\"><br></p><p style=\"margin:0\">telah melaksanakan ujian sidang pre-defense pada hari Jum\'at, 07 November 2025 pukul 07.00-08.00 WIB di Laboratorium Elektronika Telekomunikasi dengan dosen penguji Bapak Dr. Aip Saripudin, S.Si., M.T.; Bapak Dr. Ir. H. Dadang Lukman Hakim, M.T.; dan Bapak Dr. Ir. Maman Somantri, S.Pd., M.T.;</p>', '2025-10-23 07:47:48', '2025-11-10 05:31:43');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (392, 1, 734, 125, 4, 3, 1, 1, 1, '<p style=\"margin:0\">Assalamu\'alaikum</p><p style=\"margin:0\">Lapor, saya sudah mengikuti Pre-Defence pada Hari Jum\'at tanggal 7 November 2025.</p><p style=\"margin:0\">Laporan Selesai.&nbsp;</p>', '2025-10-28 07:46:52', '2025-11-19 12:42:47');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (393, 1, 729, 125, 3, 3, 1, 1, 1, '<p style=\"margin:0\">Lapor saya Dika Abdul Wahab dengan NIM 2102560 sudah melaksanakan predefense dengan judul Analisis Tekno-Ekonomi Deployment 5G New Radio Frekuensi 3.5 GHz di Kawasan Urban Kota Cirebon Menggunakan Simulasi Atoll dan di uji oleh Bapak Tommi Hariyadi, Bapak Agus Heri Setya Budi, dan Bapak Didin Wahyudin di Gedung A PFTI Lab Telkom lantai 5 pada Pukul 09:00-10:00. Ada revisi dibagian penulisan abstrak, Gambar yang dipakai harus dibuat sendiri jika tidak ada referensi, serta pembuatan rumus perhitungan pengujian yang perlu dirapihkan dan dibuat berurutan.</p>', '2025-10-31 11:24:58', '2025-12-21 19:09:27');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (394, 1, 755, 124, 1, 2, 1, 1, 1, '<p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Assalamu\'alaikum Warahmatullahi\nWabarakatuh.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Saya telah melaksanakan sidang Pre-Defense\npada tanggal 07 November 2025.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Selama proses sidang, dosen penguji\nmemberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">1. Abstrak<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">2. Bab 2 penambahan sub bab mekanisme\npembahasan busur api<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">3. Bab 3 merubah metode penelitian jadi Komparatif\ndeskriptif analitik<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">4. Bab 4 Validasi Hasil Pengujian Terhadap\nStandar Kelayakan Operasi<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">5. Pembetulan tabel ke halaman selanjutnya<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">6. Menambahkan tahun pada standar yang\ndigunakan<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">7. Penambahan diskusi penyebab fisik\ndegradasi pada PMT<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Saya mengucapkan terima kasih yang\nsebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu,\ntenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan\nkritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di\nmasa mendatang.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Demikian laporan hasil sidang skripsi ini\nsaya sampaikan.<o:p></o:p></span></p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\"><span lang=\"IN\" style=\"font-size:12.0pt;line-height:107%;\nfont-family:&quot;Times New Roman&quot;,serif\">Wassalamu\'alaikum Warahmatullahi\nWabarakatuh.<o:p></o:p></span></p>', '2025-11-01 23:14:15', '2025-11-21 10:26:02');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (395, 1, 756, 124, 2, 2, 1, 1, 1, '<p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Assalamu\'alaikum\nWarahmatullahi Wabarakatuh.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Saya\ntelah melaksanakan sidang Pre-Defense pada tanggal 07 November 2025.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Selama\nproses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk\nskripsi saya, antara lain:<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">1.\nAbstrak<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">2.\nBab 4 Temuan dan Pembahasan<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">-Tabel\npada temuan Sub-bab 4.1.2, yaitu tabel 4.2, table 4.3, table 4.4 dan tabel 4.5.\nData pengujian tahanan isolasi pada tahun 2024-2025<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">3.\nBab 3 Metode Penelitian<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">-\nMerubah metode penelitian deskriptif kuantitatif menjadi kuantitatif deskripsif\ndenagn pendekatan <i>field research<o:p></o:p></i></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">4.\nmenambahkan tahun pada standar yang digunakan<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">5.\nBab 2 Penelitian Terdahulu<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">-\nmenambahkan perbandingan hasil studi dengan penelitian terdahulu<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">6.\nBab 2 landasan teori pada Sub-bab 2.5.3<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">-menambahkan\nbahasan teori mengenai mekanisme degradasi pada tahanan kontak dan tahanan\nisolasi pada PMT.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Saya\nmengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji\nyang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya\ntulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk\npengembangan keilmuan saya di masa mendatang.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Demikian\nlaporan hasil sidang skripsi ini saya sampaikan.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">&nbsp;</span></p><p style=\"margin:0\">\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n</p><p class=\"MsoNormal\" style=\"text-align:justify\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Wassalamu\'alaikum\nWarahmatullahi Wabarakatuh.<o:p></o:p></span></p>', '2025-11-01 23:16:27', '2025-11-21 10:36:00');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (396, 1, 724, 124, 2, 1, 1, 1, 1, '<p style=\"text-align: justify; \">Assalamu’alaikum Warahmatullahi Wabarakatuh.</p><p style=\"text-align: justify; \">Saya telah melaksanakan sidang Pre-Defense pada tanggal 7 November 2025.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Selama proses sidang berlangsung, para dosen penguji memberikan berbagai masukan konstruktif terhadap skripsi saya. Adapun beberapa poin perbaikan yang disarankan antara lain:</span></p><p style=\"text-align: justify; \">1. Melengkapi lampiran datasheet setiap sensor.</p><p style=\"text-align: justify; \">2. Memperbaiki penulisan pada tabel.</p><p style=\"text-align: justify; \">3. Melengkapi dan menyempurnakan lampiran tampilan spreadsheet serta website.</p><p style=\"text-align: justify; \">4. Memperbaiki penulisan referensi, terutama pada judul yang dikutip.</p><p style=\"text-align: justify; \">5. Memberi label pada setiap komponen pada gambar skematik.</p><p style=\"text-align: justify; \">6. Menambahkan uraian mengenai karakteristik tempat penelitian secara lebih rinci.</p><p style=\"text-align: justify; \">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah meluangkan waktu, tenaga, dan pemikiran untuk memberikan evaluasi terhadap karya tulis ilmiah saya.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Segala masukan dan kritik yang membangun akan menjadi bahan berharga bagi pengembangan pengetahuan dan kemampuan saya di masa mendatang.</span></p><p style=\"text-align: justify; \">Demikian laporan hasil sidang Pre-Defense ini saya sampaikan.&nbsp;<span style=\"color: inherit; font-size: 1rem;\">Atas perhatian dan bimbingannya, saya ucapkan terima kasih.</span></p><p style=\"text-align: justify; \"><span style=\"color: inherit; font-size: 1rem;\">Wassalamu’alaikum Warahmatullahi Wabarakatuh.</span></p>', '2025-11-03 08:59:31', '2025-11-13 14:53:11');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (397, 1, 731, 124, 1, 1, 1, 1, 1, '<p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Assalamu\'alaikum Warahmatullahi Wabarakatuh.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Saya telah melaksanakan sidang Pre-Defense pada tanggal 07 November 2025.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\"><br></font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Selama proses sidang, dosen penguji memberikan berbagai masukan konstruktif untuk skripsi saya, antara lain:</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">1. Bab 2 Tinjauan Pustaka</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan kalimat pengantar sebelum tabel 2.2 Penelitian Terdahulu disajikan.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan caption pada tabel penelitian terdahulu.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">2. Bab 4 Hasil dan Pembahasan:</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menyebutkan kembali/menjelaskan tabel dalam paragraf.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">3. Bab 5 Simpulan dan Hasil:</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Buat kesimpulan menjadi 2 paragraf, menyesuaikan dengan tujuan penelitian.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">4. Bab 2 Tinjauan Pustaka</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan penjelasan mengenai mata pelajaran.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan teori persepsi dan motivasi belajar.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">5. Bab 3 Metode Penelitian</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Mengubah metode menjadi mixed methods.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">6. Lampiran</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan data observasi aktivitas siswa.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan data wawancara.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan langkah pembuatan kuis.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">- Menambahkan silabus.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\"><br></font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Saya mengucapkan terima kasih yang sebesar-besarnya kepada seluruh dosen penguji yang telah memberikan waktu, tenaga, dan pemikiran untuk mengevaluasi karya tulis ilmiah saya. Masukan dan kritik yang membangun akan sangat berharga untuk pengembangan keilmuan saya di masa mendatang.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\"><br></font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Demikian laporan hasil sidang skripsi ini saya sampaikan.</font></p><p style=\"margin:0\"><font color=\"#000000\" style=\"background-color: rgb(255, 255, 255);\">Wassalamu\'alaikum Warahmatullahi Wabarakatuh.</font></p>', '2025-11-03 09:17:17', '2025-11-19 17:03:56');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (398, 1, 810, 124, 2, 11, 1, 1, 1, '<p style=\"margin:0\">Sudah megirimkan soft file artikel yang sudah terbit ke dosen penguji</p>', '2025-11-03 14:04:24', '2025-12-02 09:54:44');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (399, 1, 819, 124, 3, 11, 1, 1, 1, '<p style=\"margin:0\">sudah memberikan draft artikel dan sudah diberi penilaian&nbsp;</p>', '2025-11-03 14:36:19', '2026-01-01 20:14:20');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (400, 1, 658, 125, 4, 9, 1, 1, 1, '<p data-start=\"191\" data-end=\"226\"><strong data-start=\"191\" data-end=\"226\">Laporan Pelaksanaan Pre-Defense</strong></p><p data-start=\"228\" data-end=\"541\">Telah dilaksanakan <em data-start=\"247\" data-end=\"260\">pre-defense</em> skripsi dengan judul <strong data-start=\"282\" data-end=\"439\">“Perancangan dan Implementasi Equalizer 20 Channels Berbasis Semantic Menggunakan Natural Language Processing dan Machine Learning pada Platform Android”</strong> pada <strong data-start=\"445\" data-end=\"472\">Jumat, 07 November 2025</strong>, pukul <strong data-start=\"480\" data-end=\"499\">10.00–11.00 WIB</strong>, bertempat di <strong data-start=\"514\" data-end=\"540\">Ruang Ketua Lab Telkom</strong>.</p><p data-start=\"543\" data-end=\"715\"><em data-start=\"543\" data-end=\"556\">Pre-defense</em> dilaksanakan di bawah bimbingan <strong data-start=\"589\" data-end=\"629\">Ir. Hj. Arjuni Budi Pantjawati, M.T.</strong>, dengan dosen penguji <strong data-start=\"652\" data-end=\"679\">Dr. Aip Saripudin, M.T.</strong> dan <strong data-start=\"684\" data-end=\"715\">Iwan Kustiawan, M.T., Ph.D.</strong></p><p data-start=\"717\" data-end=\"767\">Adapun hasil <em data-start=\"730\" data-end=\"743\">pre-defense</em> adalah sebagai berikut:</p><ol data-start=\"768\" data-end=\"1301\">\n<li data-start=\"768\" data-end=\"1052\">\n<p data-start=\"771\" data-end=\"1052\"><strong data-start=\"771\" data-end=\"811\">Masukan dari Dr. Aip Saripudin, M.T.</strong> berupa revisi teknis dan substansi, meliputi perbaikan pada bagian rumusan masalah, tujuan, dan batasan masalah, penomoran persamaan, penyajian tabel, penulisan notasi desimal, serta perumusan simpulan agar lebih ringkas dan <em data-start=\"1037\" data-end=\"1051\">to the point</em>.</p>\n</li>\n<li data-start=\"1053\" data-end=\"1301\">\n<p data-start=\"1056\" data-end=\"1301\"><strong data-start=\"1056\" data-end=\"1100\">Masukan dari Iwan Kustiawan, M.T., Ph.D.</strong> bersifat <em data-start=\"1110\" data-end=\"1127\">future research</em> dan pengembangan lanjutan, antara lain pengujian sistem pada perangkat selain yang digunakan saat ini serta pengembangan lebih lanjut pada konsep <em data-start=\"1274\" data-end=\"1300\">semantic audio equalizer</em>.</p>\n</li>\n</ol><p style=\"margin:0\">\n\n\n\n\n</p><p data-start=\"1303\" data-end=\"1361\">Revisi telah dilakukan sesuai dengan arahan dosen penguji.</p>', '2025-11-04 11:08:26', '2025-12-14 21:02:15');
INSERT INTO `arsys_event_applicant_defense` (`id`, `defense_model_id`, `research_id`, `event_id`, `session_id`, `space_id`, `status`, `confirmed`, `publish`, `report`, `created_at`, `updated_at`) VALUES (401, 1, 740, 129, 2, 2, 1, 1, 1, '<p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Assalamu\'alaikum Warahmatullahi\nWabarakatuh.<o:p></o:p></span></p><p class=\"MsoNormal\" style=\"text-align:justify;line-height:150%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Saya telah melaksanakan sidang\nPre-Defense pada tanggal 12 Desember 2025. Selama proses sidang, dosen penguji\nmemberikan berbagai masukan untuk skripsi saya, antara lain:<o:p></o:p></span></p><p class=\"MsoListParagraphCxSpFirst\" style=\"text-align:justify;text-indent:-18.0pt;\nline-height:150%;mso-list:l2 level1 lfo1\"><!--[if !supportLists]--><b><span style=\"font-family:&quot;Times New Roman&quot;,serif;mso-fareast-font-family:&quot;Times New Roman&quot;\">1.<span style=\"font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-weight: normal; font-stretch: normal; font-size: 7pt; line-height: normal; font-family: &quot;Times New Roman&quot;;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n</span></span></b><!--[endif]--><b><span style=\"font-family:&quot;Times New Roman&quot;,serif\">Abstrak<o:p></o:p></span></b></p><p class=\"MsoListParagraphCxSpMiddle\" style=\"margin-left:49.65pt;mso-add-space:\nauto;text-align:justify;text-indent:-14.2pt;line-height:150%;mso-list:l1 level1 lfo2\"><!--[if !supportLists]--><span style=\"font-family:Symbol;mso-fareast-font-family:Symbol;mso-bidi-font-family:\nSymbol\">·<span style=\"font-variant-numeric: normal; font-variant-east-asian: norma