INSERT INTO `arsys_research` (`id`, `milestone_id`, `academic_year_id`, `type_id`, `student_id`, `code`, `status`, `title`, `abstract`, `file`, `created_at`, `updated_at`) VALUES (829, 1, 8, 3, 1225, 'SK-2204265-3', NULL, 'Analisis Performa Setting Relai Diferensial Pada Generator dan Transformator di PLTU Pelabuhan\nRatu Berbasis Fuzzy Logic Algorithm', 'Penelitian ini bertujuan untuk menganalisis dan mengevaluasi performa setting relai diferensial pada komponen utama sistem tenaga, yaitu generator dan transformator, di Pembangkit Listrik Tenaga Uap (PLTU) Pelabuhan Ratu dengan mengintegrasikan Algoritma Logika Fuzzy.  Kinerja proteksi diferensial yang andal sangat krusial untuk menjaga stabilitas operasional dan mencegah kerusakan fatal akibat gangguan internal, terutama saat terjadi kondisi arus inrush magnetisasi pada transformator atau fluktuasi beban transien pada generator.', 'https://drive.google.com/file/d/12qk0RMfLNqkcEZFE1U0M7VwFlQwFe038/view?usp=drivesdk', '2025-11-06 15:04:37', '2025-11-06 15:04:37');
