INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (58, 36, 124, '<p style=\"margin:0\">Izin mengonfirmasi pak, setelah berdiskusi dengan beliau, beliau keberatan menjadi dosen pembimbing saya dengan judul yang saya ajukan, beliau menyarankan saya untuk mencari dosen yang lain, atau jika ingin tetap beliau menjadi dosen pembimbing saya, saya harus mengikuti topik yang beliau pilih, sedangkan saya sudah selesai mengolah data penelitian, dan memasuki penulisan bab terakhir. Namun saya tidak menutup kemungkinan apabila topik saya harus dikembangkan lagi. Solusi nya saya harus bagaimana ya pak? Mohon bantuannya, pak</p>', '2023-10-05 03:25:07', '2023-10-05 03:25:07');
