INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (466, 262, 8, '<p style=\"margin:0\">- Latar belakang yang disampaikan tidak mendukung penelitian yang akan dilakukan.<br>- Tujuan penelitian belum jelas.<br>- Apakah penelitian ini fokus ke optimal control? (baca referensi tentang kontrol optimal)</p>', '2023-11-09 20:12:51', '2023-11-09 20:12:51');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (467, 254, 8, '<p style=\"margin:0\">- Pada latar&nbsp; belakang belum memunculkan algoritma yang akan dikembangkan &amp; alasan kenapa algoritma yg sdh ada itu perlu dikembangkan.<br>- Tujuan penelitian belum fokus &amp; jelas.<br>- novelty?</p><p style=\"margin:0\"><br></p>', '2023-11-10 09:52:56', '2023-11-10 09:52:56');
