INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (600, 207, 14, '<p style=\"margin:0\">-Tambahkan Studi litelatur terkait penelitian yang relevan dan jelaskan hasil studi litelatur apa yg akan dibuat pada penelitian kali ini</p><p style=\"margin:0\">-referensi tidak disitasi pada kalimat</p>', '2024-02-13 10:28:07', '2024-02-13 10:28:07');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (601, 290, 14, '<p style=\"margin:0\">-Studi litelatur belum menjelaskan penelitian yang relevan</p><p style=\"margin:0\">-tambahkan studi litelatur mengenai penelitian sebelumnya dalam waktu 5 tahun terakhir</p><p style=\"margin:0\">-persingkat jadwal yang dijabarkan</p><p style=\"margin:0\">-jelaskan lebih detail dan sertakan diagram pada fitur produk</p>', '2024-02-13 10:30:18', '2024-02-13 10:30:18');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (602, 325, 14, '<p style=\"margin:0\">Bedakan sub bab sesuai dengan format&nbsp;<br>ex : Pada bagian pendahuluan</p><p style=\"margin:0\">A. Latar belakang dan rumusan permasalahan yang akan diteliti<div>B. Pendekatan pemecahan masalah</div><div>C. State of the art dan kebaruan</div><div>D. Peta jalan (road map) penelitian 5 tahun kedepan</div></p>', '2024-02-13 10:40:53', '2024-02-13 10:40:53');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (603, 324, 14, '<p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\">Bedakan sub bab sesuai dengan format&nbsp;<br>ex : Pada bagian pendahuluan</p><p style=\"margin-right: 0px; margin-bottom: 0px; margin-left: 0px;\">A. Latar belakang dan rumusan permasalahan yang akan diteliti</p><div>B. Pendekatan pemecahan masalah</div><div>C. State of the art dan kebaruan</div><div>D. Peta jalan (road map) penelitian 5 tahun kedepan</div>', '2024-02-13 10:41:28', '2024-02-13 10:41:28');
