INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (628, 325, 205, '<p style=\"margin:0\">Assalamualaikum wr wb.<br>Selamat Siang bapak Erik, terimakasih banyak atas koreksi yang diberikan selama beberapa hari kemarin. Mohon maaf mengganggu akhir pekan bapak. Izin memberikan revisi Proposal Skripsi yang sudah direvisi sesuai arahan bapak pada <a href=\"https://drive.google.com/file/d/1exG5wDNBU-mDasJfEPGlIUhn7lthLexK/view?usp=sharing\" target=\"_blank\">Revisi 1</a>. File juga sudah saya tambahkan di google drive yang ada. Semoga sesuai dengan yang dimaksudkan. Jika ada tambahan saya siap mengerjakan.&nbsp;<br><br>Salam hangat,<br>M. Farhan Nurpratama<br></p>', '2024-02-24 13:03:33', '2024-02-24 13:03:33');
