INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (971, 479, 14, '<p style=\"margin:0\">1. latar belakang diringkas, untuk penelitian sebelumnya yg relevan disimpan di bagian&nbsp;Pendekatan Pemecahan Masalah.<br>2. alat ini berupa robot berpindah? atau hanya alat yg dapat mengeluarkan pupuk? jelaskan lebih detail diringkasan alat</p>', '2024-09-19 14:55:01', '2024-09-19 14:55:01');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (972, 480, 14, '<p style=\"margin:0\">1. ringkasan diperjelas, cukup jelaskan penelitian yg akan dibuat tentang apa dan bagaimana.<br>2.&nbsp;<span style=\"color: rgb(0, 0, 0); font-family: Cambria, serif; font-size: 12pt; font-weight: 700; white-space-collapse: preserve;\">Pendekatan Pemecahan Masalah </span><span style=\"color: rgb(0, 0, 0); font-family: Cambria, serif; font-size: 12pt; white-space-collapse: preserve;\">jelaskan penelitian sebelumnya yang relevan \n3. state of the art dan keterbaruan menjadi subbab yg sama</span></p>', '2024-09-19 14:58:18', '2024-09-19 14:58:18');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (973, 483, 14, '<p style=\"margin:0\">1. STATE OF ART DAN KEBARUAN blm muncul<br>2. sitasi dibuat dalam format&nbsp;Vancouver</p>', '2024-09-19 15:00:50', '2024-09-19 15:00:50');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (974, 485, 14, '<p style=\"margin:0\">A. Latar belakang dan rumusan permasalahan yang akan diteliti</p><p style=\"margin:0\"><span style=\"color: inherit; font-size: 1rem;\">B. Pendekatan pemecahan masalah</span></p><p style=\"margin:0\">C. State of the art dan kebaruan<br><br>perbaiki 3 subba diatas, masih kurang jelas arah penjelasannya</p>', '2024-09-19 15:04:54', '2024-09-19 15:04:54');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (975, 485, 14, '<p style=\"margin:0\">pada bagian ringkasan diperjelas lagi apa yang akan dibuat. Kenapa harus simulasi?<br><br>penelitian ini fokus ke turretnya atau ke sistem pemantuan dari pengolahan gambarnya? karna itu 2 bidang berbeda.<br><br>jika fokus ke pemantauan memalaui pengolahan gambar berbasis AI, tidak perlu melalui simulasi MATLAB atau simulink. fokus dibidang visi komputernya dan cari tau data yang dibutuhkan untuk menggerakan turret mengarah ke object yang dideteksi apa dan jenis ancaman apa saja yang bisa diklasifikasikan sebagai ancaman.</p>', '2024-09-19 15:08:46', '2024-09-19 15:08:46');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (976, 487, 14, '<p style=\"margin:0\">akses masih terkunci</p>', '2024-09-19 15:10:36', '2024-09-19 15:10:36');
