INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1060, 460, 14, '<p style=\"margin:0\">Pendahuluan penelitian tidak lebih dari 1000 kata yang terdiri dari:</p><p style=\"margin:0\">A. Latar belakang dan rumusan permasalahan yang akan diteliti</p><p style=\"margin:0\">B. Pendekatan pemecahan masalah</p><p style=\"margin:0\">C. State of the art dan kebaruan</p><p style=\"margin:0\">D. Peta jalan (road map) penelitian 5 tahun kedepan</p><p style=\"margin:0\">E. Sitasi disusun dan ditulis berdasarkan sistem nomor sesuai dengan urutan</p><p style=\"margin:0\">pengutipan, mengikuti format Vancouver<br><br>bagi menjadi subbab2 diatas</p>', '2024-09-24 17:02:52', '2024-09-24 17:02:52');
