INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1222, 419, 403, '<p style=\"margin:0\">Assalamualaikum Wr. Wb mohon maaf mengganggu waktunya saya Daffa Faisal Mufid dengan NIM 2003348 izin bertanya pak, tdi saya buka arsys tetapi status milestonenya freze pre-defense kemudian saya tidak sengaja menekan renew itu bagaimana ya pak. Terimakasih</p><p style=\"margin:0\"><br></p>', '2024-12-24 06:14:51', '2024-12-24 06:14:51');
