INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1228, 419, 403, '<p style=\"margin:0\">Assalamualaikum Wr.Wb selamat pagi, mohon maaf mengganggu waktunya, minggu kemarin status pada milestonenya in progres tetapi pas saya cek minggu ini statusnya frezee, izin bertanya pak untuk status milestonenya frezee itu bagaimana ya pak kemudian kemarin tidak sengaja menekan renew jadi bagaimana yaa pak. Terimakasih</p>', '2024-12-25 09:02:18', '2024-12-25 09:02:18');
INSERT INTO `arsys_research_remark` (`id`, `research_id`, `discussant_id`, `message`, `created_at`, `updated_at`) VALUES (1229, 574, 11, '<p style=\"margin:0\">Secara umum untuk proposal pada prinsipnya OK. Mengenai teknis penulisan dan masalah instrumen pengambilan data bisa didiskusikan saat bimbingan. Termasuk judul yang fixed dilihat lagi berdasarkan permasalahan dan data yang diperoleh dari lapangan. Tks.</p>', '2024-12-26 09:01:08', '2024-12-26 09:01:08');
