INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (21, 53, 36, 113, 1, 'Research discussion and consultation', '<p>Discuss and consult with supervisors regarding Abstract, Introduction, Methods, Results and Discussion, Conclusions according to journal format.<br></p>', NULL, NULL, NULL, '2023-11-08 13:42:35', '2023-11-08 19:42:35');
INSERT INTO `arsys_research_supervise` (`id`, `research_id`, `supervisor_id`, `threader_id`, `status`, `topic`, `message`, `read`, `share`, `date_of_meeting`, `created_at`, `updated_at`) VALUES (22, 17, 19, 65, NULL, 'Review Artikel ', '<p><a href=\"https://drive.google.com/file/d/1i_UD_9X8exyHmw3TEKgPVShrbwZY_Pvo/view?usp=drive_link\" target=\"_blank\">https://drive.google.com/file/d/1i_UD_9X8exyHmw3TEKgPVShrbwZY_Pvo/view?usp=drive_link</a><br></p>', NULL, NULL, NULL, '2023-10-22 11:37:07', '2023-10-22 11:37:07');
